/// Run the standard migrated namelist path while deriving every active source
/// branch option from the post-`read_nl` prepare state, and optionally generate
/// the final `Get_Contain(0)` domain containment file before post-processing.
pub fn run_mkgrd_refine_loop_namelist_with_derived_migrated_executor_and_final_domain_contain_and_prepare_hook<
    'a,
    F,
>(
    namelist_source: impl AsRef<Path>,
    workdir: impl AsRef<Path>,
    source_grid: MkgrdRefinePrepareSourceGridOptions<'a>,
    calculated_refine: Option<(&'a [Vec<i32>], AreaJudgeSourceBounds)>,
    is_in_domain: Option<&'a [Vec<i32>]>,
    seaorland: &'a [Vec<i32>],
    landtypes_global: &'a [Vec<i32>],
    num_vertex: usize,
    maxlc: i32,
    refine_executor: MkgrdRefineLoopWorkingStateExecutor,
    contain_options: Option<MkgrdFinalDomainContainOptions<'_>>,
    postproc_options: Option<MkgrdFinalDomainPostprocOptions<'_>>,
    after_prepare: F,
) -> io::Result<MkgrdRefineLoopNamelistRunReport>
where
    F: FnOnce(&MkgrdRefineLoopPrepareReport) -> io::Result<()>,
{
    let prepare =
        prepare_mkgrd_refine_loop_namelist_with_source_grid(namelist_source, workdir, source_grid)?;
    after_prepare(&prepare)?;
    let source_options = mkgrd_refine_source_branch_options_from_prepare(
        &prepare,
        source_grid,
        calculated_refine,
        is_in_domain,
        seaorland,
        landtypes_global,
        num_vertex,
        maxlc,
    )?;
    let mut executor = mkgrd_migrated_refine_loop_executor_with_runtime_state(
        source_options,
        refine_executor,
        prepare.runtime_state.clone(),
    );
    let execution = run_mkgrd_refine_loop_execution_with_final_domain_contain(
        &prepare.plan,
        &mut executor,
        contain_options,
        postproc_options,
    )?;
    Ok(MkgrdRefineLoopNamelistRunReport { prepare, execution })
}

/// Build the non-destructive step schedule for the `mkgrd.F90` refine loop.
///
/// Fortran computes `max_iter = max(max_iter_cal, max_iter_spc)`, then for each
/// `step` runs the calculated `iter=0` threshold branch while `step <=
/// max_iter_cal`, the specified branch while `step <= max_iter_spc`, and then
/// calls `refine_loop`.  When `exit_loop_step(step)` is pre-seeded, this plan
/// also models the Fortran `all(exit_loop_step(1:max_iter))` early-exit check
/// before incrementing `step`.
pub fn plan_mkgrd_refine_loop(refine: &RefineConfig) -> io::Result<MkgrdRefineLoopPlan> {
    let calculated_enabled = matches!(refine.refine_setting.as_str(), "calculate" | "mixed");
    let specified_enabled = matches!(refine.refine_setting.as_str(), "specified" | "mixed");
    let active_max_iter_cal = if calculated_enabled {
        refine.max_iter_cal
    } else {
        0
    };
    let active_max_iter_spc = if specified_enabled {
        refine.max_iter_spc
    } else {
        0
    };
    let max_iter_i32 = active_max_iter_cal.max(active_max_iter_spc);
    if max_iter_i32 <= 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "max_iter must be more than zero like mkgrd.F90 refine loop",
        ));
    }
    let max_iter = usize::try_from(max_iter_i32)
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "max_iter must fit usize"))?;
    let max_iter_cal = usize::try_from(active_max_iter_cal.max(0))
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "max_iter_cal must fit usize"))?;
    let max_iter_spc = usize::try_from(active_max_iter_spc.max(0))
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "max_iter_spc must fit usize"))?;
    validate_mkgrd_refine_loop_controls(refine, max_iter)?;

    let mut steps = Vec::with_capacity(max_iter);
    let mut completed_steps = vec![false; max_iter + 1];
    let mut final_mask_postproc_step = max_iter + 1;
    for step in 1..=max_iter {
        let mut sources = Vec::with_capacity(2);
        if calculated_enabled && step <= max_iter_cal {
            sources.push(MkgrdRefineSource::CalculatedIterZero);
        }
        if specified_enabled && step <= max_iter_spc {
            sources.push(MkgrdRefineSource::SpecifiedStep);
        }

        if refine.exit_loop_step.get(step).copied().unwrap_or(false) {
            completed_steps[step] = true;
        }
        let stop_after_step = (1..=max_iter).all(|idx| completed_steps[idx]);
        if stop_after_step {
            final_mask_postproc_step = step;
        }

        steps.push(MkgrdRefineLoopStepPlan {
            step,
            max_transition_row: usize::try_from(refine.max_transition_row[step]).map_err(|_| {
                io::Error::new(
                    io::ErrorKind::InvalidInput,
                    format!("max_transition_row({step}) must fit usize"),
                )
            })?,
            sources,
            run_refine_loop: true,
            stop_after_step,
        });

        if stop_after_step {
            break;
        }
    }

    Ok(MkgrdRefineLoopPlan {
        max_iter,
        steps,
        final_mask_postproc_step,
    })
}

/// Execute the final file-backed handoff after the top-level `mkgrd.F90` refine
/// loop: copy the final step gridfile to `result/gridfile_NXP####_<mode>.nc4`
/// like `Get_Contain(0)` does before containment calculation, then optionally
/// run the migrated domain `mask_postproc` branch using the planned files.
pub fn run_mkgrd_refine_loop_final_domain_handoff(
    plan: &MkgrdRefineLoopIoPlan,
    postproc_options: Option<MkgrdFinalDomainPostprocOptions<'_>>,
) -> io::Result<MkgrdRefineLoopFinalDomainHandoffReport> {
    run_mkgrd_refine_loop_final_domain_handoff_with_domain_contain(plan, None, postproc_options)
}

/// Execute the final file-backed handoff after the top-level `mkgrd.F90` refine
/// loop and, when requested, generate the final `Get_Contain(0)` domain
/// containment file before optional `mask_postproc(mesh_type)`.
pub fn run_mkgrd_refine_loop_final_domain_handoff_with_domain_contain(
    plan: &MkgrdRefineLoopIoPlan,
    contain_options: Option<MkgrdFinalDomainContainOptions<'_>>,
    postproc_options: Option<MkgrdFinalDomainPostprocOptions<'_>>,
) -> io::Result<MkgrdRefineLoopFinalDomainHandoffReport> {
    if let Some(parent) = plan.final_result_gridfile.parent() {
        fs::create_dir_all(parent)?;
    }
    let copied_bytes = fs::copy(&plan.final_domain_gridfile, &plan.final_result_gridfile)?;

    let generated_contain = contain_options
        .map(|options| {
            run_getcontain_refine_file_fortran_indexed(GetContainRefineFileRunConfig {
                gridfile: &plan.final_result_gridfile,
                area_grid_file: options.area_grid_file,
                output: &plan.final_domain_contain_output,
                mesh_kind: options.mesh_kind,
                seaorland: options.seaorland,
                lon_vertex: options.lon_vertex,
                lat_vertex: options.lat_vertex,
                lon_i: options.lon_i,
                lat_i: options.lat_i,
                num_vertex: options.num_vertex,
            })
        })
        .transpose()?;

    let postproc = match postproc_options {
        None => None,
        Some(options) => Some(match options {
            MkgrdFinalDomainPostprocOptions::Atmos { output_format } => {
                match output_format.trim() {
                    "MPAS" => MkgrdFinalDomainPostprocReport::AtmosFull(
                        write_mask_postproc_atmos_mpas_netcdf(
                            &plan.file_dir,
                            plan.nxp,
                            plan.final_mask_postproc_step,
                            &plan.mode_grid,
                            &plan.mesh_type,
                            output_format,
                        )?,
                    ),
                    "MPAS-Simple" => MkgrdFinalDomainPostprocReport::Atmos(
                        write_mask_postproc_atmos_mpas_simple_netcdf(
                            &plan.file_dir,
                            plan.nxp,
                            &plan.mode_grid,
                            &plan.mesh_type,
                            output_format,
                        )?,
                    ),
                    other => {
                        return Err(io::Error::new(
                                io::ErrorKind::InvalidInput,
                                format!(
                                    "atmosmesh final postproc supports output_format MPAS/MPAS-Simple, got {other}"
                                ),
                            ));
                    }
                }
            }
            MkgrdFinalDomainPostprocOptions::Earth(options) => {
                let postproc_plan = plan.final_mask_postproc_domain.as_ref().ok_or_else(|| {
                    io::Error::new(
                        io::ErrorKind::InvalidInput,
                        "final domain mask_postproc plan is unavailable for this mesh_type",
                    )
                })?;
                MkgrdFinalDomainPostprocReport::Earth(run_mask_postproc_earth_domain(
                    postproc_plan,
                    options,
                )?)
            }
            MkgrdFinalDomainPostprocOptions::EarthFromFinalGrid(options) => {
                let postproc_plan = plan.final_mask_postproc_domain.as_ref().ok_or_else(|| {
                    io::Error::new(
                        io::ErrorKind::InvalidInput,
                        "final domain mask_postproc plan is unavailable for this mesh_type",
                    )
                })?;
                let source_mesh = read_unstructured_mesh_netcdf(&postproc_plan.source_gridfile)?;
                let num_mp_step = vec![source_mesh.m_points.len()];
                MkgrdFinalDomainPostprocReport::Earth(run_mask_postproc_earth_domain(
                    postproc_plan,
                    MaskPostprocEarthRunOptions {
                        mask_sea_ratio: options.mask_sea_ratio,
                        minlon_dm_area: options.minlon_dm_area,
                        maxlat_dm_area: options.maxlat_dm_area,
                        nlons_dm_select: options.nlons_dm_select,
                        nlats_dm_select: options.nlats_dm_select,
                        lon_vertex: options.lon_vertex,
                        lat_vertex: options.lat_vertex,
                        lon_i: options.lon_i,
                        lat_i: options.lat_i,
                        num_mp_step: &num_mp_step,
                        sjx_points: source_mesh.m_points.len(),
                    },
                )?)
            }
            MkgrdFinalDomainPostprocOptions::Land(options) => {
                let postproc_plan = plan.final_mask_postproc_domain.as_ref().ok_or_else(|| {
                    io::Error::new(
                        io::ErrorKind::InvalidInput,
                        "final domain mask_postproc plan is unavailable for this mesh_type",
                    )
                })?;
                MkgrdFinalDomainPostprocReport::Land(run_mask_postproc_land_domain(
                    postproc_plan,
                    options,
                )?)
            }
            MkgrdFinalDomainPostprocOptions::Ocean(options) => {
                let postproc_plan = plan.final_mask_postproc_domain.as_ref().ok_or_else(|| {
                    io::Error::new(
                        io::ErrorKind::InvalidInput,
                        "final domain mask_postproc plan is unavailable for this mesh_type",
                    )
                })?;
                MkgrdFinalDomainPostprocReport::Ocean(run_mask_postproc_ocean_domain(
                    postproc_plan,
                    options,
                )?)
            }
        }),
    };

    Ok(MkgrdRefineLoopFinalDomainHandoffReport {
        copied_result_gridfile: plan.final_result_gridfile.clone(),
        copied_bytes,
        contain_domain: plan.final_domain_contain_output.clone(),
        generated_contain,
        postproc,
    })
}

/// Execute only the `MOD_refine.F90:refine_loop` prologue that reads the
/// current unstructured grid and copies it to `tmpfile/*_ori.nc4`.
///
/// This intentionally does not perform one-into-four refinement, transition
/// building, LOP, `NGR_RENEW`, or final gridfile writing. It is a safe adapter
/// boundary for wiring the remaining geometry kernels incrementally.
pub fn run_mkgrd_refine_loop_prologue_snapshot(
    step: &MkgrdRefineLoopStepIoPlan,
) -> io::Result<MkgrdRefineLoopPrologueSnapshotReport> {
    let mesh = read_unstructured_mesh_netcdf(&step.refine_loop_input_gridfile)?;
    if let Some(parent) = step.refine_loop_original_tmpfile.parent() {
        fs::create_dir_all(parent)?;
    }
    let copied_bytes = fs::copy(
        &step.refine_loop_input_gridfile,
        &step.refine_loop_original_tmpfile,
    )?;
    Ok(MkgrdRefineLoopPrologueSnapshotReport {
        input_gridfile: step.refine_loop_input_gridfile.clone(),
        original_tmpfile: step.refine_loop_original_tmpfile.clone(),
        copied_bytes,
        sjx_points: mesh.m_points.len(),
        lbx_points: mesh.w_points.len(),
    })
}

/// Execute the `refine_loop` prologue and return the Fortran-indexed Rust
/// working state that subsequent migrated geometry adapters can mutate.
pub fn run_mkgrd_refine_loop_working_state_prologue(
    step: &MkgrdRefineLoopStepIoPlan,
) -> io::Result<MkgrdRefineLoopWorkingStatePrologueReport> {
    let mesh = read_unstructured_mesh_netcdf(&step.refine_loop_input_gridfile)?;
    if let Some(parent) = step.refine_loop_original_tmpfile.parent() {
        fs::create_dir_all(parent)?;
    }
    let copied_bytes = fs::copy(
        &step.refine_loop_input_gridfile,
        &step.refine_loop_original_tmpfile,
    )?;
    let snapshot = MkgrdRefineLoopPrologueSnapshotReport {
        input_gridfile: step.refine_loop_input_gridfile.clone(),
        original_tmpfile: step.refine_loop_original_tmpfile.clone(),
        copied_bytes,
        sjx_points: mesh.m_points.len(),
        lbx_points: mesh.w_points.len(),
    };
    let state = RefineLoopWorkingState::from_unstructured_mesh(&mesh);
    Ok(MkgrdRefineLoopWorkingStatePrologueReport { snapshot, state })
}

impl MkgrdRefineLoopWorkingStateExecutor {
    pub fn with_one_into_four_ref_sjx(
        ref_sjx: Vec<i32>,
        num_vertex: usize,
        set_dis_in: usize,
    ) -> Self {
        Self {
            one_into_four_ref_sjx: Some(ref_sjx),
            one_into_two_ref_sjx: None,
            one_into_two_is_reverse: false,
            one_into_two_mrl_new: None,
            one_into_two_triangle_neighbors: None,
            specified_threshold_file: None,
            calculated_threshold_files: Vec::new(),
            num_vertex,
            set_dis_in,
            last_post_refine_counts: None,
        }
    }

    pub fn with_one_into_two_ref_sjx(
        ref_sjx: Vec<i32>,
        is_reverse: bool,
        num_vertex: usize,
        mrl_new: Vec<i32>,
    ) -> Self {
        Self {
            one_into_four_ref_sjx: None,
            one_into_two_ref_sjx: Some(ref_sjx),
            one_into_two_is_reverse: is_reverse,
            one_into_two_mrl_new: Some(mrl_new),
            one_into_two_triangle_neighbors: None,
            specified_threshold_file: None,
            calculated_threshold_files: Vec::new(),
            num_vertex,
            set_dis_in: 0,
            last_post_refine_counts: None,
        }
    }

    pub fn with_one_into_two_triangle_neighbors(
        mut self,
        triangle_neighbors: Vec<Vec<usize>>,
    ) -> Self {
        self.one_into_two_triangle_neighbors = Some(triangle_neighbors);
        self
    }

    pub fn with_specified_threshold_file(
        threshold_file: impl Into<PathBuf>,
        num_vertex: usize,
        set_dis_in: usize,
    ) -> Self {
        Self {
            one_into_four_ref_sjx: None,
            one_into_two_ref_sjx: None,
            one_into_two_is_reverse: false,
            one_into_two_mrl_new: None,
            one_into_two_triangle_neighbors: None,
            specified_threshold_file: Some(threshold_file.into()),
            calculated_threshold_files: Vec::new(),
            num_vertex,
            set_dis_in,
            last_post_refine_counts: None,
        }
    }

    pub fn with_calculated_threshold_files(
        threshold_files: impl IntoIterator<Item = PathBuf>,
        num_vertex: usize,
        set_dis_in: usize,
    ) -> Self {
        Self {
            one_into_four_ref_sjx: None,
            one_into_two_ref_sjx: None,
            one_into_two_is_reverse: false,
            one_into_two_mrl_new: None,
            one_into_two_triangle_neighbors: None,
            specified_threshold_file: None,
            calculated_threshold_files: threshold_files.into_iter().collect(),
            num_vertex,
            set_dis_in,
            last_post_refine_counts: None,
        }
    }

    pub fn run_refine_loop_step_report(
        &self,
        step: &MkgrdRefineLoopStepIoPlan,
    ) -> io::Result<MkgrdRefineLoopWorkingStateStepReport> {
        let prologue = run_mkgrd_refine_loop_working_state_prologue(step)?;
        let mut state = prologue.state.clone();
        let mut loaded_ref_sjx = None;
        let mut onedivide_four_connection = None;
        let mut array_length = None;
        let mut onedivide_four_renew = None;
        let mut onedivide_two = None;
        let mut ngr_renew = None;
        let mut post_refine_counts = None;

        let ref_sjx = if let Some(ref_sjx) = &self.one_into_four_ref_sjx {
            Some(ref_sjx.clone())
        } else if let Some(threshold_file) = &self.specified_threshold_file {
            Some(read_getref_specified_ref_sjx_netcdf(threshold_file)?)
        } else if !self.calculated_threshold_files.is_empty() {
            Some(read_getref_calculated_ref_sjx_netcdf(
                &self.calculated_threshold_files,
                self.num_vertex,
            )?)
        } else {
            None
        };

        if let Some(ref_sjx) = ref_sjx {
            loaded_ref_sjx = Some(ref_sjx.clone());
            self.run_configured_one_into_four_pipeline(step, &mut state, &ref_sjx)
                .map(|(connection, length, renew, ngr, counts)| {
                    onedivide_four_connection = Some(connection);
                    array_length = Some(length);
                    onedivide_four_renew = Some(renew);
                    ngr_renew = Some(ngr);
                    post_refine_counts = counts;
                })?;
        } else if let Some(ref_sjx) = &self.one_into_two_ref_sjx {
            loaded_ref_sjx = Some(ref_sjx.clone());
            let mrl_new = self.one_into_two_mrl_new.as_ref().ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidInput,
                    "one-into-two transition requires mrl_new markers",
                )
            })?;
            onedivide_two = Some(
                self.run_configured_one_into_two_transition_pipeline(&mut state, ref_sjx, mrl_new)?,
            );
        }

        let output_mesh = state.to_unstructured_mesh()?;
        write_unstructured_mesh_netcdf(&step.refine_loop_output_gridfile, &output_mesh)?;
        Ok(MkgrdRefineLoopWorkingStateStepReport {
            prologue,
            state,
            output_gridfile: step.refine_loop_output_gridfile.clone(),
            loaded_ref_sjx,
            onedivide_four_connection,
            array_length,
            onedivide_four_renew,
            onedivide_two,
            ngr_renew,
            post_refine_counts,
        })
    }

    fn run_configured_one_into_two_transition_pipeline(
        &self,
        state: &mut RefineLoopWorkingState,
        ref_sjx: &[i32],
        mrl_new: &[i32],
    ) -> io::Result<OnedivideTwoReport> {
        let old_mp = *state
            .num_mp
            .get(1)
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "num_mp[1] is required"))?;
        let old_wp = *state
            .num_wp
            .get(1)
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "num_wp[1] is required"))?;
        if ref_sjx.len() <= old_mp || mrl_new.len() <= old_mp {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!(
                    "one-into-two transition requires placeholder plus {old_mp} ref_sjx/mrl_new entries"
                ),
            ));
        }

        let num_vertex = self.num_vertex.max(1).min(old_mp);
        state.num_vertex = num_vertex;
        state.ref_sjx = ref_sjx[..=old_mp]
            .iter()
            .map(|&marker| if marker > 1 { 1 } else { marker })
            .collect();
        state.mrl_new = mrl_new[..=old_mp].to_vec();
        let marked_triangles = state.ref_sjx[num_vertex + 1..=old_mp]
            .iter()
            .filter(|&&marker| marker != 0)
            .count();

        state.iter = 2;
        if state.num_mp.len() <= state.iter {
            state.num_mp.resize(state.iter + 1, 0);
        }
        if state.num_wp.len() <= state.iter {
            state.num_wp.resize(state.iter + 1, 0);
        }
        state.num_mp[state.iter] = old_mp + marked_triangles * 2;
        state.num_wp[state.iter] = old_wp + marked_triangles;
        state.mp_new.resize(
            state.num_mp[state.iter] + 1,
            LonLatPoint { lon: 0.0, lat: 0.0 },
        );
        state.wp_new.resize(
            state.num_wp[state.iter] + 1,
            LonLatPoint { lon: 0.0, lat: 0.0 },
        );
        if state.ngrmw_new.len() <= 3 {
            state.ngrmw_new.resize_with(4, Vec::new);
        }
        for row in &mut state.ngrmw_new[1..=3] {
            row.resize(state.num_mp[state.iter] + 1, 0);
        }
        state.sjx_child.resize(old_mp + 1, [0, 0]);
        if let Some(triangle_neighbors) = &self.one_into_two_triangle_neighbors {
            state.triangle_neighbors = triangle_neighbors.clone();
        }

        let report = state.apply_onedivide_two(self.one_into_two_is_reverse)?;
        refresh_working_vertex_membership_from_ngrmw_new(state)?;
        Ok(report)
    }

    fn run_configured_one_into_four_pipeline(
        &self,
        step: &MkgrdRefineLoopStepIoPlan,
        state: &mut RefineLoopWorkingState,
        ref_sjx: &[i32],
    ) -> io::Result<(
        OnedivideFourConnectionReport,
        RefineArrayLengthCalculationRunReport,
        OnedivideFourRenewReport,
        NgrRenewReport,
        Option<(usize, usize)>,
    )> {
        let old_mp = *state
            .num_mp
            .get(1)
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "num_mp[1] is required"))?;
        let old_wp = *state
            .num_wp
            .get(1)
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "num_wp[1] is required"))?;
        if ref_sjx.len() <= old_mp {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("one-into-four ref_sjx must include placeholder plus {old_mp} triangles"),
            ));
        }
        let file_dir = step
            .refine_loop_input_gridfile
            .parent()
            .and_then(Path::parent)
            .ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidInput,
                    "refine_loop_input_gridfile must live under <file_dir>/gridfile",
                )
            })?;
        let set_dis_in = if self.set_dis_in > 0 {
            self.set_dis_in
        } else {
            step.max_transition_row
        };
        let num_vertex = self.num_vertex.max(1).min(old_mp);
        state.num_vertex = num_vertex;
        state.ref_sjx = ref_sjx[..=old_mp]
            .iter()
            .map(|&marker| if marker > 1 { 1 } else { marker })
            .collect();
        if step.step > 1 {
            apply_previous_refine_region_prefilter(
                file_dir,
                step.step - 1,
                set_dis_in + 1,
                old_mp,
                old_wp,
                state,
            )?;
        }
        if set_dis_in == 0 {
            remove_isolated_one_into_four_markers(
                num_vertex,
                old_mp,
                &state.triangle_neighbors,
                &mut state.ref_sjx,
            )?;
        }
        let active_refine_start = num_vertex + 1;
        if active_refine_start > old_mp
            || !state.ref_sjx[active_refine_start..=old_mp]
                .iter()
                .any(|&marker| marker != 0)
        {
            return Ok((
                OnedivideFourConnectionReport {
                    marked_triangles: Vec::new(),
                    marked_vertices: Vec::new(),
                },
                empty_refine_array_length_report(),
                OnedivideFourRenewReport {
                    refined_triangles: Vec::new(),
                    new_triangle_ids: Vec::new(),
                    new_vertex_ids: Vec::new(),
                    dateline_adjusted: false,
                },
                identity_ngr_renew_report(old_mp, old_wp, state),
                None,
            ));
        }
        let mut ref_sjx_segment = state.ref_sjx.clone();
        state.num_tranrow_sjx = ref_sjx_segment[num_vertex + 1..=old_mp]
            .iter()
            .filter(|&&marker| marker != 0)
            .count();

        let mut connection = state.apply_onedivide_four_connection()?;
        let can_expand_transition = marked_triangles_have_valid_neighbors(
            num_vertex,
            old_mp,
            &state.triangle_neighbors,
            &state.ref_sjx,
        );
        if can_expand_transition {
            self.expand_one_into_four_transition_band(
                state,
                num_vertex,
                old_mp,
                old_wp,
                set_dis_in,
                &mut ref_sjx_segment,
                &mut connection,
            )?;
        }
        state.ref_sjx = ref_sjx_segment;
        state.num_tranrow_sjx = state.ref_sjx[num_vertex + 1..=old_mp]
            .iter()
            .filter(|&&marker| marker != 0)
            .count();
        let length = state.apply_array_length_calculation(file_dir, step.step, set_dis_in)?;

        state.iter = 2;
        if state.num_mp.len() <= state.iter {
            state.num_mp.resize(state.iter + 1, 0);
        }
        if state.num_wp.len() <= state.iter {
            state.num_wp.resize(state.iter + 1, 0);
        }
        let reserved_capacity = state.num_tranrow_sjx * 4;
        state.num_mp[state.iter] = old_mp + reserved_capacity;
        state.num_wp[state.iter] = old_wp + reserved_capacity;
        state.mp_new.resize(
            state.num_mp[state.iter] + 1,
            LonLatPoint { lon: 0.0, lat: 0.0 },
        );
        state.wp_new.resize(
            state.num_wp[state.iter] + 1,
            LonLatPoint { lon: 0.0, lat: 0.0 },
        );
        if state.ngrmw_new.len() <= 3 {
            state.ngrmw_new.resize_with(4, Vec::new);
        }
        for row in &mut state.ngrmw_new[1..=3] {
            row.resize(state.num_mp[state.iter] + 1, 1);
        }

        let renew = state.apply_onedivide_four_renew()?;
        state.num_mp[state.iter] = old_mp + renew.new_triangle_ids.len();
        state.num_wp[state.iter] = old_wp + renew.new_vertex_ids.len();
        let num_lop = self.apply_forward_transition_rows(state, set_dis_in, &length)?;
        let ngr = state.apply_ngr_renew()?;
        let output_mesh = state.to_unstructured_mesh()?;
        let post_counts = Some(refine_loop_post_counts_fortran_indexed(
            old_mp,
            old_wp,
            *state.num_mp.get(state.iter).ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidInput,
                    "refine working state is missing expanded num_mp(iter)",
                )
            })?,
            &output_mesh,
            num_lop,
        )?);
        Ok((connection, length, renew, ngr, post_counts))
    }

    fn expand_one_into_four_transition_band(
        &self,
        state: &mut RefineLoopWorkingState,
        num_vertex: usize,
        old_mp: usize,
        old_wp: usize,
        set_dis_in: usize,
        ref_sjx_segment: &mut [i32],
        connection: &mut OnedivideFourConnectionReport,
    ) -> io::Result<()> {
        if set_dis_in == 0 {
            return Ok(());
        }

        loop {
            let mut changed_outer = false;

            loop {
                let markers = refine_iter_b_judge_fortran_indexed(
                    set_dis_in,
                    num_vertex,
                    &state.triangle_neighbors,
                    &state.mrl_new,
                )?;
                if !self.apply_transition_markers(
                    state,
                    num_vertex,
                    old_mp,
                    &markers,
                    ref_sjx_segment,
                    connection,
                )? {
                    break;
                }
                changed_outer = true;
            }

            loop {
                let (cells_on_triangle, triangles_on_cell) =
                    transition_cell_views(state, old_mp, old_wp)?;
                let markers = refine_iter_c_judge_fortran_indexed(
                    set_dis_in,
                    num_vertex,
                    num_vertex,
                    old_wp,
                    &state.triangle_neighbors,
                    &triangles_on_cell,
                    &state.n_ngrwm,
                    &state.mrl_new,
                    &state.ref_lbx,
                )?;
                drop(cells_on_triangle);
                if !self.apply_transition_markers(
                    state,
                    num_vertex,
                    old_mp,
                    &markers,
                    ref_sjx_segment,
                    connection,
                )? {
                    break;
                }
                changed_outer = true;
            }

            let (cells_on_triangle, triangles_on_cell) =
                transition_cell_views(state, old_mp, old_wp)?;
            let markers = refine_iter_e_judge_fortran_indexed(
                num_vertex,
                old_wp,
                &cells_on_triangle,
                &triangles_on_cell,
                &state.n_ngrwm,
                &state.mrl_new,
                &state.ref_lbx,
            )?;
            if self.apply_transition_markers(
                state,
                num_vertex,
                old_mp,
                &markers,
                ref_sjx_segment,
                connection,
            )? {
                changed_outer = true;
            }

            if changed_outer {
                continue;
            }

            loop {
                let (_, triangles_on_cell) = transition_cell_views(state, old_mp, old_wp)?;
                let markers = refine_iter_g_judge_fortran_indexed(
                    num_vertex,
                    old_wp,
                    &triangles_on_cell,
                    &state.n_ngrwm,
                    &state.mrl_new,
                )?;
                if !self.apply_transition_markers(
                    state,
                    num_vertex,
                    old_mp,
                    &markers,
                    ref_sjx_segment,
                    connection,
                )? {
                    break;
                }
                changed_outer = true;
            }

            if !changed_outer {
                break;
            }
        }

        Ok(())
    }

    fn apply_transition_markers(
        &self,
        state: &mut RefineLoopWorkingState,
        num_vertex: usize,
        old_mp: usize,
        markers: &[i32],
        ref_sjx_segment: &mut [i32],
        connection: &mut OnedivideFourConnectionReport,
    ) -> io::Result<bool> {
        if markers.len() <= old_mp {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("transition markers must include placeholder plus {old_mp} triangles"),
            ));
        }
        state.ref_sjx.fill(0);
        let mut any = false;
        for triangle in (num_vertex + 1)..=old_mp {
            if markers[triangle] == 0 || state.mrl_new[triangle] == 4 {
                continue;
            }
            state.ref_sjx[triangle] = 1;
            ref_sjx_segment[triangle] = 1;
            any = true;
        }
        if !any {
            return Ok(false);
        }
        let added = state.apply_onedivide_four_connection()?;
        for triangle in added.marked_triangles {
            if !connection.marked_triangles.contains(&triangle) {
                connection.marked_triangles.push(triangle);
            }
        }
        for vertex in added.marked_vertices {
            if !connection.marked_vertices.contains(&vertex) {
                connection.marked_vertices.push(vertex);
            }
        }
        Ok(true)
    }

    fn apply_forward_transition_rows(
        &self,
        state: &mut RefineLoopWorkingState,
        set_dis_in: usize,
        length: &RefineArrayLengthCalculationRunReport,
    ) -> io::Result<usize> {
        if set_dis_in == 0 || length.calculation.boundary.curves.num_closed_curve == 0 {
            return Ok(0);
        }

        let old_mp = *state
            .num_mp
            .get(1)
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "num_mp[1] is required"))?;
        let old_wp = *state
            .num_wp
            .get(1)
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "num_wp[1] is required"))?;
        let (_, triangles_on_cell) = transition_cell_views(state, old_mp, old_wp)?;
        let close_curves = length.calculation.boundary.curves.close_curves
            [1..=length.calculation.boundary.curves.num_closed_curve]
            .to_vec();
        let boundary_segments = refine_boundary_segments_make_fortran_indexed(
            set_dis_in,
            &close_curves,
            &triangles_on_cell,
            &state.n_ngrwm,
            &state.mrl_new,
        )?;
        if boundary_segments.num_bdy_refine_segment == 0 {
            return Ok(0);
        }

        let mut segments = boundary_segments.bdy_refine_segment;
        for segment in &mut segments {
            segment.resize(set_dis_in, 1);
        }
        let mut segment_lengths = boundary_segments.n_bdy_refine_segment;
        state.sjx_child.resize(old_mp + 1, [0, 0]);
        let mut num_lop = 0usize;

        for transition_row in 1..=set_dis_in {
            let segments_old = segments.clone();
            state.ref_sjx.fill(0);
            for (segment, remaining) in segments.iter().zip(segment_lengths.iter_mut()) {
                if *remaining == 0 {
                    continue;
                }
                for &triangle in segment.iter().take(*remaining) {
                    if triangle == 1 {
                        break;
                    }
                    if triangle != 0
                        && triangle < state.ref_sjx.len()
                        && state.mrl_new[triangle] != 4
                    {
                        state.ref_sjx[triangle] = 1;
                    }
                }
                *remaining = remaining.saturating_sub(1);
            }

            let num_ref = state.ref_sjx.iter().filter(|&&marker| marker != 0).count();
            if num_ref == 0 {
                if transition_row == 1 {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidInput,
                        "transition row 1 has no forward one-into-two triangles",
                    ));
                }
                break;
            }

            apply_transition_onedivide_two(state, num_ref, false)?;

            if transition_row >= set_dis_in {
                continue;
            }

            let reverse = apply_isreverse_judge_fortran_indexed(
                set_dis_in,
                segments.len(),
                &state.triangle_neighbors,
                &state.mrl_new,
                &mut segments,
                &segment_lengths,
            )?;
            state.ref_sjx = reverse.ref_sjx;
            let reverse_ref = state.ref_sjx.iter().filter(|&&marker| marker != 0).count();
            if reverse_ref != 0 {
                apply_transition_onedivide_two(state, reverse_ref, true)?;
            }

            let num_end = 4 * (set_dis_in - 1);
            if num_end == 0 {
                continue;
            }
            let num_segment = segments.len();
            let mut segment_temp = vec![vec![1_usize; num_end + 1]; num_segment + 1];
            let mut n_segment_temp = Vec::with_capacity(num_segment + 1);
            n_segment_temp.push(0);
            n_segment_temp.extend(segment_lengths.iter().copied());
            let bdy_segment = fortran_index_segments(&segments);
            let bdy_segment_old = fortran_index_segments(&segments_old);
            let mut n_bdy_segment = Vec::with_capacity(num_segment + 1);
            n_bdy_segment.push(0);
            n_bdy_segment.extend(segment_lengths.iter().copied());
            let mut lop_ref = 0usize;
            apply_sharp_concav_lop_judge_fortran_indexed(
                &mut lop_ref,
                num_segment,
                state.num_mp[state.iter],
                &state.mrl_new,
                &state.triangle_neighbors,
                &state.ngrmw_new,
                &state.sjx_child,
                &bdy_segment,
                &bdy_segment_old,
                &n_bdy_segment,
                &mut segment_temp,
                &mut n_segment_temp,
            )?;
            if lop_ref == 0 {
                continue;
            }
            num_lop += lop_ref;
            let mut lop_segment = vec![0usize];
            for segment_id in 1..=num_segment {
                let n = n_segment_temp[segment_id];
                if n == 0 {
                    continue;
                }
                lop_segment.extend_from_slice(&segment_temp[segment_id][1..=n]);
            }
            state.iter += 1;
            if state.num_mp.len() <= state.iter {
                state.num_mp.resize(state.iter + 1, 0);
            }
            if state.num_wp.len() <= state.iter {
                state.num_wp.resize(state.iter + 1, 0);
            }
            state.num_mp[state.iter] = state.num_mp[state.iter - 1] + lop_ref;
            state.num_wp[state.iter] = state.num_wp[state.iter - 1];
            state.mp_new.resize(
                state.num_mp[state.iter] + 1,
                LonLatPoint { lon: 0.0, lat: 0.0 },
            );
            if state.ngrmw_new.len() <= 3 {
                state.ngrmw_new.resize_with(4, Vec::new);
            }
            for row in &mut state.ngrmw_new[1..=3] {
                row.resize(state.num_mp[state.iter] + 1, 1);
            }
            state.num_ref = lop_ref;
            state.ref_sjx_segment = lop_segment;
            state.apply_delaunay_lop()?;
        }

        Ok(num_lop)
    }
}

fn apply_transition_onedivide_two(
    state: &mut RefineLoopWorkingState,
    num_ref: usize,
    is_reverse: bool,
) -> io::Result<()> {
    state.iter += 1;
    if state.num_mp.len() <= state.iter {
        state.num_mp.resize(state.iter + 1, 0);
    }
    if state.num_wp.len() <= state.iter {
        state.num_wp.resize(state.iter + 1, 0);
    }
    state.num_mp[state.iter] = state.num_mp[state.iter - 1] + 2 * num_ref;
    state.num_wp[state.iter] = state.num_wp[state.iter - 1] + num_ref;
    state.mp_new.resize(
        state.num_mp[state.iter] + 1,
        LonLatPoint { lon: 0.0, lat: 0.0 },
    );
    state.wp_new.resize(
        state.num_wp[state.iter] + 1,
        LonLatPoint { lon: 0.0, lat: 0.0 },
    );
    if state.ngrmw_new.len() <= 3 {
        state.ngrmw_new.resize_with(4, Vec::new);
    }
    for row in &mut state.ngrmw_new[1..=3] {
        row.resize(state.num_mp[state.iter] + 1, 1);
    }

    state.apply_onedivide_two(is_reverse)?;
    for triangle in 1..state.ref_sjx.len() {
        if state.ref_sjx[triangle] != 0 {
            state.mrl_new[triangle] = 4;
        }
    }
    Ok(())
}

fn remove_isolated_one_into_four_markers(
    num_vertex: usize,
    old_mp: usize,
    triangle_neighbors: &[Vec<usize>],
    ref_sjx: &mut [i32],
) -> io::Result<()> {
    if triangle_neighbors.len() <= old_mp || ref_sjx.len() <= old_mp {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("old_mp {old_mp} requires one-based triangle neighbor and ref_sjx storage"),
        ));
    }
    for triangle in (num_vertex + 1)..=old_mp {
        if ref_sjx[triangle] != 1 {
            continue;
        }
        let neighbors = &triangle_neighbors[triangle];
        if neighbors.len() != 3 {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("triangle neighbor row {triangle} must contain exactly three neighbors"),
            ));
        }
        let mut neighbor_marker_sum = 0_i32;
        for &neighbor in neighbors {
            if neighbor == 0 {
                continue;
            }
            if neighbor > old_mp {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidInput,
                    format!("triangle {triangle} references invalid neighbor {neighbor}"),
                ));
            }
            neighbor_marker_sum += ref_sjx[neighbor];
        }
        if neighbor_marker_sum <= 1 {
            ref_sjx[triangle] = 0;
        }
    }
    Ok(())
}

fn marked_triangles_have_valid_neighbors(
    num_vertex: usize,
    old_mp: usize,
    triangle_neighbors: &[Vec<usize>],
    ref_sjx: &[i32],
) -> bool {
    if triangle_neighbors.len() <= old_mp || ref_sjx.len() <= old_mp {
        return false;
    }
    if !((num_vertex + 1)..=old_mp).any(|triangle| ref_sjx[triangle] != 0) {
        return false;
    }
    ((num_vertex + 1)..=old_mp)
        .filter(|&triangle| ref_sjx[triangle] != 0)
        .all(|triangle| {
            triangle_neighbors[triangle]
                .iter()
                .all(|&neighbor| neighbor != 0 && neighbor <= old_mp)
        })
}

fn apply_previous_refine_region_prefilter(
    file_dir: &Path,
    previous_step: usize,
    dist_len: usize,
    old_mp: usize,
    old_wp: usize,
    state: &mut RefineLoopWorkingState,
) -> io::Result<()> {
    let mut close_curves = Vec::new();
    for curve_id in 1.. {
        let path = refine_array_length_close_mesh_output_path(file_dir, previous_step, curve_id);
        if !path.exists() {
            break;
        }
        close_curves.push(read_close_mesh_netcdf(path)?);
    }
    if close_curves.is_empty() {
        return Ok(());
    }
    if state.mp_new.len() <= old_mp || state.n_ngrwm.len() <= old_wp {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "previous refine-region prefilter requires current mesh arrays",
        ));
    }
    if state.ngrwm.iter().any(|row| row.len() <= old_wp) {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "previous refine-region prefilter requires vertex-to-triangle rows",
        ));
    }

    let mut mrl_bk = vec![0_i32; old_mp + 1];
    for triangle in 1..=old_mp {
        let point = state.mp_new[triangle];
        if close_curves
            .iter()
            .any(|curve| point_in_close_curve_fortran(point, curve))
        {
            mrl_bk[triangle] = 1;
        }
    }

    for _ in 0..dist_len {
        let mut boundary = vec![false; old_wp + 1];
        for cell in 1..=old_wp {
            let num_edges = state.n_ngrwm[cell];
            if num_edges == 0 || state.ngrwm.len() <= num_edges {
                continue;
            }
            let mut marked = 0_i32;
            for row in 1..=num_edges {
                let triangle = state.ngrwm[row][cell];
                if triangle <= old_mp {
                    marked += mrl_bk[triangle];
                }
            }
            if marked != 0 && marked != num_edges as i32 {
                boundary[cell] = true;
            }
        }
        for cell in 1..=old_wp {
            if !boundary[cell] {
                continue;
            }
            let num_edges = state.n_ngrwm[cell];
            if state.ngrwm.len() <= num_edges {
                continue;
            }
            for row in 1..=num_edges {
                let triangle = state.ngrwm[row][cell];
                if triangle <= old_mp && mrl_bk[triangle] != 0 {
                    mrl_bk[triangle] = 0;
                }
            }
        }
    }

    for triangle in 1..=old_mp {
        if state.ref_sjx[triangle] != 0 && mrl_bk[triangle] != 1 {
            state.ref_sjx[triangle] = 0;
        }
    }
    Ok(())
}

fn point_in_close_curve_fortran(point: LonLatPoint, curve: &[LonLatPoint]) -> bool {
    if curve.len() < 3 {
        return false;
    }
    let mut inside = false;
    let mut previous = curve.len() - 1;
    for current in 0..curve.len() {
        let current_point = curve[current];
        let previous_point = curve[previous];
        if (current_point.lat > point.lat) != (previous_point.lat > point.lat) {
            let denominator = previous_point.lat - current_point.lat;
            if denominator != 0.0 {
                let lon_intersect = (previous_point.lon - current_point.lon)
                    * (point.lat - current_point.lat)
                    / denominator
                    + current_point.lon;
                if point.lon < lon_intersect {
                    inside = !inside;
                }
            }
        }
        previous = current;
    }
    inside
}

fn empty_refine_array_length_report() -> RefineArrayLengthCalculationRunReport {
    RefineArrayLengthCalculationRunReport {
        calculation: RefineArrayLengthCalculation {
            halo: RefineArrayLengthHalo {
                expanded_mrl: Vec::new(),
                initial_boundary_mask: Vec::new(),
                transition_boundary_mask: Vec::new(),
                boundary_refine: Vec::new(),
                boundary_refine_transition: Vec::new(),
                num_transition_row_triangles: 0,
            },
            boundary: BoundaryConnection {
                bdy_num_in: 0,
                boundary_order: Vec::new(),
                boundary_neighbors: Vec::new(),
                curves: BoundaryClosedCurves {
                    num_closed_curve: 0,
                    num_bdy_long: [0; 3],
                    close_curves: vec![Vec::new()],
                    n_close_curve: vec![0],
                },
            },
        },
        close_meshes: RefineArrayLengthCloseMeshesWriteReport {
            mask_patch_ndm: 0,
            outputs: Vec::new(),
        },
    }
}

fn identity_ngr_renew_report(
    old_mp: usize,
    old_wp: usize,
    state: &RefineLoopWorkingState,
) -> NgrRenewReport {
    NgrRenewReport {
        num_sjx: old_mp,
        num_dbx: old_wp,
        vertex_mapping: (0..=old_wp).collect(),
        adjacency_capacity: state.ngrwm.len().saturating_sub(1).max(7),
        boundary_refine: Vec::new(),
        boundary_refine_transition: Vec::new(),
    }
}

fn fortran_index_segments(segments: &[Vec<usize>]) -> Vec<Vec<usize>> {
    let mut indexed = Vec::with_capacity(segments.len() + 1);
    indexed.push(Vec::new());
    for segment in segments {
        let mut row = Vec::with_capacity(segment.len() + 1);
        row.push(1);
        row.extend(segment.iter().copied());
        indexed.push(row);
    }
    indexed
}

fn transition_cell_views(
    state: &RefineLoopWorkingState,
    old_mp: usize,
    old_wp: usize,
) -> io::Result<(Vec<[usize; 3]>, Vec<Vec<usize>>)> {
    let cells_on_triangle = fortran_rows_to_triangle_major(&state.ngrmw, old_mp)?;
    if state.n_ngrwm.len() <= old_wp {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("old_wp {old_wp} requires one-based n_ngrwm storage"),
        ));
    }
    let mut triangles_on_cell = vec![Vec::<usize>::new(); old_wp + 1];
    for cell in 1..=old_wp {
        let count = state.n_ngrwm[cell];
        if state.ngrwm.len() <= count || state.ngrwm[1..=count].iter().any(|row| row.len() <= cell)
        {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("cell {cell} requires ngrwm rows 1..={count}"),
            ));
        }
        triangles_on_cell[cell].extend((1..=count).map(|row| state.ngrwm[row][cell]));
    }
    Ok((cells_on_triangle, triangles_on_cell))
}

fn refresh_working_vertex_membership_from_ngrmw_new(
    state: &mut RefineLoopWorkingState,
) -> io::Result<()> {
    let num_triangles = *state
        .num_mp
        .get(state.iter)
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "iter must address num_mp"))?;
    let num_vertices = *state
        .num_wp
        .get(state.iter)
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "iter must address num_wp"))?;
    if state.ngrmw_new.len() <= 3
        || state.ngrmw_new[1..=3]
            .iter()
            .any(|row| row.len() <= num_triangles)
    {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "ngrmw_new rows must address current working triangles",
        ));
    }

    let mut triangles_by_vertex = vec![Vec::<usize>::new(); num_vertices + 1];
    for triangle in 1..=num_triangles {
        for row in 1..=3 {
            let vertex = state.ngrmw_new[row][triangle];
            if vertex == 0 || vertex > num_vertices {
                continue;
            }
            triangles_by_vertex[vertex].push(triangle);
        }
    }
    let capacity = triangles_by_vertex.iter().map(Vec::len).max().unwrap_or(0);
    state.ngrwm = vec![vec![0_usize; num_vertices + 1]; capacity + 1];
    state.n_ngrwm = vec![0_usize; num_vertices + 1];
    for (vertex, triangles) in triangles_by_vertex.iter().enumerate().skip(1) {
        state.n_ngrwm[vertex] = triangles.len();
        for (row, &triangle) in triangles.iter().enumerate() {
            state.ngrwm[row + 1][vertex] = triangle;
        }
    }
    Ok(())
}

impl MkgrdRefineLoopExecutor for MkgrdRefineLoopWorkingStateExecutor {
    fn run_source_branch(
        &mut self,
        _step: &MkgrdRefineLoopStepIoPlan,
        _source: &MkgrdRefineSourceIoPlan,
    ) -> io::Result<()> {
        Err(io::Error::new(
            io::ErrorKind::Unsupported,
            "refine source branches are not implemented by MkgrdRefineLoopWorkingStateExecutor",
        ))
    }

    fn run_refine_loop_step(&mut self, step: &MkgrdRefineLoopStepIoPlan) -> io::Result<()> {
        let report = self.run_refine_loop_step_report(step)?;
        self.last_post_refine_counts = report.post_refine_counts;
        Ok(())
    }

    fn run_final_quality_check(&mut self, plan: &MkgrdFinalQualityCheckIoPlan) -> io::Result<()> {
        run_mkgrd_final_quality_check(plan)
    }

    fn accept_source_branch_outputs(
        &mut self,
        _step: &MkgrdRefineLoopStepIoPlan,
        source: &MkgrdRefineSourceIoPlan,
    ) -> io::Result<()> {
        self.one_into_four_ref_sjx = None;
        match source.source {
            MkgrdRefineSource::SpecifiedStep => {
                let threshold_file =
                    source.specified_threshold_output.as_ref().ok_or_else(|| {
                        io::Error::new(
                            io::ErrorKind::InvalidInput,
                            "specified refine source handoff requires a threshold output path",
                        )
                    })?;
                self.specified_threshold_file = Some(threshold_file.clone());
                self.calculated_threshold_files.clear();
            }
            MkgrdRefineSource::CalculatedIterZero => {
                if source.threshold_outputs.is_empty() {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidInput,
                        "calculated refine source handoff requires threshold output paths",
                    ));
                }
                self.specified_threshold_file = None;
                self.calculated_threshold_files = source.threshold_outputs.clone();
            }
        }
        Ok(())
    }

    fn accept_source_branch_report(
        &mut self,
        step: &MkgrdRefineLoopStepIoPlan,
        source: &MkgrdRefineSourceIoPlan,
        report: &MkgrdRefineSourceBranchReport,
    ) -> io::Result<()> {
        let counts = report.contain_runtime_counts();
        if counts.previous_num_vertex > 0 {
            self.num_vertex = counts.previous_num_vertex;
        }
        if let MkgrdRefineSourceBranchReport::Calculated(report) = report {
            let threshold_files = report.getref.written_threshold_outputs();
            if !threshold_files.is_empty() {
                self.specified_threshold_file = None;
                self.calculated_threshold_files = threshold_files;
                return Ok(());
            }
        }
        self.accept_source_branch_outputs(step, source)
    }

    fn last_refine_step_post_counts(&self) -> Option<(usize, usize)> {
        self.last_post_refine_counts
    }
}

impl RefineLoopWorkingState {
    /// Build the initial `refine_loop` working arrays from the current
    /// unstructured gridfile payload.
    pub fn from_unstructured_mesh(mesh: &UnstructuredMesh) -> Self {
        let nma = mesh.m_points.len();
        let nwa = mesh.w_points.len();
        let mut mp_new = vec![LonLatPoint { lon: 0.0, lat: 0.0 }; nma + 1];
        for (idx, point) in mesh.m_points.iter().copied().enumerate() {
            mp_new[idx + 1] = point;
        }
        let mut wp_new = vec![LonLatPoint { lon: 0.0, lat: 0.0 }; nwa + 1];
        for (idx, point) in mesh.w_points.iter().copied().enumerate() {
            wp_new[idx + 1] = point;
        }

        let mut ngrmw = vec![vec![0_usize; nma + 1]; 4];
        for (triangle, vertices) in mesh.m_to_w.iter().enumerate() {
            for row in 1..=3 {
                ngrmw[row][triangle + 1] = vertices[row - 1].max(0) as usize;
            }
        }
        let ngrmw_new = ngrmw.clone();

        let ngrwm_capacity = mesh.w_to_m.iter().map(Vec::len).max().unwrap_or(0);
        let mut ngrwm = vec![vec![0_usize; nwa + 1]; ngrwm_capacity + 1];
        for (vertex, triangles) in mesh.w_to_m.iter().enumerate() {
            for (row, &triangle) in triangles.iter().enumerate() {
                ngrwm[row + 1][vertex + 1] = triangle.max(0) as usize;
            }
        }
        let mut n_ngrwm = vec![0_usize; nwa + 1];
        for (vertex, &count) in mesh.n_w_to_m.iter().enumerate() {
            n_ngrwm[vertex + 1] = count.max(0) as usize;
        }
        let triangle_neighbors =
            derive_triangle_neighbors_from_one_based_membership(nma, nwa, &ngrmw, &ngrwm, &n_ngrwm);

        Self {
            iter: 1,
            num_vertex: 0,
            num_mp: vec![0, nma],
            num_wp: vec![0, nwa],
            num_sjx: 0,
            num_dbx: 0,
            num_tranrow_sjx: 0,
            mp_new,
            wp_new,
            ngrmw,
            ngrmw_new,
            ngrwm,
            n_ngrwm,
            mp_f: Vec::new(),
            wp_f: Vec::new(),
            ngrmw_f: Vec::new(),
            ngrwm_f: Vec::new(),
            n_ngrwm_f: Vec::new(),
            ref_sjx: vec![0; nma + 1],
            ref_lbx: vec![0; nwa + 1],
            mrl_new: vec![1; nma + 1],
            triangle_neighbors,
            segments: Vec::new(),
            n_segments: Vec::new(),
            sjx_child: vec![[0, 0]; nma + 1],
            weak_concav_pair: Vec::new(),
            weak_concav_segment: Vec::new(),
            weak_concav_segment_old: Vec::new(),
            n_weak_concav_segment: Vec::new(),
            bdy_refine_segment: Vec::new(),
            bdy_refine_segment_old: Vec::new(),
            n_bdy_refine_segment: Vec::new(),
            ref_sjx_segment_temp: Vec::new(),
            n_ref_sjx_segment_temp: Vec::new(),
            ref_sjx_segment: Vec::new(),
            num_ref: 0,
            bdy_refine: Vec::new(),
            bdy_refine_tran: Vec::new(),
        }
    }

    /// Export either the renewed final arrays (`*_f`) or the current working
    /// arrays back to the unstructured mesh shape used by gridfile writers.
    pub fn to_unstructured_mesh(&self) -> io::Result<UnstructuredMesh> {
        let has_final = self.num_sjx > 0
            && self.num_dbx > 0
            && !self.mp_f.is_empty()
            && !self.wp_f.is_empty()
            && !self.ngrmw_f.is_empty()
            && !self.ngrwm_f.is_empty()
            && !self.n_ngrwm_f.is_empty();
        if has_final {
            state_arrays_to_unstructured_mesh(
                self.num_sjx,
                self.num_dbx,
                &self.mp_f,
                &self.wp_f,
                &self.ngrmw_f,
                &self.ngrwm_f,
                &self.n_ngrwm_f,
            )
        } else {
            let nma = *self.num_mp.get(self.iter).ok_or_else(|| {
                io::Error::new(io::ErrorKind::InvalidInput, "iter must address num_mp")
            })?;
            let nwa = *self.num_wp.get(self.iter).ok_or_else(|| {
                io::Error::new(io::ErrorKind::InvalidInput, "iter must address num_wp")
            })?;
            state_arrays_to_unstructured_mesh(
                nma,
                nwa,
                &self.mp_new,
                &self.wp_new,
                &self.ngrmw_new,
                &self.ngrwm,
                &self.n_ngrwm,
            )
        }
    }

    /// Apply migrated `Array_length_calculation` using the state's base
    /// connectivity, update transition-row and boundary lists, and write the
    /// legacy close-mesh scratch files.
    pub fn apply_array_length_calculation(
        &mut self,
        file_dir: impl AsRef<Path>,
        step: usize,
        set_dis_in: usize,
    ) -> io::Result<RefineArrayLengthCalculationRunReport> {
        let sjx_points = *self
            .num_mp
            .get(1)
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "num_mp[1] is required"))?;
        let lbx_points = *self
            .num_wp
            .get(1)
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "num_wp[1] is required"))?;
        let cells_on_triangle = fortran_rows_to_triangle_major(&self.ngrmw, sjx_points)?;
        if self.n_ngrwm.len() <= lbx_points {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("num_wp[1] {lbx_points} requires one-based n_ngrwm storage"),
            ));
        }
        let mut triangles_on_cell = vec![Vec::<usize>::new(); lbx_points + 1];
        for (cell, target) in triangles_on_cell
            .iter_mut()
            .enumerate()
            .take(lbx_points + 1)
            .skip(1)
        {
            let count = self.n_ngrwm[cell];
            if self.ngrwm.len() <= count
                || self.ngrwm[1..=count].iter().any(|row| row.len() <= cell)
            {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidInput,
                    format!("cell {cell} requires ngrwm rows 1..={count}"),
                ));
            }
            target.extend((1..=count).map(|row| self.ngrwm[row][cell]));
        }
        let report = run_refine_array_length_calculation_fortran_indexed(
            file_dir,
            step,
            set_dis_in,
            self.num_vertex,
            self.num_vertex,
            sjx_points,
            lbx_points,
            &self.mrl_new,
            &self.triangle_neighbors,
            &cells_on_triangle,
            &triangles_on_cell,
            &self.n_ngrwm,
            self.num_tranrow_sjx,
            &self.wp_new,
        )?;
        self.num_tranrow_sjx = report.calculation.halo.num_transition_row_triangles;
        self.bdy_refine = report.calculation.halo.boundary_refine.clone();
        self.bdy_refine_tran = report.calculation.halo.boundary_refine_transition.clone();
        Ok(report)
    }

    /// Apply migrated `OnedivideFour_connection` using the state's current
    /// refinement markers and base triangle connectivity.
    pub fn apply_onedivide_four_connection(&mut self) -> io::Result<OnedivideFourConnectionReport> {
        let sjx_points = *self
            .num_mp
            .get(1)
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "num_mp[1] is required"))?;
        apply_onedivide_four_connection_fortran_indexed(
            self.num_vertex,
            sjx_points,
            &self.ref_sjx,
            &self.ngrmw,
            &mut self.ref_lbx,
            &mut self.mrl_new,
        )
    }

    /// Apply migrated `OnedivideFour_renew` and write child points/connectivity
    /// back into this state's `*_new` arrays.
    pub fn apply_onedivide_four_renew(&mut self) -> io::Result<OnedivideFourRenewReport> {
        apply_onedivide_four_renew_fortran_indexed(
            self.num_vertex,
            self.iter,
            &self.ngrmw,
            &self.ref_sjx,
            &self.num_mp,
            &self.num_wp,
            &mut self.mp_new,
            &mut self.wp_new,
            &mut self.ngrmw_new,
        )
    }

    /// Look up the child triangle pair corresponding to a parent triangle/cell
    /// pair using the state's current `sjx_child` and renewed connectivity.
    pub fn lookup_m1w1_to_m11w11(&self, m1: usize, w1: usize) -> io::Result<M1W1LookupReport> {
        let max_triangle = self.num_mp.get(self.iter).copied().unwrap_or_else(|| {
            self.ngrmw_new
                .get(1)
                .map_or(0, |row| row.len().saturating_sub(1))
        });
        lookup_m1w1_to_m11w11_fortran_indexed(
            m1,
            w1,
            &self.sjx_child,
            &self.ngrmw_new,
            max_triangle,
        )
    }

    /// Apply migrated `weak_concav_pair_special` to the state's weak-concavity
    /// pair and temporary segment workspace.
    pub fn apply_weak_concav_pair_special(
        &mut self,
        num_weak_concav_pair: usize,
        num_ref_weak_concav: usize,
    ) -> io::Result<WeakConcavPairSpecialReport> {
        let max_triangle = self
            .iter
            .checked_sub(1)
            .and_then(|idx| self.num_mp.get(idx))
            .copied()
            .filter(|&value| value > 0)
            .unwrap_or_else(|| {
                self.ngrmw
                    .get(1)
                    .map_or(0, |row| row.len().saturating_sub(1))
            });
        apply_weak_concav_pair_special_fortran_indexed(
            num_weak_concav_pair,
            num_ref_weak_concav,
            max_triangle,
            &self.triangle_neighbors,
            &self.ngrmw,
            &mut self.mrl_new,
            &mut self.ref_sjx,
            &mut self.weak_concav_pair,
            &mut self.weak_concav_segment,
        )
    }

    /// Apply migrated `Delaunay_Lop` to the state's queued LOP reference
    /// segment and renewed geometry/connectivity arrays.
    pub fn apply_delaunay_lop(&mut self) -> io::Result<DelaunayLopReport> {
        apply_delaunay_lop_fortran_indexed(
            self.iter,
            self.num_ref,
            &self.num_mp,
            &self.num_wp,
            &mut self.mp_new,
            &mut self.wp_new,
            &mut self.ngrmw_new,
            &self.ref_sjx_segment,
        )
    }

    /// Apply migrated `sharp_concav_lop_judge` to the state's boundary-refine
    /// segment work arrays and accumulated LOP reference count.
    pub fn apply_sharp_concav_lop_judge(
        &mut self,
        num_bdy_refine_segment: usize,
    ) -> io::Result<SharpConcavLopJudgeReport> {
        let max_triangle = self.num_mp.get(self.iter).copied().unwrap_or_else(|| {
            self.ngrmw_new
                .get(1)
                .map_or(0, |row| row.len().saturating_sub(1))
        });
        apply_sharp_concav_lop_judge_fortran_indexed(
            &mut self.num_ref,
            num_bdy_refine_segment,
            max_triangle,
            &self.mrl_new,
            &self.triangle_neighbors,
            &self.ngrmw_new,
            &self.sjx_child,
            &self.bdy_refine_segment,
            &self.bdy_refine_segment_old,
            &self.n_bdy_refine_segment,
            &mut self.ref_sjx_segment_temp,
            &mut self.n_ref_sjx_segment_temp,
        )
    }

    /// Apply migrated `weak_concav_lop_judge` to the state's weak-concavity
    /// LOP work arrays and accumulated LOP reference count.
    pub fn apply_weak_concav_lop_judge(
        &mut self,
        num_bdy_refine_segment: usize,
        num_ref_weak_concav: usize,
        num_weak_concav_segment: usize,
        num_weak_concav_pair: usize,
    ) -> io::Result<SharpConcavLopJudgeReport> {
        let max_triangle = self.num_mp.get(self.iter).copied().unwrap_or_else(|| {
            self.ngrmw_new
                .get(1)
                .map_or(0, |row| row.len().saturating_sub(1))
        });
        apply_weak_concav_lop_judge_fortran_indexed(
            &mut self.num_ref,
            num_bdy_refine_segment,
            num_ref_weak_concav,
            num_weak_concav_segment,
            num_weak_concav_pair,
            max_triangle,
            &self.mrl_new,
            &self.triangle_neighbors,
            &self.ngrmw_new,
            &self.sjx_child,
            &mut self.weak_concav_segment,
            &self.weak_concav_segment_old,
            &self.n_weak_concav_segment,
            &self.weak_concav_pair,
            &mut self.ref_sjx_segment_temp,
            &mut self.n_ref_sjx_segment_temp,
        )
    }

    /// Apply migrated `ref_sjx_isreverse_judge` to the state's transition
    /// segment workspace and replace `ref_sjx` with the returned markers.
    pub fn apply_isreverse_judge(&mut self, set_dis_in: usize) -> io::Result<IsreverseJudgeReport> {
        let report = apply_isreverse_judge_fortran_indexed(
            set_dis_in,
            self.n_segments.len(),
            &self.triangle_neighbors,
            &self.mrl_new,
            &mut self.segments,
            &self.n_segments,
        )?;
        self.ref_sjx = report.ref_sjx.clone();
        Ok(report)
    }

    /// Apply migrated `OnedivideTwo` and write transition child geometry plus
    /// `sjx_child` mapping back into this state.
    pub fn apply_onedivide_two(&mut self, is_reverse: bool) -> io::Result<OnedivideTwoReport> {
        if let Some(&old_mp) = self
            .iter
            .checked_sub(1)
            .and_then(|idx| self.num_mp.get(idx))
        {
            if self.sjx_child.len() <= old_mp {
                self.sjx_child.resize(old_mp + 1, [0, 0]);
            }
        }
        apply_onedivide_two_fortran_indexed(
            self.iter,
            is_reverse,
            self.num_vertex,
            &self.num_mp,
            &self.num_wp,
            &self.triangle_neighbors,
            &self.ngrmw,
            &self.ref_sjx,
            &self.mrl_new,
            &mut self.mp_new,
            &mut self.wp_new,
            &mut self.ngrmw_new,
            &mut self.sjx_child,
        )
    }

    /// Apply the migrated `NGR_RENEW` adapter to this working state and store
    /// the final compacted arrays in `*_f` fields.
    pub fn apply_ngr_renew(&mut self) -> io::Result<NgrRenewReport> {
        let report = apply_ngr_renew_fortran_indexed(
            self.iter,
            self.num_vertex,
            &self.num_mp,
            &self.num_wp,
            &self.mp_new,
            &self.wp_new,
            &self.ngrmw_new,
            &mut self.mp_f,
            &mut self.wp_f,
            &mut self.ngrmw_f,
            &mut self.ngrwm_f,
            &mut self.n_ngrwm_f,
            &mut self.bdy_refine,
            &mut self.bdy_refine_tran,
        )?;
        self.num_sjx = report.num_sjx;
        self.num_dbx = report.num_dbx;
        Ok(report)
    }
}

fn derive_triangle_neighbors_from_one_based_membership(
    num_triangles: usize,
    num_vertices: usize,
    ngrmw: &[Vec<usize>],
    ngrwm: &[Vec<usize>],
    n_ngrwm: &[usize],
) -> Vec<Vec<usize>> {
    let mut neighbors = vec![vec![0_usize; 3]; num_triangles + 1];
    if ngrmw.len() <= 3 || n_ngrwm.len() <= num_vertices {
        return neighbors;
    }
    for triangle in 1..=num_triangles {
        if ngrmw[1..=3].iter().any(|row| row.len() <= triangle) {
            continue;
        }
        let cells = [ngrmw[1][triangle], ngrmw[2][triangle], ngrmw[3][triangle]];
        for &cell in &cells {
            if cell == 0 || cell > num_vertices || cell >= n_ngrwm.len() {
                continue;
            }
            let count = n_ngrwm[cell];
            if ngrwm.len() <= count || ngrwm[1..=count].iter().any(|row| row.len() <= cell) {
                continue;
            }
            for row in 1..=count {
                let candidate = ngrwm[row][cell];
                if candidate == 0 || candidate == triangle || candidate > num_triangles {
                    continue;
                }
                if ngrmw[1..=3].iter().any(|row| row.len() <= candidate) {
                    continue;
                }
                let candidate_cells = [
                    ngrmw[1][candidate],
                    ngrmw[2][candidate],
                    ngrmw[3][candidate],
                ];
                let shared = cells
                    .iter()
                    .filter(|&&triangle_cell| {
                        triangle_cell != 0 && candidate_cells.contains(&triangle_cell)
                    })
                    .count();
                if shared != 2 {
                    continue;
                }
                if let Some(slot) = cells
                    .iter()
                    .position(|triangle_cell| !candidate_cells.contains(triangle_cell))
                {
                    neighbors[triangle][slot] = candidate;
                }
            }
        }
    }
    neighbors
}

fn state_arrays_to_unstructured_mesh(
    num_triangles: usize,
    num_vertices: usize,
    triangle_points: &[LonLatPoint],
    vertex_points: &[LonLatPoint],
    cells_on_triangle_rows: &[Vec<usize>],
    triangles_on_cell_rows: &[Vec<usize>],
    n_triangles_on_cell: &[usize],
) -> io::Result<UnstructuredMesh> {
    if triangle_points.len() <= num_triangles || vertex_points.len() <= num_vertices {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "point arrays must include one-based final slots",
        ));
    }
    if cells_on_triangle_rows.len() <= 3
        || cells_on_triangle_rows[1..=3]
            .iter()
            .any(|row| row.len() <= num_triangles)
    {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "ngrmw rows must include one-based final triangle slots",
        ));
    }
    if n_triangles_on_cell.len() <= num_vertices {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "n_ngrwm must include one-based final vertex slots",
        ));
    }
    if triangles_on_cell_rows
        .iter()
        .any(|row| row.len() <= num_vertices)
    {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "ngrwm rows must include one-based final vertex slots",
        ));
    }

    let m_points = triangle_points[1..=num_triangles].to_vec();
    let w_points = vertex_points[1..=num_vertices].to_vec();
    let m_to_w = (1..=num_triangles)
        .map(|triangle| {
            [
                cells_on_triangle_rows[1][triangle] as i32,
                cells_on_triangle_rows[2][triangle] as i32,
                cells_on_triangle_rows[3][triangle] as i32,
            ]
        })
        .collect();
    let n_w_to_m = n_triangles_on_cell[1..=num_vertices]
        .iter()
        .map(|&count| count as i32)
        .collect();
    let w_to_m = (1..=num_vertices)
        .map(|vertex| {
            triangles_on_cell_rows
                .iter()
                .skip(1)
                .map(|row| row[vertex] as i32)
                .collect()
        })
        .collect();

    Ok(UnstructuredMesh {
        m_points,
        w_points,
        m_to_w,
        w_to_m,
        n_w_to_m,
    })
}

/// Port of `MOD_refine.F90:OnedivideFour_connection`.
///
/// Inputs use the same one-based/sentinel layout as the Fortran arrays:
/// `ref_sjx[1..=sjx_points]`, `mrl_new[1..=sjx_points]`, and
/// `ngrmw[1..=3][1..=sjx_points]`.  Selected, still-unrefined triangles after
/// `num_vertex` are marked `4`, and their three polygon vertices are marked in
/// `ref_lbx`.
pub fn apply_onedivide_four_connection_fortran_indexed(
    num_vertex: usize,
    sjx_points: usize,
    ref_sjx: &[i32],
    ngrmw: &[Vec<usize>],
    ref_lbx: &mut [i32],
    mrl_new: &mut [i32],
) -> io::Result<OnedivideFourConnectionReport> {
    if ref_sjx.len() <= sjx_points || mrl_new.len() <= sjx_points {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "sjx_points {sjx_points} requires one-based ref_sjx and mrl_new arrays with length at least {}",
                sjx_points + 1
            ),
        ));
    }
    if ngrmw.len() <= 3 || ngrmw[1..=3].iter().any(|row| row.len() <= sjx_points) {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "sjx_points {sjx_points} requires one-based ngrmw rows 1..3 with length at least {}",
                sjx_points + 1
            ),
        ));
    }
    if num_vertex >= sjx_points {
        return Ok(OnedivideFourConnectionReport {
            marked_triangles: Vec::new(),
            marked_vertices: Vec::new(),
        });
    }

    let mut marked_triangles = Vec::new();
    let mut marked_vertices = Vec::new();
    for i in (num_vertex + 1)..=sjx_points {
        if ref_sjx[i] == 0 || mrl_new[i] != 1 {
            continue;
        }
        for row in ngrmw.iter().take(4).skip(1) {
            let w = row[i];
            if w == 0 || w >= ref_lbx.len() {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidInput,
                    format!("ngrmw vertex id {w} for triangle {i} is outside ref_lbx"),
                ));
            }
            ref_lbx[w] = 1;
            if !marked_vertices.contains(&w) {
                marked_vertices.push(w);
            }
        }
        mrl_new[i] = 4;
        marked_triangles.push(i);
    }

    Ok(OnedivideFourConnectionReport {
        marked_triangles,
        marked_vertices,
    })
}

/// Port of the non-dateline coordinate/connectivity core from
/// `MOD_refine.F90:OnedivideFour_renew`.
///
/// Inputs keep the same one-based/sentinel layout as the Fortran arrays.
/// `num_mp[1]`/`num_wp[1]` are the pre-renewal counts and `num_mp[iter]` /
/// `num_wp[iter]` are the allocated post-renewal capacities.  Dateline
/// `CheckCrossing`/`crossline_check` behavior is intentionally rejected here
/// until covered by an explicit fixture.
pub fn apply_onedivide_four_renew_fortran_indexed(
    num_vertex: usize,
    iter: usize,
    ngrmw: &[Vec<usize>],
    ref_sjx_segment: &[i32],
    num_mp: &[usize],
    num_wp: &[usize],
    mp_new: &mut [LonLatPoint],
    wp_new: &mut [LonLatPoint],
    ngrmw_new: &mut [Vec<usize>],
) -> io::Result<OnedivideFourRenewReport> {
    if iter == 0
        || iter >= num_mp.len()
        || iter >= num_wp.len()
        || num_mp.len() <= 1
        || num_wp.len() <= 1
    {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("iter {iter} requires one-based num_mp/num_wp arrays with slots 1 and iter"),
        ));
    }
    let old_mp = num_mp[1];
    let old_wp = num_wp[1];
    let new_mp_capacity = num_mp[iter];
    let new_wp_capacity = num_wp[iter];
    if ref_sjx_segment.len() <= old_mp || mp_new.len() <= new_mp_capacity {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "num_mp[1] {old_mp} and num_mp[{iter}] {new_mp_capacity} require one-based ref_sjx_segment/mp_new storage"
            ),
        ));
    }
    if wp_new.len() <= new_wp_capacity {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("num_wp[{iter}] {new_wp_capacity} requires one-based wp_new storage"),
        ));
    }
    if ngrmw.len() <= 3 || ngrmw[1..=3].iter().any(|row| row.len() <= old_mp) {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "num_mp[1] {old_mp} requires one-based ngrmw rows 1..3 with length at least {}",
                old_mp + 1
            ),
        ));
    }
    if ngrmw_new.len() <= 3
        || ngrmw_new[1..=3]
            .iter()
            .any(|row| row.len() <= new_mp_capacity)
    {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "num_mp[{iter}] {new_mp_capacity} requires one-based ngrmw_new rows 1..3 with length at least {}",
                new_mp_capacity + 1
            ),
        ));
    }

    let mut refined_triangles = Vec::new();
    let mut new_triangle_ids = Vec::new();
    let mut new_vertex_ids = Vec::new();
    let mut dateline_adjusted = false;
    let mut refed_iter = 0usize;
    for i in (num_vertex + 1)..=old_mp {
        if ref_sjx_segment[i] == 0 {
            continue;
        }
        let source_vertices = [ngrmw[1][i], ngrmw[2][i], ngrmw[3][i]];
        for &w in &source_vertices {
            if w == 0 || w > old_wp || w >= wp_new.len() {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidInput,
                    format!("ngrmw vertex id {w} for triangle {i} is outside wp_new"),
                ));
            }
        }

        let mut sjx = [
            wp_new[source_vertices[0]],
            wp_new[source_vertices[1]],
            wp_new[source_vertices[2]],
        ];
        let min_lon = sjx.iter().map(|p| p.lon).fold(f64::INFINITY, f64::min);
        let max_lon = sjx.iter().map(|p| p.lon).fold(f64::NEG_INFINITY, f64::max);
        let crosses_dateline = max_lon - min_lon > 180.0;
        if crosses_dateline {
            check_crossing_fortran_points(&mut sjx);
            dateline_adjusted = true;
        }

        let m0 = old_mp + refed_iter * 4;
        let w0 = old_wp + refed_iter * 3;
        if m0 + 4 > new_mp_capacity || w0 + 3 > new_wp_capacity {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!(
                    "renewal for triangle {i} would write m{}..m{} and w{}..w{} beyond allocated capacities",
                    m0 + 1,
                    m0 + 4,
                    w0 + 1,
                    w0 + 3
                ),
            ));
        }

        let mut newdbx = [
            midpoint(sjx[1], sjx[2]),
            midpoint(sjx[0], sjx[2]),
            midpoint(sjx[0], sjx[1]),
        ];
        let mut newsjx = [
            centroid3(sjx[0], newdbx[1], newdbx[2]),
            centroid3(sjx[1], newdbx[0], newdbx[2]),
            centroid3(sjx[2], newdbx[0], newdbx[1]),
            centroid3(newdbx[2], newdbx[0], newdbx[1]),
        ];
        if crosses_dateline {
            check_crossing_fortran_points(&mut newsjx);
            check_crossing_fortran_points(&mut newdbx);
        }

        for (offset, point) in newdbx.into_iter().enumerate() {
            wp_new[w0 + offset + 1] = point;
            new_vertex_ids.push(w0 + offset + 1);
        }
        for (offset, point) in newsjx.into_iter().enumerate() {
            mp_new[m0 + offset + 1] = point;
            new_triangle_ids.push(m0 + offset + 1);
        }

        ngrmw_new[2][m0 + 1] = w0 + 3;
        ngrmw_new[3][m0 + 1] = w0 + 2;
        ngrmw_new[2][m0 + 2] = w0 + 1;
        ngrmw_new[3][m0 + 2] = w0 + 3;
        ngrmw_new[2][m0 + 3] = w0 + 2;
        ngrmw_new[3][m0 + 3] = w0 + 1;
        ngrmw_new[1][m0 + 4] = w0 + 1;
        ngrmw_new[2][m0 + 4] = w0 + 2;
        ngrmw_new[3][m0 + 4] = w0 + 3;
        for k in 1..=3 {
            ngrmw_new[k][i] = 1;
            ngrmw_new[1][m0 + k] = ngrmw[k][i];
        }

        refined_triangles.push(i);
        refed_iter += 1;
    }

    crossline_check_fortran_points(iter, num_mp, num_wp, mp_new, wp_new)?;

    Ok(OnedivideFourRenewReport {
        refined_triangles,
        new_triangle_ids,
        new_vertex_ids,
        dateline_adjusted,
    })
}

/// CLI adapter for `MOD_refine.F90:Delaunay_Lop`.
///
/// Fortran stores triangle connectivity as `ngrmw_new(1:3, triangle)` rows.
/// The migrated mesh kernel uses triangle-major rows, so this wrapper is a
/// narrow layout bridge plus an execution report for the refine-loop executor.
#[allow(clippy::too_many_arguments)]
pub fn apply_delaunay_lop_fortran_indexed(
    iter: usize,
    num_ref: usize,
    num_mp: &[usize],
    num_wp: &[usize],
    mp_new: &mut [LonLatPoint],
    wp_new: &mut [LonLatPoint],
    ngrmw_new: &mut [Vec<usize>],
    ref_sjx_segment: &[usize],
) -> io::Result<DelaunayLopReport> {
    if iter == 0 || iter >= num_mp.len() || iter >= num_wp.len() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("iter {iter} must address num_mp/num_wp previous and current slots"),
        ));
    }
    if num_ref >= ref_sjx_segment.len() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "num_ref must address one-based ref_sjx_segment entries",
        ));
    }
    let old_mp = num_mp[iter - 1];
    let new_mp = num_mp[iter];
    let new_wp = num_wp[iter];
    if mp_new.len() <= new_mp || wp_new.len() <= new_wp {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("num_mp[{iter}] {new_mp} and num_wp[{iter}] {new_wp} exceed one-based point storage"),
        ));
    }
    if ngrmw_new.len() <= 3 || ngrmw_new[1..=3].iter().any(|row| row.len() <= new_mp) {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("num_mp[{iter}] {new_mp} requires one-based ngrmw_new rows 1..=3"),
        ));
    }

    let mut cells_on_triangle = fortran_rows_to_triangle_major(ngrmw_new, new_mp)?;
    let mut flipped_pairs = Vec::new();
    let mut new_triangle_ids = Vec::new();
    let mut dateline_adjusted = false;
    let mut nonzero_pair_index = 0_usize;
    for k in 1..=(num_ref / 2) {
        let i = ref_sjx_segment[2 * k - 1];
        let j = ref_sjx_segment[2 * k];
        if i == 0 || j == 0 {
            continue;
        }
        if i >= cells_on_triangle.len() || j >= cells_on_triangle.len() {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("LOP pair i={i}, j={j} must address triangle connectivity"),
            ));
        }
        let mut min_lon = f64::INFINITY;
        let mut max_lon = f64::NEG_INFINITY;
        for &vertex in cells_on_triangle[i]
            .iter()
            .chain(cells_on_triangle[j].iter())
        {
            if vertex == 0 || vertex >= wp_new.len() {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidInput,
                    format!("LOP pair i={i}, j={j} references invalid vertex {vertex}"),
                ));
            }
            min_lon = min_lon.min(wp_new[vertex].lon);
            max_lon = max_lon.max(wp_new[vertex].lon);
        }
        dateline_adjusted |= max_lon - min_lon > 180.0;
        flipped_pairs.push((i, j));
        let m1 = old_mp + nonzero_pair_index * 2 + 1;
        let m2 = old_mp + nonzero_pair_index * 2 + 2;
        if m2 > new_mp {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("LOP pair i={i}, j={j} exceeds allocated child triangle storage"),
            ));
        }
        new_triangle_ids.extend([m1, m2]);
        nonzero_pair_index += 1;
    }

    let mut triangle_points: Vec<LonLatDegrees> = mp_new
        .iter()
        .map(|point| LonLatDegrees::new(point.lon, point.lat))
        .collect();
    let mut cell_points: Vec<LonLatDegrees> = wp_new
        .iter()
        .map(|point| LonLatDegrees::new(point.lon, point.lat))
        .collect();

    refine_delaunay_lop_mesh_fortran_indexed(
        iter,
        num_ref,
        num_mp,
        num_wp,
        &mut triangle_points,
        &mut cell_points,
        &mut cells_on_triangle,
        ref_sjx_segment,
    )?;

    for triangle in 1..=new_mp {
        ngrmw_new[1][triangle] = cells_on_triangle[triangle][0];
        ngrmw_new[2][triangle] = cells_on_triangle[triangle][1];
        ngrmw_new[3][triangle] = cells_on_triangle[triangle][2];
    }
    for triangle in 1..=new_mp {
        mp_new[triangle] = LonLatPoint {
            lon: triangle_points[triangle].lon_degrees,
            lat: triangle_points[triangle].lat_degrees,
        };
    }
    for vertex in 1..=new_wp {
        wp_new[vertex] = LonLatPoint {
            lon: cell_points[vertex].lon_degrees,
            lat: cell_points[vertex].lat_degrees,
        };
    }

    Ok(DelaunayLopReport {
        flipped_pairs,
        new_triangle_ids,
        dateline_adjusted,
    })
}

/// CLI adapter for `MOD_refine.F90:NGR_RENEW`.
///
/// The migrated mesh kernel owns the deduplication, triangle compaction, final
/// adjacency rebuild, and `GetSortNew` ordering. This wrapper allocates and
/// writes the surrounding CLI state back into the same one-based row layout as
/// the Fortran allocatables: `ngrmw_f(1:3, triangle)` and
/// `ngrwm_f(1:capacity, vertex)`.
#[allow(clippy::too_many_arguments)]
pub fn apply_ngr_renew_fortran_indexed(
    iter: usize,
    num_vertex: usize,
    num_mp: &[usize],
    num_wp: &[usize],
    mp_new: &[LonLatPoint],
    wp_new: &[LonLatPoint],
    ngrmw_new: &[Vec<usize>],
    mp_f: &mut Vec<LonLatPoint>,
    wp_f: &mut Vec<LonLatPoint>,
    ngrmw_f: &mut Vec<Vec<usize>>,
    ngrwm_f: &mut Vec<Vec<usize>>,
    n_ngrwm_f: &mut Vec<usize>,
    bdy_refine: &mut Vec<usize>,
    bdy_refine_tran: &mut Vec<usize>,
) -> io::Result<NgrRenewReport> {
    if iter == 0 || iter >= num_mp.len() || iter >= num_wp.len() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("iter {iter} must address num_mp/num_wp previous and current slots"),
        ));
    }
    let new_mp = num_mp[iter];
    let new_wp = num_wp[iter];
    if mp_new.len() <= new_mp || wp_new.len() <= new_wp {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("num_mp[{iter}] {new_mp} and num_wp[{iter}] {new_wp} exceed one-based point storage"),
        ));
    }
    let cells_on_triangle_new = fortran_rows_to_triangle_major(ngrmw_new, new_mp)?;
    let triangle_points_new: Vec<LonLatDegrees> = mp_new
        .iter()
        .map(|point| LonLatDegrees::new(point.lon, point.lat))
        .collect();
    let cell_points_new: Vec<LonLatDegrees> = wp_new
        .iter()
        .map(|point| LonLatDegrees::new(point.lon, point.lat))
        .collect();

    let renewed = refine_ngr_renew_mesh_fortran_indexed(
        iter,
        num_vertex,
        num_mp,
        num_wp,
        &triangle_points_new,
        &cell_points_new,
        &cells_on_triangle_new,
        bdy_refine,
        bdy_refine_tran,
    )?;

    *mp_f = vec![LonLatPoint { lon: 0.0, lat: 0.0 }; renewed.num_sjx + 1];
    for triangle in 1..=renewed.num_sjx {
        mp_f[triangle] = LonLatPoint {
            lon: renewed.triangle_points[triangle].lon_degrees,
            lat: renewed.triangle_points[triangle].lat_degrees,
        };
    }

    *wp_f = vec![
        LonLatPoint {
            lon: 9999.0,
            lat: 9999.0
        };
        renewed.num_dbx + 1
    ];
    for vertex in 1..=renewed.num_dbx {
        wp_f[vertex] = LonLatPoint {
            lon: renewed.cell_points[vertex].lon_degrees,
            lat: renewed.cell_points[vertex].lat_degrees,
        };
    }

    *ngrmw_f = vec![vec![1_usize; renewed.num_sjx + 1]; 4];
    for triangle in 1..=renewed.num_sjx {
        ngrmw_f[1][triangle] = renewed.cells_on_triangle[triangle][0];
        ngrmw_f[2][triangle] = renewed.cells_on_triangle[triangle][1];
        ngrmw_f[3][triangle] = renewed.cells_on_triangle[triangle][2];
    }

    *n_ngrwm_f = renewed.n_triangles_on_cell.clone();
    let adjacency_capacity = 7_usize.max(
        renewed
            .n_triangles_on_cell
            .iter()
            .take(renewed.num_dbx + 1)
            .copied()
            .max()
            .unwrap_or(0),
    );
    *ngrwm_f = vec![vec![1_usize; renewed.num_dbx + 1]; adjacency_capacity + 1];
    for vertex in 1..=renewed.num_dbx {
        for (offset, &triangle) in renewed.triangles_on_cell[vertex].iter().enumerate() {
            ngrwm_f[offset + 1][vertex] = triangle;
        }
    }

    *bdy_refine = renewed.boundary_refine.clone();
    *bdy_refine_tran = renewed.boundary_refine_transition.clone();

    Ok(NgrRenewReport {
        num_sjx: renewed.num_sjx,
        num_dbx: renewed.num_dbx,
        vertex_mapping: renewed.vertex_mapping,
        adjacency_capacity,
        boundary_refine: bdy_refine.clone(),
        boundary_refine_transition: bdy_refine_tran.clone(),
    })
}

/// CLI adapter for `MOD_refine.F90:m1w1_to_m11w11`.
///
/// The mesh kernel consumes triangle-major child connectivity; refine-loop
/// state keeps `ngrmw_new(1:3, triangle)` rows. This adapter only converts the
/// layout and reports whether a valid child edge pair was found.
pub fn lookup_m1w1_to_m11w11_fortran_indexed(
    m1: usize,
    w1: usize,
    sjx_child: &[[usize; 2]],
    ngrmw_new: &[Vec<usize>],
    num_mp: usize,
) -> io::Result<M1W1LookupReport> {
    let cells_on_triangle_new = fortran_rows_to_triangle_major(ngrmw_new, num_mp)?;
    let child_pair =
        refine_m1w1_to_m11w11_mesh_fortran_indexed(m1, w1, sjx_child, &cells_on_triangle_new)?;
    Ok(M1W1LookupReport {
        parent_pair: (m1, w1),
        child_pair,
    })
}

/// CLI adapter for `MOD_refine.F90:weak_concav_pair_special`.
///
/// Converts `ngrmw(1:3, triangle)` rows to the mesh kernel's triangle-major
/// connectivity, then leaves all mutable weak-concavity state in-place exactly
/// where the refine-loop executor owns it.
#[allow(clippy::too_many_arguments)]
pub fn apply_weak_concav_pair_special_fortran_indexed(
    num_weak_concav_pair: usize,
    num_ref_weak_concav: usize,
    max_triangle: usize,
    triangle_neighbors: &[Vec<usize>],
    ngrmw: &[Vec<usize>],
    mrl_new: &mut [i32],
    ref_sjx: &mut [i32],
    weak_concav_pair: &mut [[usize; 2]],
    weak_concav_segment: &mut [Vec<usize>],
) -> io::Result<WeakConcavPairSpecialReport> {
    let cells_on_triangle = fortran_rows_to_triangle_major(ngrmw, max_triangle)?;
    let previous_mrl = mrl_new.to_vec();
    let previous_ref_sjx = ref_sjx.to_vec();
    let previous_segments = weak_concav_segment.to_vec();

    refine_weak_concav_pair_special_mesh_fortran_indexed(
        num_weak_concav_pair,
        num_ref_weak_concav,
        triangle_neighbors,
        &cells_on_triangle,
        mrl_new,
        ref_sjx,
        weak_concav_pair,
        weak_concav_segment,
    )?;

    let updated_pairs = weak_concav_pair
        .iter()
        .take(num_weak_concav_pair + 1)
        .skip(1)
        .copied()
        .collect();
    let marked_ref_sjx_triangles = ref_sjx
        .iter()
        .zip(previous_ref_sjx.iter())
        .enumerate()
        .filter_map(|(triangle, (&after, &before))| (after != before).then_some(triangle))
        .collect();
    let deferred_renew_triangles = mrl_new
        .iter()
        .zip(previous_mrl.iter())
        .enumerate()
        .filter_map(|(triangle, (&after, &before))| (after != before).then_some(triangle))
        .collect();
    let segment_first_slots = weak_concav_segment
        .iter()
        .zip(previous_segments.iter())
        .enumerate()
        .filter_map(|(segment_id, (after, before))| {
            if after.first() != before.first() {
                after
                    .first()
                    .copied()
                    .map(|triangle| (segment_id, triangle))
            } else {
                None
            }
        })
        .collect();

    Ok(WeakConcavPairSpecialReport {
        updated_pairs,
        marked_ref_sjx_triangles,
        deferred_renew_triangles,
        segment_first_slots,
    })
}

/// CLI adapter for `MOD_refine.F90:sharp_concav_lop_judge`.
///
/// Converts `ngrmw_new(1:3, triangle)` rows into the triangle-major child
/// connectivity expected by the mesh kernel, then reports the segment entries
/// written back into the caller-owned temporary LOP segment matrices.
#[allow(clippy::too_many_arguments)]
pub fn apply_sharp_concav_lop_judge_fortran_indexed(
    num_ref: &mut usize,
    num_bdy_refine_segment: usize,
    max_triangle: usize,
    mrl_new: &[i32],
    triangle_neighbors: &[Vec<usize>],
    ngrmw_new: &[Vec<usize>],
    sjx_child: &[[usize; 2]],
    bdy_refine_segment: &[Vec<usize>],
    bdy_refine_segment_old: &[Vec<usize>],
    n_bdy_refine_segment: &[usize],
    ref_sjx_segment_temp: &mut [Vec<usize>],
    n_ref_sjx_segment_temp: &mut [usize],
) -> io::Result<SharpConcavLopJudgeReport> {
    let before_num_ref = *num_ref;
    let cells_on_triangle_new = fortran_rows_to_triangle_major(ngrmw_new, max_triangle)?;

    refine_sharp_concav_lop_judge_mesh_fortran_indexed(
        num_ref,
        num_bdy_refine_segment,
        mrl_new,
        triangle_neighbors,
        &cells_on_triangle_new,
        sjx_child,
        bdy_refine_segment,
        bdy_refine_segment_old,
        n_bdy_refine_segment,
        ref_sjx_segment_temp,
        n_ref_sjx_segment_temp,
    )?;

    let mut segment_lengths = Vec::new();
    let mut written_segments = Vec::new();
    for segment_id in 1..=num_bdy_refine_segment {
        let length = n_ref_sjx_segment_temp[segment_id];
        if length == 0 {
            continue;
        }
        segment_lengths.push((segment_id, length));
        let segment_values = ref_sjx_segment_temp[segment_id][1..=length].to_vec();
        if segment_values.iter().any(|&value| value != 0) {
            written_segments.push((segment_id, segment_values));
        }
    }

    Ok(SharpConcavLopJudgeReport {
        num_ref_added: *num_ref - before_num_ref,
        segment_lengths,
        written_segments,
    })
}

/// CLI adapter for `MOD_refine.F90:weak_concav_lop_judge`.
///
/// Converts `ngrmw_new(1:3, triangle)` rows into the triangle-major child
/// connectivity expected by the mesh kernel, then reports the weak-concavity
/// temporary LOP segment rows written by the kernel.
#[allow(clippy::too_many_arguments)]
pub fn apply_weak_concav_lop_judge_fortran_indexed(
    num_ref: &mut usize,
    num_bdy_refine_segment: usize,
    num_ref_weak_concav: usize,
    num_weak_concav_segment: usize,
    num_weak_concav_pair: usize,
    max_triangle: usize,
    mrl_new: &[i32],
    triangle_neighbors: &[Vec<usize>],
    ngrmw_new: &[Vec<usize>],
    sjx_child: &[[usize; 2]],
    weak_concav_segment: &mut [Vec<usize>],
    weak_concav_segment_old: &[Vec<usize>],
    n_weak_concav_segment: &[usize],
    weak_concav_pair: &[[usize; 2]],
    ref_sjx_segment_temp: &mut [Vec<usize>],
    n_ref_sjx_segment_temp: &mut [usize],
) -> io::Result<SharpConcavLopJudgeReport> {
    let before_num_ref = *num_ref;
    let cells_on_triangle_new = fortran_rows_to_triangle_major(ngrmw_new, max_triangle)?;

    refine_weak_concav_lop_judge_mesh_fortran_indexed(
        num_ref,
        num_bdy_refine_segment,
        num_ref_weak_concav,
        num_weak_concav_segment,
        num_weak_concav_pair,
        mrl_new,
        triangle_neighbors,
        &cells_on_triangle_new,
        sjx_child,
        weak_concav_segment,
        weak_concav_segment_old,
        n_weak_concav_segment,
        weak_concav_pair,
        ref_sjx_segment_temp,
        n_ref_sjx_segment_temp,
    )?;

    let mut segment_lengths = Vec::new();
    let mut written_segments = Vec::new();
    for (segment_id, &length) in n_ref_sjx_segment_temp.iter().enumerate().skip(1) {
        if length == 0 {
            continue;
        }
        segment_lengths.push((segment_id, length));
        let segment_values = ref_sjx_segment_temp[segment_id][1..=length].to_vec();
        if segment_values.iter().any(|&value| value != 0) {
            written_segments.push((segment_id, segment_values));
        }
    }

    Ok(SharpConcavLopJudgeReport {
        num_ref_added: *num_ref - before_num_ref,
        segment_lengths,
        written_segments,
    })
}

/// CLI adapter for `MOD_refine.F90:ref_sjx_isreverse_judge`.
///
/// The underlying mesh kernel owns the Fortran-indexed neighbor/segment logic;
/// this wrapper adds execution evidence useful for stitching the transition-row
/// loop into the CLI refine-loop executor.
pub fn apply_isreverse_judge_fortran_indexed(
    set_dis_in: usize,
    num_segment: usize,
    triangle_neighbors: &[Vec<usize>],
    mrl_new: &[i32],
    segments: &mut [Vec<usize>],
    n_segments: &[usize],
) -> io::Result<IsreverseJudgeReport> {
    let ref_sjx = refine_isreverse_judge_mesh_fortran_indexed(
        set_dis_in,
        num_segment,
        triangle_neighbors,
        mrl_new,
        segments,
        n_segments,
    )?;
    let marked_triangles = ref_sjx
        .iter()
        .enumerate()
        .filter_map(|(triangle, &marker)| (marker != 0).then_some(triangle))
        .collect();
    let mut active_segments = Vec::new();
    let mut rewritten_segments = Vec::new();
    for segment_id in 0..num_segment.min(segments.len()).min(n_segments.len()) {
        if n_segments[segment_id] == 0 {
            continue;
        }
        active_segments.push(segment_id);
        rewritten_segments.push(segments[segment_id].clone());
    }

    Ok(IsreverseJudgeReport {
        ref_sjx,
        marked_triangles,
        active_segments,
        rewritten_segments,
    })
}

/// CLI adapter for `MOD_refine.F90:OnedivideTwo`.
///
/// The pure mesh kernel uses triangle-major `[[w1,w2,w3]]` rows and
/// `LonLatDegrees`.  This wrapper keeps the surrounding CLI/refine-loop state
/// in the Fortran-compatible row-major `ngrmw(1:3, triangle)` layout and the
/// local `LonLatPoint` type, then writes the mutated connectivity rows back to
/// `ngrmw_new`.
#[allow(clippy::too_many_arguments)]
pub fn apply_onedivide_two_fortran_indexed(
    iter: usize,
    is_reverse: bool,
    num_vertex: usize,
    num_mp: &[usize],
    num_wp: &[usize],
    triangle_neighbors: &[Vec<usize>],
    ngrmw: &[Vec<usize>],
    ref_sjx: &[i32],
    mrl_new: &[i32],
    mp_new: &mut [LonLatPoint],
    wp_new: &mut [LonLatPoint],
    ngrmw_new: &mut [Vec<usize>],
    sjx_child: &mut [[usize; 2]],
) -> io::Result<OnedivideTwoReport> {
    if iter == 0 || iter >= num_mp.len() || iter >= num_wp.len() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("iter {iter} must address num_mp/num_wp previous and current slots"),
        ));
    }
    let old_mp = num_mp[iter - 1];
    let base_mp = *num_mp
        .get(1)
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "num_mp[1] is required"))?;
    let new_mp = num_mp[iter];
    let old_wp = num_wp[iter - 1];
    let new_wp = num_wp[iter];
    if ref_sjx.len() <= base_mp || mrl_new.len() <= base_mp {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("base triangle count {base_mp} requires one-based ref_sjx/mrl_new storage"),
        ));
    }
    if mp_new.len() <= new_mp || wp_new.len() <= new_wp || sjx_child.len() <= base_mp {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("num_mp[{iter}] {new_mp} and num_wp[{iter}] {new_wp} exceed one-based output storage"),
        ));
    }
    if ngrmw.len() <= 3 || ngrmw_new.len() <= 3 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "ngrmw/ngrmw_new must expose one-based rows 1..=3",
        ));
    }
    let parent_ngrmw: &[Vec<usize>] = if ngrmw[1..=3].iter().all(|row| row.len() > base_mp) {
        ngrmw
    } else if ngrmw_new[1..=3].iter().all(|row| row.len() > base_mp) {
        &*ngrmw_new
    } else {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "base triangle count {base_mp} requires ngrmw rows with at least {} columns",
                base_mp + 1
            ),
        ));
    };
    if ngrmw_new[1..=3].iter().any(|row| row.len() <= new_mp) {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "num_mp[{iter}] {new_mp} requires ngrmw_new rows with at least {} columns",
                new_mp + 1
            ),
        ));
    }

    let split_triangles: Vec<usize> = ((num_vertex + 1)..=base_mp)
        .filter(|&triangle| ref_sjx[triangle] != 0)
        .collect();
    let mut new_triangle_ids = Vec::with_capacity(split_triangles.len() * 2);
    let mut new_vertex_ids = Vec::with_capacity(split_triangles.len());
    let mut dateline_adjusted = false;
    for (split_idx, &triangle) in split_triangles.iter().enumerate() {
        let vertex_ids = [
            parent_ngrmw[1][triangle],
            parent_ngrmw[2][triangle],
            parent_ngrmw[3][triangle],
        ];
        let mut min_lon = f64::INFINITY;
        let mut max_lon = f64::NEG_INFINITY;
        for &vertex_id in &vertex_ids {
            if vertex_id == 0 || vertex_id > old_wp || vertex_id >= wp_new.len() {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidInput,
                    format!(
                        "ngrmw vertex id {vertex_id} for triangle {triangle} is outside wp_new"
                    ),
                ));
            }
            min_lon = min_lon.min(wp_new[vertex_id].lon);
            max_lon = max_lon.max(wp_new[vertex_id].lon);
        }
        dateline_adjusted |= max_lon - min_lon > 180.0;
        let m1 = old_mp + split_idx * 2 + 1;
        let m2 = old_mp + split_idx * 2 + 2;
        let w4 = old_wp + split_idx + 1;
        if m2 > new_mp || w4 > new_wp {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!(
                    "one-into-two split for triangle {triangle} exceeds allocated child storage"
                ),
            ));
        }
        new_triangle_ids.extend([m1, m2]);
        new_vertex_ids.push(w4);
    }

    let mut cells_on_triangle = fortran_rows_to_triangle_major(parent_ngrmw, base_mp)?;
    let mut cells_on_triangle_new = fortran_rows_to_triangle_major(ngrmw_new, new_mp)?;
    cells_on_triangle.resize(new_mp + 1, [0, 0, 0]);
    let mut triangle_points: Vec<LonLatDegrees> = mp_new
        .iter()
        .map(|point| LonLatDegrees::new(point.lon, point.lat))
        .collect();
    let mut cell_points: Vec<LonLatDegrees> = wp_new
        .iter()
        .map(|point| LonLatDegrees::new(point.lon, point.lat))
        .collect();

    refine_onedivide_two_mesh_fortran_indexed(
        iter,
        is_reverse,
        num_vertex,
        num_mp,
        num_wp,
        triangle_neighbors,
        &cells_on_triangle,
        ref_sjx,
        mrl_new,
        &mut triangle_points,
        &mut cell_points,
        &mut cells_on_triangle_new,
        sjx_child,
    )?;

    for triangle in 1..=new_mp {
        ngrmw_new[1][triangle] = cells_on_triangle_new[triangle][0];
        ngrmw_new[2][triangle] = cells_on_triangle_new[triangle][1];
        ngrmw_new[3][triangle] = cells_on_triangle_new[triangle][2];
    }
    for triangle in 1..=new_mp {
        mp_new[triangle] = LonLatPoint {
            lon: triangle_points[triangle].lon_degrees,
            lat: triangle_points[triangle].lat_degrees,
        };
    }
    for vertex in 1..=new_wp {
        wp_new[vertex] = LonLatPoint {
            lon: cell_points[vertex].lon_degrees,
            lat: cell_points[vertex].lat_degrees,
        };
    }

    Ok(OnedivideTwoReport {
        split_triangles,
        new_triangle_ids,
        new_vertex_ids,
        dateline_adjusted,
    })
}

fn fortran_rows_to_triangle_major(
    rows: &[Vec<usize>],
    max_triangle: usize,
) -> io::Result<Vec<[usize; 3]>> {
    if rows.len() <= 3 || rows[1..=3].iter().any(|row| row.len() <= max_triangle) {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("triangle count {max_triangle} requires one-based rows 1..=3"),
        ));
    }
    let mut out = vec![[0, 0, 0]; max_triangle + 1];
    for triangle in 1..=max_triangle {
        out[triangle] = [rows[1][triangle], rows[2][triangle], rows[3][triangle]];
    }
    Ok(out)
}

fn midpoint(a: LonLatPoint, b: LonLatPoint) -> LonLatPoint {
    LonLatPoint {
        lon: (a.lon + b.lon) / 2.0,
        lat: (a.lat + b.lat) / 2.0,
    }
}

fn centroid3(a: LonLatPoint, b: LonLatPoint, c: LonLatPoint) -> LonLatPoint {
    LonLatPoint {
        lon: (a.lon + b.lon + c.lon) / 3.0,
        lat: (a.lat + b.lat + c.lat) / 3.0,
    }
}

fn check_crossing_fortran_points(points: &mut [LonLatPoint]) {
    for point in points {
        if point.lon < 0.0 {
            point.lon += 180.0;
        } else {
            point.lon -= 180.0;
        }
    }
}

fn crossline_check_fortran_points(
    iter: usize,
    num_mp: &[usize],
    num_wp: &[usize],
    mp_new: &mut [LonLatPoint],
    wp_new: &mut [LonLatPoint],
) -> io::Result<()> {
    if iter == 0 || iter >= num_mp.len() || iter >= num_wp.len() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("iter {iter} must address num_mp/num_wp previous and current slots"),
        ));
    }
    if num_mp[iter] >= mp_new.len() || num_wp[iter] >= wp_new.len() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "crossline_check range exceeds point storage",
        ));
    }
    for point in mp_new
        .iter_mut()
        .take(num_mp[iter] + 1)
        .skip(num_mp[iter - 1] + 1)
    {
        if point.lon == -180.0 {
            point.lon = 180.0;
        }
    }
    for point in wp_new
        .iter_mut()
        .take(num_wp[iter] + 1)
        .skip(num_wp[iter - 1] + 1)
    {
        if point.lon == -180.0 {
            point.lon = 180.0;
        }
    }
    Ok(())
}

/// Execute the top-level `mkgrd.F90` refine-loop order using a pluggable kernel
/// executor for the heavy migrated/pending geometry branches.
///
/// This owns only orchestration: for each planned step, dispatch
/// `Area_judge_refine/Get_Contain/GetRef` source branches in order, then the
/// `refine_loop` step, then optional final quality check and final domain
/// handoff.  File names and early-exit truncation come from
/// `MkgrdRefineLoopIoPlan`.
pub fn run_mkgrd_refine_loop_execution(
    plan: &MkgrdRefineLoopIoPlan,
    executor: &mut impl MkgrdRefineLoopExecutor,
    postproc_options: Option<MkgrdFinalDomainPostprocOptions<'_>>,
) -> io::Result<MkgrdRefineLoopExecutionReport> {
    run_mkgrd_refine_loop_execution_with_final_domain_contain(
        plan,
        executor,
        None,
        postproc_options,
    )
}

/// Execute the refine loop plus the data_preprocess-derived final-domain
/// handoff. This keeps the final Area_judge write, `Get_Contain(0)` option
/// assembly, and land/ocean postprocess option mapping inside the Rust library
/// boundary instead of the CLI front-end.
pub fn run_mkgrd_refine_loop_execution_with_data_preprocess_final_domain_handoff<'a>(
    plan: &MkgrdRefineLoopIoPlan,
    executor: &mut impl MkgrdRefineLoopExecutor,
    state: &'a MkgrdDataPreprocessSourceState,
    mesh_type: &str,
    area_grid_file: &'a Path,
    mask_sea_ratio: f64,
    output_format: &'a str,
) -> io::Result<MkgrdRefineLoopExecutionReport> {
    let final_postproc_request =
        data_preprocess_source_state_final_postproc_request(state, mesh_type)?;
    let postproc_options = data_preprocess_source_state_final_postproc_options(
        final_postproc_request.as_ref(),
        state,
        mask_sea_ratio,
        output_format,
    )?;
    let contain_options = if matches!(
        postproc_options,
        Some(MkgrdFinalDomainPostprocOptions::Atmos { .. })
    ) {
        None
    } else {
        write_data_preprocess_source_state_final_domain_contain_options(
            state,
            mesh_type,
            area_grid_file,
        )?
    };
    run_mkgrd_refine_loop_execution_with_final_domain_contain(
        plan,
        executor,
        contain_options,
        postproc_options,
    )
}

/// Execute the top-level `mkgrd.F90` refine-loop order and optionally generate
/// the final `Get_Contain(0)` domain containment file before the final
/// `mask_postproc(mesh_type)` handoff.
pub fn run_mkgrd_refine_loop_execution_with_final_domain_contain(
    plan: &MkgrdRefineLoopIoPlan,
    executor: &mut impl MkgrdRefineLoopExecutor,
    contain_options: Option<MkgrdFinalDomainContainOptions<'_>>,
    postproc_options: Option<MkgrdFinalDomainPostprocOptions<'_>>,
) -> io::Result<MkgrdRefineLoopExecutionReport> {
    let mut executed_sources = 0;
    let mut executed_refine_steps = 0;

    for (step_index, step) in plan.steps.iter().enumerate() {
        if !earthmesh_core::progress::report("refine", step_index, plan.steps.len()) {
            return Err(io::Error::new(io::ErrorKind::Interrupted, "cancelled"));
        }
        for source in &step.sources {
            executor.run_source_branch(step, source)?;
            executed_sources += 1;
        }
        if step.run_refine_loop {
            executor.run_refine_loop_step(step)?;
            executed_refine_steps += 1;
        }
        if step.stop_after_step {
            break;
        }
    }

    let effective_plan = effective_mkgrd_refine_loop_io_plan(plan)?;
    let ran_final_quality_check = effective_plan.final_quality_check.run_quality_check;
    if ran_final_quality_check {
        let mut final_quality_check = effective_plan.final_quality_check.clone();
        if let Some(runtime_state) = executor.runtime_state().cloned() {
            enrich_mkgrd_final_quality_with_global_distance_steps_io(
                &mut final_quality_check,
                &runtime_state,
                effective_plan.max_iter,
            )?;
        }
        executor.run_final_quality_check(&final_quality_check)?;
    }

    let final_handoff = run_mkgrd_refine_loop_final_domain_handoff_with_domain_contain(
        &effective_plan,
        contain_options,
        postproc_options,
    )?;
    let mut runtime_state = executor.runtime_state().cloned();
    if let (Some(runtime_state), Some(contain)) = (
        runtime_state.as_mut(),
        final_handoff.generated_contain.as_ref(),
    ) {
        let counts = &contain.runtime_counts;
        runtime_state
            .record_mesh_counts_for_step(
                effective_plan.final_mask_postproc_step,
                counts.current_num_mp_step,
                counts.current_num_wp_step,
            )
            .map_err(|err| io::Error::new(io::ErrorKind::InvalidInput, err))?;
        if counts.previous_num_vertex > 0 {
            runtime_state
                .record_num_vertex(counts.previous_num_vertex)
                .map_err(|err| io::Error::new(io::ErrorKind::InvalidInput, err))?;
        }
    }
    Ok(MkgrdRefineLoopExecutionReport {
        executed_sources,
        source_branch_reports: executor.source_branch_reports().to_vec(),
        runtime_state,
        executed_refine_steps,
        ran_final_quality_check,
        final_handoff,
    })
}

fn validate_mkgrd_refine_loop_controls(refine: &RefineConfig, max_iter: usize) -> io::Result<()> {
    if max_iter >= refine.halo.len() || max_iter >= refine.max_transition_row.len() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "max_iter {max_iter} exceeds one-based refine control table length {}",
                refine.halo.len() - 1
            ),
        ));
    }

    for iter in 1..=max_iter {
        let halo = refine.halo[iter];
        let max_transition_row = refine.max_transition_row[iter];
        if halo < max_transition_row {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("halo({iter}) must be larger than or equal to max_transition_row({iter})"),
            ));
        }
        if halo <= 0 {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("halo({iter}) must be more than zero"),
            ));
        }
        if max_transition_row <= 0 {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("max_transition_row({iter}) must be more than zero"),
            ));
        }
    }
    Ok(())
}

/// Build a non-destructive legacy file path schedule for the top-level
/// `mkgrd.F90` refine loop.  This mirrors the active file names in
/// `Area_judge_refine`, `Get_Contain`, `GetRef`, and `refine_loop` without
/// executing their heavy geometry kernels.
pub fn plan_mkgrd_refine_loop_io(
    config: &EarthmeshConfig,
    refine: &RefineConfig,
) -> io::Result<MkgrdRefineLoopIoPlan> {
    if config.nxp <= 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "NXP must be positive for refine loop",
        ));
    }
    let nxp = usize::try_from(config.nxp)
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "NXP must fit usize"))?;
    let loop_plan = plan_mkgrd_refine_loop(refine)?;
    let file_dir = PathBuf::from(config.file_dir());
    let mesh_type = config.mesh_type.trim().to_string();
    let mode_grid = config.mode_grid.trim().to_string();

    let mut steps = Vec::with_capacity(loop_plan.steps.len());
    for step in &loop_plan.steps {
        let mut sources = Vec::with_capacity(step.sources.len());
        for source in &step.sources {
            sources.push(plan_mkgrd_refine_source_io(
                &file_dir, nxp, &mesh_type, step.step, *source,
            )?);
        }
        steps.push(MkgrdRefineLoopStepIoPlan {
            step: step.step,
            max_transition_row: step.max_transition_row,
            sources,
            refine_loop_input_gridfile: mkgrd_gridfile_path(&file_dir, nxp, step.step, &mode_grid),
            refine_loop_original_tmpfile: mkgrd_tmpfile_path(&file_dir, nxp, step.step, "ori"),
            refine_loop_stage2_tmpfile: mkgrd_tmpfile_path(&file_dir, nxp, step.step, "2"),
            refine_loop_stage5_tmpfile: mkgrd_tmpfile_path(&file_dir, nxp, step.step, "5"),
            refine_loop_output_gridfile: mkgrd_gridfile_path(
                &file_dir,
                nxp,
                step.step + 1,
                &mode_grid,
            ),
            run_refine_loop: step.run_refine_loop,
            stop_after_step: step.stop_after_step,
        });
    }

    let final_step = loop_plan.final_mask_postproc_step;
    let final_quality_check = plan_mkgrd_final_quality_check_io(config, refine, final_step)?;
    let final_mask_postproc_domain =
        matches!(mesh_type.as_str(), "earthmesh" | "landmesh" | "oceanmesh")
            .then(|| {
                plan_mask_postproc_domain_io(
                    &file_dir,
                    nxp,
                    &mode_grid,
                    &mesh_type,
                    config.mask_patch_on,
                )
            })
            .transpose()?;
    Ok(MkgrdRefineLoopIoPlan {
        file_dir: file_dir.clone(),
        nxp,
        mesh_type: mesh_type.clone(),
        mode_grid: mode_grid.clone(),
        max_iter: loop_plan.max_iter,
        steps,
        final_mask_postproc_step: final_step,
        final_get_contain_iter: 0,
        final_domain_gridfile: mkgrd_gridfile_path(&file_dir, nxp, final_step, &mode_grid),
        final_result_gridfile: file_dir
            .join("result")
            .join(format!("gridfile_NXP{nxp:04}_{mode_grid}.nc4")),
        final_domain_contain_output: file_dir.join("contain").join(format!(
            "contain_{mesh_type}_domain_NXP{nxp:04}_{mode_grid}.nc4"
        )),
        final_quality_check,
        final_mask_postproc_domain,
    })
}

pub fn infer_mkgrd_effective_final_step_from_gridfiles(
    plan: &MkgrdRefineLoopIoPlan,
) -> io::Result<usize> {
    let planned_step = plan.final_mask_postproc_step;
    if planned_step != plan.max_iter + 1 || planned_step <= 1 {
        return Ok(planned_step);
    }
    if !plan.final_domain_gridfile.exists() {
        let previous_gridfile =
            mkgrd_gridfile_path(&plan.file_dir, plan.nxp, planned_step - 1, &plan.mode_grid);
        if !previous_gridfile.exists() {
            return Ok(planned_step);
        }
        return Ok(planned_step - 1);
    }
    Ok(planned_step)
}

fn effective_mkgrd_refine_loop_io_plan(
    plan: &MkgrdRefineLoopIoPlan,
) -> io::Result<MkgrdRefineLoopIoPlan> {
    let effective_step = infer_mkgrd_effective_final_step_from_gridfiles(plan)?;
    if effective_step == plan.final_mask_postproc_step {
        return Ok(plan.clone());
    }
    let mut effective = plan.clone();
    effective.final_mask_postproc_step = effective_step;
    effective.final_domain_gridfile = mkgrd_gridfile_path(
        &effective.file_dir,
        effective.nxp,
        effective_step,
        &effective.mode_grid,
    );
    effective.final_quality_check = retarget_final_quality_check_step(
        &effective.final_quality_check,
        &effective.file_dir,
        effective.nxp,
        &effective.mode_grid,
        effective_step,
    );
    Ok(effective)
}

fn retarget_final_quality_check_step(
    plan: &MkgrdFinalQualityCheckIoPlan,
    file_dir: &Path,
    nxp: usize,
    mode_grid: &str,
    step: usize,
) -> MkgrdFinalQualityCheckIoPlan {
    let mut retargeted = plan.clone();
    retargeted.step = step;
    if retargeted.run_quality_check {
        let input_gridfile = mkgrd_gridfile_path(file_dir, nxp, step, mode_grid);
        retargeted.input_gridfile = input_gridfile.clone();
        retargeted.original_gridfile = Some(file_dir.join("gridfile").join(format!(
            "gridfile_NXP{nxp:04}_{step:02}_{mode_grid}_orial.nc4"
        )));
        retargeted.quality_before_spring = Some(file_dir.join("result").join(format!(
            "quality_NXP{nxp:04}_{step:02}_global_beforeSpring.nc4"
        )));
        retargeted.quality_after_spring = Some(
            file_dir
                .join("result")
                .join(format!("quality_NXP{nxp:04}_{step:02}_global.nc4")),
        );
        retargeted.output_gridfile = Some(input_gridfile);
    }
    retargeted
}

fn plan_mkgrd_refine_source_io(
    file_dir: &Path,
    nxp: usize,
    mesh_type: &str,
    step: usize,
    source: MkgrdRefineSource,
) -> io::Result<MkgrdRefineSourceIoPlan> {
    let stepc = format!("{step:02}");
    match source {
        MkgrdRefineSource::CalculatedIterZero => Ok(MkgrdRefineSourceIoPlan {
            source,
            area_judge_iter: 0,
            get_contain_iter: 0,
            getref_iter: 0,
            area_judge_output: file_dir
                .join("result")
                .join(format!("IsInRfArea_grid_cal_NXP{nxp:04}_{stepc}.nc4")),
            contain_output: file_dir.join("contain").join(format!(
                "contain_{mesh_type}_refine_cal_NXP{nxp:04}_{stepc}_tri.nc4"
            )),
            threshold_outputs: mkgrd_calculated_threshold_outputs(file_dir, nxp, step, mesh_type)?,
            specified_threshold_output: None,
        }),
        MkgrdRefineSource::SpecifiedStep => Ok(MkgrdRefineSourceIoPlan {
            source,
            area_judge_iter: step,
            get_contain_iter: step,
            getref_iter: step,
            area_judge_output: file_dir
                .join("result")
                .join(format!("IsInRfArea_grid_spc_NXP{nxp:04}_{stepc}.nc4")),
            contain_output: file_dir.join("contain").join(format!(
                "contain_{mesh_type}_refine_spc_NXP{nxp:04}_{stepc}_tri.nc4"
            )),
            threshold_outputs: Vec::new(),
            specified_threshold_output: Some(
                file_dir
                    .join("threshold")
                    .join(format!("threshold_specified_NXP{nxp:04}_{stepc}.nc4")),
            ),
        }),
    }
}

fn mkgrd_calculated_threshold_outputs(
    file_dir: &Path,
    nxp: usize,
    step: usize,
    mesh_type: &str,
) -> io::Result<Vec<PathBuf>> {
    let stepc = format!("{step:02}");
    let threshold_dir = file_dir.join("threshold");
    let mut outputs = Vec::new();
    match mesh_type {
        "landmesh" => outputs
            .push(threshold_dir.join(format!("threshold_calculate_land_NXP{nxp:04}_{stepc}.nc4"))),
        "oceanmesh" => outputs
            .push(threshold_dir.join(format!("threshold_calculate_ocean_NXP{nxp:04}_{stepc}.nc4"))),
        "atmos" | "atmosmesh" => outputs
            .push(threshold_dir.join(format!("threshold_calculate_atmos_NXP{nxp:04}_{stepc}.nc4"))),
        "LOCmesh" | "earthmesh" => {
            outputs.push(
                threshold_dir.join(format!("threshold_calculate_land_NXP{nxp:04}_{stepc}.nc4")),
            );
            outputs.push(
                threshold_dir.join(format!("threshold_calculate_ocean_NXP{nxp:04}_{stepc}.nc4")),
            );
            outputs.push(
                threshold_dir.join(format!("threshold_calculate_atmos_NXP{nxp:04}_{stepc}.nc4")),
            );
        }
        other => {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("unsupported mesh_type {other} for calculated GetRef outputs"),
            ));
        }
    }
    Ok(outputs)
}

/// Build the non-destructive I/O plan for `mkgrd.F90:Final_Grid_Quality_Check`.
pub fn plan_mkgrd_final_quality_check_io(
    config: &EarthmeshConfig,
    refine: &RefineConfig,
    step: usize,
) -> io::Result<MkgrdFinalQualityCheckIoPlan> {
    if config.nxp <= 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "NXP must be positive for final quality check",
        ));
    }
    if step == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "Final_Grid_Quality_Check step must be one-based",
        ));
    }
    let nxp = usize::try_from(config.nxp)
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "NXP must fit usize"))?;
    let file_dir = PathBuf::from(config.file_dir());
    let mode_grid = config.mode_grid.trim();
    let input_gridfile = mkgrd_gridfile_path(&file_dir, nxp, step, mode_grid);

    if refine.spring_global_type == 0 && refine.spring_regional_type == 0 {
        return Ok(MkgrdFinalQualityCheckIoPlan {
            step,
            run_quality_check: false,
            spring_mode: MkgrdFinalQualitySpringMode::SkippedBothDisabled,
            input_gridfile,
            original_gridfile: None,
            quality_before_spring: None,
            quality_after_spring: None,
            output_gridfile: None,
            regional_set_dis: None,
            global_spring: None,
            regional_spring: None,
            regional_source_mask: None,
        });
    }

    if refine.spring_regional_type == 1 {
        return Ok(MkgrdFinalQualityCheckIoPlan {
            step,
            run_quality_check: false,
            spring_mode: MkgrdFinalQualitySpringMode::SkippedRegionalEachStep,
            input_gridfile,
            original_gridfile: None,
            quality_before_spring: None,
            quality_after_spring: None,
            output_gridfile: None,
            regional_set_dis: None,
            global_spring: None,
            regional_spring: None,
            regional_source_mask: None,
        });
    }

    let spring_mode = if refine.spring_global_type == 1 {
        MkgrdFinalQualitySpringMode::Global
    } else {
        let set_dis = *refine.halo.get(1).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                "Final_Grid_Quality_Check requires halo(1) for regional final spring",
            )
        })?;
        if set_dis <= 0 {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                "Final_Grid_Quality_Check regional set_dis halo(1) must be positive",
            ));
        }
        MkgrdFinalQualitySpringMode::RegionalFinal
    };
    let regional_set_dis =
        (spring_mode == MkgrdFinalQualitySpringMode::RegionalFinal).then_some(refine.halo[1]);
    let global_spring = (spring_mode == MkgrdFinalQualitySpringMode::Global)
        .then(|| plan_mkgrd_final_quality_global_spring(config, refine, nxp))
        .transpose()?;
    let regional_spring = (spring_mode == MkgrdFinalQualitySpringMode::RegionalFinal)
        .then(|| plan_mkgrd_final_quality_regional_spring(refine))
        .transpose()?;

    Ok(MkgrdFinalQualityCheckIoPlan {
        step,
        run_quality_check: true,
        spring_mode,
        input_gridfile: input_gridfile.clone(),
        original_gridfile: Some(file_dir.join("gridfile").join(format!(
            "gridfile_NXP{nxp:04}_{step:02}_{mode_grid}_orial.nc4"
        ))),
        quality_before_spring: Some(file_dir.join("result").join(format!(
            "quality_NXP{nxp:04}_{step:02}_global_beforeSpring.nc4"
        ))),
        quality_after_spring: Some(
            file_dir
                .join("result")
                .join(format!("quality_NXP{nxp:04}_{step:02}_global.nc4")),
        ),
        output_gridfile: Some(input_gridfile),
        regional_set_dis,
        global_spring,
        regional_spring,
        regional_source_mask: None,
    })
}

fn plan_mkgrd_final_quality_regional_spring(
    refine: &RefineConfig,
) -> io::Result<MkgrdFinalQualityRegionalSpringIoPlan> {
    let niter_refine = final_quality_non_negative_usize(
        refine.niter_refine,
        "Final_Grid_Quality_Check niter_refine must be non-negative",
    )?;
    Ok(MkgrdFinalQualityRegionalSpringIoPlan {
        niter_refine,
        radius: earthmesh_core::EARTH_RADIUS_METERS,
    })
}

fn plan_mkgrd_final_quality_global_spring(
    config: &EarthmeshConfig,
    refine: &RefineConfig,
    nxp: usize,
) -> io::Result<MkgrdFinalQualityGlobalSpringIoPlan> {
    let distance_num_rc = final_quality_non_negative_usize(
        refine.num_rc,
        "Final_Grid_Quality_Check num_rc must be non-negative",
    )?;
    let niter_refine = final_quality_non_negative_usize(
        refine.niter_refine,
        "Final_Grid_Quality_Check niter_refine must be non-negative",
    )?;
    let distance_spacing = if distance_num_rc == 0 {
        DistanceLayerSpacing::Linear
    } else {
        final_quality_distance_spacing(&refine.set_dis_type)?
    };
    let base_dists_on_edge =
        f64::from(config.beta) * std::f64::consts::PI * 2.0 * earthmesh_core::EARTH_RADIUS_METERS
            / (5.0 * nxp as f64);
    let base_cellwidth = match config.output_format.trim() {
        "MPAS" | "MPAS-Simple" => Some((7680 / nxp) as f64),
        _ => None,
    };

    Ok(MkgrdFinalQualityGlobalSpringIoPlan {
        base_dists_on_edge,
        base_cellwidth,
        distance_num_rc,
        distance_spacing,
        distance_steps: Vec::new(),
        niter_refine,
        relax: f64::from(config.relax),
        radius: earthmesh_core::EARTH_RADIUS_METERS,
    })
}

fn final_quality_non_negative_usize(value: i32, message: &str) -> io::Result<usize> {
    usize::try_from(value).map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, message))
}

fn final_quality_distance_spacing(set_dis_type: &str) -> io::Result<DistanceLayerSpacing> {
    match set_dis_type.trim() {
        "linear" => Ok(DistanceLayerSpacing::Linear),
        "nonlinear1" => Ok(DistanceLayerSpacing::Power),
        "nonlinear2" => Ok(DistanceLayerSpacing::Exponential),
        "nonlinear3" => Ok(DistanceLayerSpacing::Logarithmic),
        other => Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("Final_Grid_Quality_Check set_dis_type must be linear, nonlinear1, nonlinear2, or nonlinear3; got {other}"),
        )),
    }
}

/// Execute `mkgrd.F90:Inital_Grid_Quality_Check` for an existing gridfile.
///
/// The Fortran entry reads the current unstructured grid and writes
/// `quality_NXP####_##_global_orial.nc4`; this Rust wrapper keeps that side
/// effect explicit without touching spring-adjustment state.
pub fn run_mkgrd_initial_grid_quality_check(
    input_gridfile: impl AsRef<Path>,
    quality_output: impl AsRef<Path>,
) -> io::Result<()> {
    let mesh = normalize_unstructured_mesh_legacy_placeholders(&read_unstructured_mesh_netcdf(
        input_gridfile.as_ref(),
    )?)?;
    let quality = grid_quality_global_from_unstructured_mesh(&mesh)?;
    write_grid_quality_global_netcdf(quality_output, &quality).map(|_| ())
}

/// Execute the migrated file-backed subset of `mkgrd.F90:Final_Grid_Quality_Check`.
///
/// This preserves the legacy side-effect order: copy the pre-spring gridfile,
/// write quality diagnostics before spring adjustment, run the selected
/// global/final-regional spring path, write quality diagnostics after spring,
/// then persist the adjusted mesh back to the planned output gridfile.
pub fn run_mkgrd_final_quality_check(plan: &MkgrdFinalQualityCheckIoPlan) -> io::Result<()> {
    if !plan.run_quality_check {
        return Ok(());
    }

    let original_gridfile =
        required_final_quality_path(plan.original_gridfile.as_deref(), "original gridfile")?;
    let quality_before_spring = required_final_quality_path(
        plan.quality_before_spring.as_deref(),
        "quality before spring",
    )?;
    let quality_after_spring =
        required_final_quality_path(plan.quality_after_spring.as_deref(), "quality after spring")?;
    let output_gridfile =
        required_final_quality_path(plan.output_gridfile.as_deref(), "output gridfile")?;

    if let Some(parent) = original_gridfile.parent() {
        fs::create_dir_all(parent)?;
    }
    fs::copy(&plan.input_gridfile, original_gridfile)?;

    let raw_mesh = read_unstructured_mesh_netcdf(&plan.input_gridfile)?;
    let mesh = normalize_unstructured_mesh_legacy_placeholders(&raw_mesh)?;
    let before_quality = grid_quality_global_from_unstructured_mesh(&mesh)?;
    write_grid_quality_global_netcdf(quality_before_spring, &before_quality)?;

    let mut restored_global_cellwidth: Option<(PathBuf, Vec<f64>)> = None;
    let adjusted_mesh = match plan.spring_mode {
        MkgrdFinalQualitySpringMode::Global => {
            let (file_dir, nxp) = final_quality_file_dir_and_nxp(plan)?;
            let global_spring = plan.global_spring.as_ref().ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidInput,
                    "Final_Grid_Quality_Check global spring requires global_spring controls",
                )
            })?;
            let distance_steps = final_quality_global_distance_steps(global_spring);
            let report = run_springjustment_global_from_unstructured_mesh(
                &mesh,
                &file_dir,
                nxp,
                plan.step,
                final_quality_global_spring_options(global_spring, &distance_steps),
            )?;
            if let Some(cellwidth) = report.core.cellwidth.as_ref() {
                restored_global_cellwidth = Some((
                    file_dir
                        .join("result")
                        .join(format!("cellwidth_NXP{nxp:04}_global.nc4")),
                    restore_cellwidth_shape(&raw_mesh, cellwidth)?,
                ));
            }
            report.mesh
        }
        MkgrdFinalQualitySpringMode::RegionalFinal => {
            run_final_regional_spring_from_unstructured_mesh(plan, &mesh)?
        }
        MkgrdFinalQualitySpringMode::SkippedBothDisabled
        | MkgrdFinalQualitySpringMode::SkippedRegionalEachStep => mesh.clone(),
    };

    let after_quality = grid_quality_global_from_unstructured_mesh(&adjusted_mesh)?;
    write_grid_quality_global_netcdf(quality_after_spring, &after_quality)?;
    let output_mesh = restore_unstructured_mesh_shape(&raw_mesh, &adjusted_mesh)?;
    write_unstructured_mesh_netcdf(output_gridfile, &output_mesh)?;
    if let Some((cellwidth_path, cellwidth)) = restored_global_cellwidth {
        write_cellwidth_netcdf(
            cellwidth_path,
            &CellwidthMesh {
                cell_points: raw_mesh.w_points.clone(),
                cellwidth,
            },
        )?;
    }
    Ok(())
}

fn restore_cellwidth_shape(original: &UnstructuredMesh, cellwidth: &[f64]) -> io::Result<Vec<f64>> {
    if cellwidth.len() < original.w_points.len() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "cellwidth is smaller than original mesh cell shape",
        ));
    }
    let cell_offset = cellwidth.len() - original.w_points.len();
    Ok(cellwidth[cell_offset..].to_vec())
}

/// Reproduce the post-`NGR_RENEW` counters that Fortran stores in
/// `num_mp_step(step)` and `num_wp_step(step)` for later global distance layers.
pub fn refine_loop_post_counts_fortran_indexed(
    old_triangle_count: usize,
    old_cell_count: usize,
    expanded_triangle_count: usize,
    compact_mesh: &UnstructuredMesh,
    lop_triangle_count: usize,
) -> io::Result<(usize, usize)> {
    let compact_triangle_count = compact_mesh.m_points.len();
    let removed_triangle_count = expanded_triangle_count
        .checked_sub(compact_triangle_count)
        .ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                "expanded triangle count must be >= compact triangle count",
            )
        })?;
    let num_vertex = old_triangle_count
        .saturating_sub(removed_triangle_count)
        .checked_add(lop_triangle_count)
        .ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                "post-refine num_vertex calculation overflowed",
            )
        })?;
    let mut num_center = old_cell_count;
    for triangle_id in (num_vertex + 1)..=compact_triangle_count {
        let row = compact_mesh.m_to_w.get(triangle_id - 1).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("compact mesh is missing triangle row {triangle_id}"),
            )
        })?;
        for &cell_id in row {
            if cell_id > 0 && (cell_id as usize) < num_center {
                num_center = cell_id as usize;
            }
        }
    }
    Ok((num_vertex, num_center))
}

fn required_final_quality_path<'a>(path: Option<&'a Path>, label: &str) -> io::Result<&'a Path> {
    path.ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("Final_Grid_Quality_Check requires {label} path"),
        )
    })
}

fn grid_quality_global_from_unstructured_mesh(
    mesh: &UnstructuredMesh,
) -> io::Result<earthmesh_mesh::GridQualityGlobalOutput> {
    let cells_on_triangle = cells_on_triangle_fortran_indexed_from_mesh(mesh)?;
    let triangles_on_cell = triangles_on_cell_fortran_indexed_from_mesh(mesh)?;
    let n_edges_on_cell = n_edges_on_cell_usize_from_mesh(mesh)?;
    let triangle_lonlat = lonlat_degrees_from_points(&mesh.m_points);
    let cell_lonlat = lonlat_degrees_from_points(&mesh.w_points);

    earthmesh_mesh::grid_quality_check_global_fortran_indexed(
        &cell_lonlat,
        &cells_on_triangle,
        &triangle_lonlat,
        &triangles_on_cell,
        &n_edges_on_cell,
    )
    .ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            "failed to run Grid_Quality_Check_Global from unstructured mesh",
        )
    })
}

fn run_final_regional_spring_from_unstructured_mesh(
    plan: &MkgrdFinalQualityCheckIoPlan,
    mesh: &UnstructuredMesh,
) -> io::Result<UnstructuredMesh> {
    let set_dis = plan.regional_set_dis.ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "Final_Grid_Quality_Check regional spring requires regional_set_dis",
        )
    })?;
    let regional_spring = plan.regional_spring.ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "Final_Grid_Quality_Check regional spring requires regional_spring controls",
        )
    })?;
    if set_dis < 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "Final_Grid_Quality_Check regional_set_dis must be non-negative",
        ));
    }

    let cells_on_triangle = cells_on_triangle_fortran_indexed_from_mesh(mesh)?;
    let source_mask = plan.regional_source_mask.as_ref().ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "Final_Grid_Quality_Check regional spring requires source mask classification inputs",
        )
    })?;
    let refined_triangles = final_regional_refined_triangles_from_source_mask(mesh, source_mask)?;
    let move_mask = final_regional_move_mask_from_refined_triangles(
        mesh,
        &cells_on_triangle,
        &refined_triangles,
        set_dis as usize,
    )?;
    let report = run_springjustment_regional_from_unstructured_mesh(
        mesh,
        SpringjustmentRegionalRunOptions {
            move_mask: &move_mask,
            niter_refine: regional_spring.niter_refine,
            radius: regional_spring.radius,
            diagnostic_every: 100,
        },
    )?;
    Ok(report.mesh)
}

fn final_regional_refined_triangles_from_source_mask(
    mesh: &UnstructuredMesh,
    source_mask: &MkgrdFinalQualityRegionalSourceMaskIoPlan,
) -> io::Result<Vec<bool>> {
    let triangle_lonlat = lonlat_degrees_from_points(&mesh.m_points);
    earthmesh_mesh::refine_sjx_regional_make_fortran_indexed(
        earthmesh_mesh::RefineRegionalMaskInput {
            triangle_lonlat: &triangle_lonlat,
            source_lon_vertices: &source_mask.source_lon_vertices,
            source_lat_vertices: &source_mask.source_lat_vertices,
            mask_patch: &source_mask.mask_patch,
            first_triangle_id: source_mask.first_triangle_id,
        },
    )
    .ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            "failed to classify final regional refined triangles from source mask",
        )
    })
}

fn final_regional_move_mask_from_refined_triangles(
    mesh: &UnstructuredMesh,
    cells_on_triangle: &[[usize; 3]],
    refined_triangles: &[bool],
    set_dis: usize,
) -> io::Result<Vec<bool>> {
    let triangles_on_cell = triangles_on_cell_fortran_indexed_from_mesh(mesh)?;
    let n_edges_on_cell = n_edges_on_cell_usize_from_mesh(mesh)?;
    let mask = earthmesh_mesh::set_dbx_move_regional_step_fortran_indexed(
        earthmesh_mesh::RegionalMoveMaskInput {
            set_dis,
            refined_triangles,
            cells_on_triangle,
            triangles_on_cell: &triangles_on_cell,
            n_edges_on_cell: &n_edges_on_cell,
            protected_seed_cells: &[],
            vertex_protect_layers: 0,
        },
    )
    .ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            "failed to derive final regional Springjustment move mask",
        )
    })?;
    Ok(mask.move_mask)
}

fn final_quality_global_distance_steps(
    plan: &MkgrdFinalQualityGlobalSpringIoPlan,
) -> Vec<GlobalDistanceStep<'_>> {
    plan.distance_steps
        .iter()
        .map(|step| GlobalDistanceStep {
            active: step.active,
            halo: step.halo,
            refinement_flags: &step.refinement_flags,
            num_vertex_in: step.num_vertex_in,
            num_center_in: step.num_center_in,
        })
        .collect()
}

fn final_quality_global_spring_options<'a>(
    plan: &'a MkgrdFinalQualityGlobalSpringIoPlan,
    distance_steps: &'a [GlobalDistanceStep<'a>],
) -> SpringjustmentGlobalRunOptions<'a> {
    SpringjustmentGlobalRunOptions {
        base_dists_on_edge: plan.base_dists_on_edge,
        base_cellwidth: plan.base_cellwidth,
        distance_num_rc: plan.distance_num_rc,
        distance_spacing: plan.distance_spacing,
        distance_steps,
        niter_refine: plan.niter_refine,
        relax: plan.relax,
        radius: plan.radius,
        diagnostic_every: 100,
    }
}

fn final_quality_file_dir_and_nxp(
    plan: &MkgrdFinalQualityCheckIoPlan,
) -> io::Result<(PathBuf, usize)> {
    let gridfile_dir = plan.input_gridfile.parent().ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "Final_Grid_Quality_Check input_gridfile must have a parent directory",
        )
    })?;
    let file_dir = gridfile_dir.parent().ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "Final_Grid_Quality_Check input_gridfile must live under <file_dir>/gridfile",
        )
    })?;
    let filename = plan
        .input_gridfile
        .file_name()
        .and_then(|name| name.to_str())
        .ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                "Final_Grid_Quality_Check input_gridfile must have a UTF-8 file name",
            )
        })?;
    Ok((
        file_dir.to_path_buf(),
        parse_nxp_from_gridfile_name(filename)?,
    ))
}

fn parse_nxp_from_gridfile_name(filename: &str) -> io::Result<usize> {
    let start = filename.find("NXP").ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("gridfile name {filename} does not contain NXP"),
        )
    })? + 3;
    let digits = filename[start..]
        .chars()
        .take_while(|ch| ch.is_ascii_digit())
        .collect::<String>();
    if digits.is_empty() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("gridfile name {filename} does not contain NXP digits"),
        ));
    }
    digits.parse::<usize>().map_err(|err| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("failed to parse NXP from gridfile name {filename}: {err}"),
        )
    })
}

fn mkgrd_gridfile_path(file_dir: &Path, nxp: usize, step: usize, mode_grid: &str) -> PathBuf {
    file_dir
        .join("gridfile")
        .join(format!("gridfile_NXP{nxp:04}_{step:02}_{mode_grid}.nc4"))
}

fn mkgrd_tmpfile_path(file_dir: &Path, nxp: usize, step: usize, suffix: &str) -> PathBuf {
    file_dir
        .join("tmpfile")
        .join(format!("gridfile_NXP{nxp:04}_{step:02}_{suffix}.nc4"))
}

/// Run the migrated top-level `mkgrd.x` namelist dispatcher for option-free branches.
///
/// This is the Rust replacement for the first branch decision in `mkgrd.F90`:
/// mask-restart namelists must not fall through to the normal gridinit path.
/// Restart variants that require extra source-grid/postprocess options return a typed plan;
/// the patch-preprocess branch is fully executable because it only depends on the namelist.
pub fn run_mkgrd_top_level_namelist(
    namelist_source: impl AsRef<Path>,
    workdir: impl AsRef<Path>,
    max_tris: usize,
    mask_restart_max_iter: i32,
) -> io::Result<MkgrdTopLevelDispatchRunReport> {
    let namelist_source = namelist_source.as_ref();
    let workdir = workdir.as_ref();
    let contents = fs::read_to_string(namelist_source)?;
    let config = EarthmeshConfig::from_mkgrd_namelist(&contents)
        .map_err(|err| io::Error::new(io::ErrorKind::InvalidInput, err))?;

    if config.mask_restart {
        if config.mask_patch_on {
            let restart_area_grid =
                PathBuf::from(config.file_dir()).join("result/IsInDmArea_grid.nc4");
            if restart_area_grid.exists() {
                return run_mkgrd_mask_restart_area_judge_configured_global_source_namelist(
                    namelist_source,
                    workdir,
                    mask_restart_max_iter,
                    None,
                )
                .map(MkgrdTopLevelDispatchRunReport::MaskRestartAreaJudge);
            }
            return run_mkgrd_mask_restart_patch_namelist(
                namelist_source,
                workdir,
                mask_restart_max_iter,
            )
            .map(MkgrdTopLevelDispatchRunReport::MaskRestartPatch);
        }
        let plan =
            plan_mkgrd_mask_restart_namelist(namelist_source, workdir, mask_restart_max_iter)?;
        if plan.remask.action == MaskRestartAction::RunMaskPostproc
            && plan.config.mesh_type.trim() == "oceanmesh"
        {
            let num_vertex = infer_mask_restart_ocean_num_vertex_from_config(&plan.config)?;
            return run_mkgrd_mask_restart_ocean_namelist(
                namelist_source,
                workdir,
                mask_restart_max_iter,
                MaskPostprocOceanRunOptions {
                    mask_sea_ratio: plan.config.mask_sea_ratio,
                    num_vertex,
                },
            )
            .map(MkgrdTopLevelDispatchRunReport::MaskRestartOcean);
        }
        if plan.remask.action == MaskRestartAction::ContinueMkgrd
            && !plan.config.mask_patch_on
            && plan.config.mesh_type.trim() != "oceanmesh"
        {
            let postproc_num_vertex =
                maybe_infer_mask_restart_non_ocean_num_vertex_from_config(&plan.config)?;
            return run_mkgrd_mask_restart_area_judge_configured_global_source_namelist(
                namelist_source,
                workdir,
                mask_restart_max_iter,
                postproc_num_vertex,
            )
            .map(MkgrdTopLevelDispatchRunReport::MaskRestartAreaJudge);
        }
        return Ok(MkgrdTopLevelDispatchRunReport::MaskRestartPlan(plan));
    }

    if olam_direct_refine_dispatch_requested(&contents, &config)? {
        return run_mkgrd_olam_specified_refine_global_source_namelist(
            namelist_source,
            workdir,
            max_tris,
            None,
        )
        .map(MkgrdTopLevelDispatchRunReport::OlamRefineGlobalSource);
    }

    run_mkgrd_gridinit_global_namelist(namelist_source, workdir, max_tris)
        .map(MkgrdTopLevelDispatchRunReport::Gridinit)
}

/// Infer the legacy `num_vertex` boundary for mask-restart ocean postprocess
/// from the restart contain file written by the previous `Get_Contain(0)`
/// handoff.
///
/// The Fortran `mkgrd` restart path already has this boundary in module state.
/// Rust callers reconstruct it from the persisted `ustr_ii` table so top-level
/// restart execution does not require a debug-only manual argument.
pub fn infer_mask_restart_ocean_num_vertex_from_config(
    config: &EarthmeshConfig,
) -> io::Result<usize> {
    if config.nxp <= 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "mask_restart ocean postproc requires positive NL%NXP to infer num_vertex, got {}",
                config.nxp
            ),
        ));
    }
    let nxp = usize::try_from(config.nxp)
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "NXP must fit usize"))?;
    let postproc_plan = plan_mask_postproc_domain_io(
        PathBuf::from(config.file_dir()),
        nxp,
        config.mode_grid.trim(),
        config.mesh_type.trim(),
        config.mask_patch_on,
    )?;
    let contain = read_contain_netcdf(&postproc_plan.contain_domain)?;
    if contain.ustr_ii.is_empty() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "mask_restart ocean postproc cannot infer num_vertex from empty ustr_ii in {}",
                postproc_plan.contain_domain.display()
            ),
        ));
    }
    Ok(contain.ustr_ii.len())
}

/// Try to recover the legacy `num_vertex` boundary for ocean mask-restart
/// `Area_judge` final postprocess from the persisted final contain file.
///
/// Missing contain files mean the continuation has not reached a final
/// postprocess handoff yet, so callers that can still run Area_judge-only should
/// treat the boundary as absent.  Existing but empty contain files are invalid
/// because they cannot prove a safe persisted boundary.
pub fn maybe_infer_mask_restart_ocean_num_vertex_from_config(
    config: &EarthmeshConfig,
) -> io::Result<Option<usize>> {
    if config.nxp <= 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "mask_restart ocean postproc requires positive NL%NXP to infer num_vertex, got {}",
                config.nxp
            ),
        ));
    }
    let nxp = usize::try_from(config.nxp)
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "NXP must fit usize"))?;
    let postproc_plan = plan_mask_postproc_domain_io(
        PathBuf::from(config.file_dir()),
        nxp,
        config.mode_grid.trim(),
        config.mesh_type.trim(),
        config.mask_patch_on,
    )?;
    if !postproc_plan.contain_domain.exists() {
        return Ok(None);
    }
    let contain = read_contain_netcdf(&postproc_plan.contain_domain)?;
    if contain.ustr_ii.is_empty() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "mask_restart ocean postproc cannot infer num_vertex from empty ustr_ii in {}",
                postproc_plan.contain_domain.display()
            ),
        ));
    }
    Ok(Some(contain.ustr_ii.len()))
}

/// Try to recover the legacy `num_vertex` boundary for non-ocean
/// mask-restart `ContinueMkgrd` final postprocess from the persisted final
/// contain file written by the previous handoff.
///
/// Missing contain files are treated as "not recoverable yet" so restart
/// callers can still run the Area_judge-only continuation.  Existing but empty
/// contain files are invalid because they cannot prove a safe boundary.
pub fn maybe_infer_mask_restart_non_ocean_num_vertex_from_config(
    config: &EarthmeshConfig,
) -> io::Result<Option<usize>> {
    if config.nxp <= 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "mask_restart non-ocean postproc requires positive NL%NXP to infer num_vertex, got {}",
                config.nxp
            ),
        ));
    }
    let nxp = usize::try_from(config.nxp)
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "NXP must fit usize"))?;
    let postproc_plan = plan_mask_postproc_domain_io(
        PathBuf::from(config.file_dir()),
        nxp,
        config.mode_grid.trim(),
        config.mesh_type.trim(),
        config.mask_patch_on,
    )?;
    if !postproc_plan.contain_domain.exists() {
        return Ok(None);
    }
    let contain = read_contain_netcdf(&postproc_plan.contain_domain)?;
    if contain.ustr_ii.is_empty() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "mask_restart non-ocean postproc cannot infer num_vertex from empty ustr_ii in {}",
                postproc_plan.contain_domain.display()
            ),
        ));
    }
    Ok(Some(contain.ustr_ii.len()))
}

fn default_mask_restart_area_judge_postproc_num_vertex(
    config: &EarthmeshConfig,
    explicit_num_vertex: Option<usize>,
) -> io::Result<Option<usize>> {
    if explicit_num_vertex.is_some() {
        return Ok(explicit_num_vertex);
    }
    let mode_num_vertex = mkgrd_mode_grid_num_vertex(config.mode_grid.trim())?;
    if config.mesh_type.trim() == "oceanmesh" {
        return Ok(
            maybe_infer_mask_restart_ocean_num_vertex_from_config(config)?
                .or(Some(mode_num_vertex)),
        );
    }
    let default_num_vertex = if config.mesh_type.trim() == "landmesh" {
        1
    } else {
        mode_num_vertex
    };
    Ok(
        maybe_infer_mask_restart_non_ocean_num_vertex_from_config(config)?
            .or(Some(default_num_vertex)),
    )
}

/// Build the standard case-local restart-refine initial gridfile path used by
/// the migrated top-level `mkgrd` restart handoff.
pub fn restart_refine_initial_gridfile_path_from_config(
    config: &EarthmeshConfig,
) -> io::Result<PathBuf> {
    if config.nxp <= 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "restart-refine handoff requires positive NL%NXP to infer initial gridfile, got {}",
                config.nxp
            ),
        ));
    }
    let nxp = usize::try_from(config.nxp)
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "NXP must fit usize"))?;
    Ok(PathBuf::from(config.file_dir())
        .join("gridfile")
        .join(format!(
            "gridfile_NXP{nxp:04}_01_{}.nc4",
            config.mode_grid.trim()
        )))
}

/// Strictly infer the standard restart-refine initial gridfile, requiring it to
/// already exist on disk.
pub fn infer_restart_refine_initial_gridfile_from_config(
    config: &EarthmeshConfig,
) -> io::Result<PathBuf> {
    let path = restart_refine_initial_gridfile_path_from_config(config)?;
    if path.exists() {
        Ok(path)
    } else {
        Err(io::Error::new(
            io::ErrorKind::NotFound,
            format!(
                "restart-refine handoff requires --restart-refine-initial-gridfile or existing initial gridfile {}",
                path.display()
            ),
        ))
    }
}

/// Optionally infer the standard restart-refine initial gridfile, returning
/// `None` when the standard path has not yet been prepared.
pub fn maybe_infer_restart_refine_initial_gridfile_from_config(
    config: &EarthmeshConfig,
) -> io::Result<Option<PathBuf>> {
    let path = restart_refine_initial_gridfile_path_from_config(config)?;
    Ok(path.exists().then_some(path))
}

/// Source branch selected by the default top-level `mkgrd.x` restart-refine
/// handoff classifier.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MkgrdDefaultRestartRefineSource {
    SourceState,
    LandtypeFile,
}

/// Reusable result for the default top-level restart-refine handoff.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MkgrdDefaultRestartRefineHandoff {
    pub source: MkgrdDefaultRestartRefineSource,
    pub initial_gridfile: PathBuf,
}

/// Return true when the raw namelist explicitly sets `NL%landtype_file` outside
/// comments.  The parsed config alone cannot distinguish an omitted key from an
/// empty default, and the legacy restart branch only enters the landtype-source
/// path when the namelist provided the field.
pub fn namelist_sets_landtype_file(contents: &str) -> bool {
    contents
        .lines()
        .map(|line| line.split('!').next().unwrap_or(""))
        .any(|line| line.to_ascii_lowercase().contains("landtype_file"))
}

/// Whether `landtype_file` names a real data file rather than the conventional
/// "unset" sentinel. EarthMesh namelists use `'none'` (and the GUI an empty
/// string) to mean "no land-type input"; the refine dispatch must not try to
/// open such a path. Mirrors how `mode_file='none'` is treated elsewhere.
pub fn landtype_file_is_real(landtype_file: &str) -> bool {
    let trimmed = landtype_file.trim();
    !trimmed.is_empty() && !trimmed.eq_ignore_ascii_case("none")
}

/// Classify the no-explicit-mode restart-refine handoff that the top-level
/// `mkgrd.x` front-end should run, including standard initial-gridfile
/// inference.  This keeps restart/refine branching reusable by callers other
/// than the CLI binary.
pub fn infer_default_restart_refine_handoff_from_config(
    config: &EarthmeshConfig,
    namelist_contents: &str,
    has_restart_refine_source_state: bool,
    restart_refine_initial_gridfile: Option<&Path>,
) -> io::Result<Option<MkgrdDefaultRestartRefineHandoff>> {
    if restart_refine_initial_gridfile.is_some() || has_restart_refine_source_state {
        let initial_gridfile = match restart_refine_initial_gridfile {
            Some(path) => path.to_path_buf(),
            None => infer_restart_refine_initial_gridfile_from_config(config)?,
        };
        let source = if has_restart_refine_source_state {
            MkgrdDefaultRestartRefineSource::SourceState
        } else if namelist_sets_landtype_file(namelist_contents)
            && landtype_file_is_real(&config.landtype_file)
        {
            MkgrdDefaultRestartRefineSource::LandtypeFile
        } else {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                "default restart-refine handoff requires --restart-refine-source-state or NL%landtype_file",
            ));
        };
        return Ok(Some(MkgrdDefaultRestartRefineHandoff {
            source,
            initial_gridfile,
        }));
    }

    if config.mask_restart
        && config.refine
        && namelist_sets_landtype_file(namelist_contents)
        && landtype_file_is_real(&config.landtype_file)
    {
        if let Some(initial_gridfile) =
            maybe_infer_restart_refine_initial_gridfile_from_config(config)?
        {
            return Ok(Some(MkgrdDefaultRestartRefineHandoff {
                source: MkgrdDefaultRestartRefineSource::LandtypeFile,
                initial_gridfile,
            }));
        }
    }

    Ok(None)
}

/// Run the top-level dispatcher after applying the default restart-refine
/// handoff classification used when the binary receives no explicit execution
/// mode.  This keeps the restart/refine branch decision in the reusable Rust
/// library instead of the CLI argument front-end.
pub fn run_mkgrd_top_level_namelist_with_default_restart_refine_handoff(
    namelist_source: impl AsRef<Path>,
    workdir: impl AsRef<Path>,
    max_tris: usize,
    mask_restart_max_iter: i32,
    restart_refine_source_state: Option<&Path>,
    restart_refine_initial_gridfile: Option<&Path>,
    source_gridnum_perdegree: Option<usize>,
    source_first_triangle_id: usize,
    mask_postproc_num_vertex: Option<usize>,
) -> io::Result<MkgrdTopLevelDefaultRestartRefineRunReport> {
    let namelist_source = namelist_source.as_ref();
    let workdir = workdir.as_ref();
    let contents = fs::read_to_string(namelist_source)?;
    let config = EarthmeshConfig::from_mkgrd_namelist(&contents)
        .map_err(|err| io::Error::new(io::ErrorKind::InvalidInput, err))?;

    let Some(handoff) = infer_default_restart_refine_handoff_from_config(
        &config,
        &contents,
        restart_refine_source_state.is_some(),
        restart_refine_initial_gridfile,
    )?
    else {
        let restart_area_grid = PathBuf::from(config.file_dir()).join("result/IsInDmArea_grid.nc4");
        if config.mask_restart && config.mask_patch_on && restart_area_grid.exists() {
            let postproc_num_vertex = default_mask_restart_area_judge_postproc_num_vertex(
                &config,
                mask_postproc_num_vertex,
            )?;
            return run_mkgrd_mask_restart_area_judge_configured_global_source_namelist(
                namelist_source,
                workdir,
                mask_restart_max_iter,
                postproc_num_vertex,
            )
            .map(MkgrdTopLevelDispatchRunReport::MaskRestartAreaJudge)
            .map(MkgrdTopLevelDefaultRestartRefineRunReport::Dispatch);
        }
        if config.mask_restart && !config.mask_patch_on {
            let plan =
                plan_mkgrd_mask_restart_namelist(namelist_source, workdir, mask_restart_max_iter)?;
            if plan.remask.action == MaskRestartAction::ContinueMkgrd {
                let postproc_num_vertex = default_mask_restart_area_judge_postproc_num_vertex(
                    &config,
                    mask_postproc_num_vertex,
                )?;
                return run_mkgrd_mask_restart_area_judge_configured_global_source_namelist(
                    namelist_source,
                    workdir,
                    mask_restart_max_iter,
                    postproc_num_vertex,
                )
                .map(MkgrdTopLevelDispatchRunReport::MaskRestartAreaJudge)
                .map(MkgrdTopLevelDefaultRestartRefineRunReport::Dispatch);
            }
        }
        if !config.mask_restart && olam_direct_refine_dispatch_requested(&contents, &config)? {
            let _ = source_first_triangle_id;
            return run_mkgrd_olam_specified_refine_global_source_namelist(
                namelist_source,
                workdir,
                max_tris,
                source_gridnum_perdegree,
            )
            .map(MkgrdTopLevelDefaultRestartRefineRunReport::OlamRefineGlobalSource);
        }
        return run_mkgrd_top_level_namelist(
            namelist_source,
            workdir,
            max_tris,
            mask_restart_max_iter,
        )
        .map(MkgrdTopLevelDefaultRestartRefineRunReport::Dispatch);
    };

    match handoff.source {
        MkgrdDefaultRestartRefineSource::SourceState => {
            let source_state = restart_refine_source_state.ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidInput,
                    "default source-state restart-refine handoff requires a source-state path",
                )
            })?;
            fs::metadata(source_state)?;
            let _ = mask_postproc_num_vertex;
            let rewritten = rewrite_restart_refine_namelist_for_olam_direct(
                namelist_source,
                workdir,
                &handoff.initial_gridfile,
            )?;
            run_mkgrd_olam_specified_refine_global_source_namelist(
                &rewritten,
                workdir,
                max_tris,
                source_gridnum_perdegree,
            )
            .map(MkgrdTopLevelDefaultRestartRefineRunReport::OlamRefineGlobalSource)
        }
        MkgrdDefaultRestartRefineSource::LandtypeFile => {
            let _ = source_first_triangle_id;
            let _ = mask_postproc_num_vertex;
            let rewritten = rewrite_restart_refine_namelist_for_olam_direct(
                namelist_source,
                workdir,
                &handoff.initial_gridfile,
            )?;
            run_mkgrd_olam_specified_refine_global_source_namelist(
                &rewritten,
                workdir,
                max_tris,
                source_gridnum_perdegree,
            )
            .map(MkgrdTopLevelDefaultRestartRefineRunReport::OlamRefineGlobalSource)
        }
    }
}

fn rewrite_restart_refine_namelist_for_olam_direct(
    namelist_source: &Path,
    workdir: &Path,
    initial_gridfile: &Path,
) -> io::Result<PathBuf> {
    fs::metadata(initial_gridfile)?;
    let contents = fs::read_to_string(namelist_source)?;
    let mut saw_mode_file = false;
    let mut saw_mode_file_description = false;
    let mut in_mkgrd = false;
    let initial_gridfile = initial_gridfile.display().to_string();
    let mut rewritten = Vec::new();
    for line in contents.lines() {
        let trimmed_lower = line.trim_start().to_ascii_lowercase();
        if trimmed_lower.starts_with("&mkgrd") {
            in_mkgrd = true;
            rewritten.push(line.to_string());
            continue;
        }
        if in_mkgrd && line.trim() == "/" {
            if !saw_mode_file {
                rewritten.push(format!("  NL%mode_file='{initial_gridfile}'"));
            }
            if !saw_mode_file_description {
                rewritten.push("  NL%mode_file_description='EarthMesh'".to_string());
            }
            in_mkgrd = false;
            rewritten.push(line.to_string());
            continue;
        }
        rewritten.push(if trimmed_lower.starts_with("nl%mask_restart") {
            "  NL%mask_restart=.false.".to_string()
        } else if trimmed_lower.starts_with("nl%mode_file_description") {
            saw_mode_file_description = true;
            "  NL%mode_file_description='EarthMesh'".to_string()
        } else if trimmed_lower.starts_with("nl%mode_file") {
            saw_mode_file = true;
            format!("  NL%mode_file='{initial_gridfile}'")
        } else {
            line.to_string()
        });
    }
    let stamp = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map_err(io::Error::other)?
        .as_nanos();
    let path = workdir.join(format!(
        "earthmesh_olam_default_restart_refine_{}_{}.nml",
        std::process::id(),
        stamp
    ));
    fs::write(&path, format!("{}\n", rewritten.join("\n")))?;
    Ok(path)
}

/// Run the Rust replacement path for the initial global `mkgrd.x` gridinit branch.
///
/// This mirrors the branch where `mode_grid` is `hex`/`tri` and `mode_file` does
/// not exist: parse the mkgrd namelist, apply the read_nl workspace/mask plan,
/// generate the in-memory global grid, and write
/// `gridfile/gridfile_NXP####_01_<mode_grid>.nc4`.  Restart mode and reading an
/// existing `mode_file` remain explicit `InvalidInput` errors until those legacy
/// branches are migrated behind tests.
pub fn run_mkgrd_gridinit_global_namelist(
    namelist_source: impl AsRef<Path>,
    workdir: impl AsRef<Path>,
    max_tris: usize,
) -> io::Result<MkgrdGridinitRunReport> {
    let namelist_source = namelist_source.as_ref();
    let workdir = workdir.as_ref();
    let contents = fs::read_to_string(namelist_source)?;
    let config = EarthmeshConfig::from_mkgrd_namelist(&contents)
        .map_err(|err| io::Error::new(io::ErrorKind::InvalidInput, err))?;

    if config.mask_restart {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "mask_restart mkgrd branch is not yet migrated to Rust",
        ));
    }
    if !matches!(config.mode_grid.as_str(), "hex" | "tri") {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "mode_grid {} is not supported by the gridinit branch",
                config.mode_grid
            ),
        ));
    }
    if config.nxp <= 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "NXP must be positive for gridinit",
        ));
    }
    if config.niter < 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "niter must be non-negative for gridinit",
        ));
    }
    let nxp = usize::try_from(config.nxp)
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "NXP must fit usize"))?;
    let niter = usize::try_from(config.niter)
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "niter must fit usize"))?;

    let plan = config.read_nl_workspace_plan(None);
    let workspace_mask =
        apply_workspace_and_mask_operations(&plan, namelist_source, workdir, 9, false)?;

    let mode_file = PathBuf::from(config.mode_file.trim());
    let (gridfile, runtime_state) = if mode_file.exists() {
        let gridfile = match config.mode_file_description.trim() {
            "EarthMesh" => copy_existing_earthmesh_mode_file(
                &mode_file,
                config.file_dir(),
                nxp,
                &config.mode_grid,
            )?,
            "MPAS" => convert_mpas_mode_file_to_earthmesh(
                &mode_file,
                config.file_dir(),
                nxp,
                &config.mode_grid,
            )?,
            "FVCOM" => convert_fvcom_mode_file_to_earthmesh(
                &mode_file,
                config.file_dir(),
                nxp,
                &config.mode_grid,
            )?,
            "IAP-Ocean" => convert_iap_ocean_mode_file_to_earthmesh(
                &mode_file,
                config.file_dir(),
                nxp,
                &config.mode_grid,
            )?,
            _ => {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidInput,
                    "only existing EarthMesh, MPAS, FVCOM, and IAP-Ocean mode_file ingestion are migrated to Rust",
                ));
            }
        };
        let mesh = read_unstructured_mesh_netcdf(&gridfile.output)?;
        let runtime_state = Some(earthmesh_runtime_state_from_compact_mesh(&config, &mesh)?);
        (gridfile, runtime_state)
    } else {
        let state = earthmesh_mesh::gridinit_voronoi_state_fortran(
            nxp,
            niter,
            f64::from(config.beta),
            f64::from(config.relax),
            max_tris,
        )?;
        let gridfile = write_gridfile_from_fortran_indexed_state(
            config.file_dir(),
            nxp,
            1,
            &config.mode_grid,
            &state.grid,
            &state.tabs,
        )?;
        let mut generated_runtime_state = EarthmeshRuntimeState::new(config.clone());
        generated_runtime_state.grid = state.grid;
        generated_runtime_state.ijtabs = state.tabs;
        generated_runtime_state
            .record_pentagon_indices_from_icosahedron(state.impent)
            .map_err(|err| io::Error::new(io::ErrorKind::InvalidInput, err))?;
        generated_runtime_state
            .record_mesh_counts_for_step(
                1,
                generated_runtime_state.grid.nma,
                generated_runtime_state.grid.nwa,
            )
            .map_err(|err| io::Error::new(io::ErrorKind::InvalidInput, err))?;
        (gridfile, Some(generated_runtime_state))
    };

    Ok(MkgrdGridinitRunReport {
        config,
        runtime_state,
        workspace_mask,
        gridfile,
    })
}

/// Read the landtype source and construct one-based source-grid arrays like
/// `MOD_data_preprocess.F90:data_preprocess`.
pub fn read_landtype_data_preprocess_fortran_indexed(
    landtype_file: impl AsRef<Path>,
    gridnum_perdegree: usize,
) -> io::Result<LandtypeDataPreprocessReport> {
    if gridnum_perdegree == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "gridnum_perdegree must be positive for data_preprocess",
        ));
    }
    let nlons_source = gridnum_perdegree.checked_mul(360).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "gridnum_perdegree * 360 overflows usize",
        )
    })?;
    let nlats_source = gridnum_perdegree.checked_mul(180).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "gridnum_perdegree * 180 overflows usize",
        )
    })?;

    let axes =
        build_global_source_axes_fortran_indexed(gridnum_perdegree, nlons_source, nlats_source)?;
    let file = netcdf::open(landtype_file.as_ref()).map_err(netcdf_to_io_error)?;
    let lon_dim = first_existing_dimension_len(&file, &["lon", "longitude"])?;
    let lat_dim = first_existing_dimension_len(&file, &["lat", "latitude"])?;
    if lon_dim != nlons_source {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "nlons_source from landtype_file {lon_dim} != gridnum_perdegree * 360 {nlons_source}"
            ),
        ));
    }
    if lat_dim != nlats_source {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "nlats_source from landtype_file {lat_dim} != gridnum_perdegree * 180 {nlats_source}"
            ),
        ));
    }
    let values = required_values_i8_matrix(
        &file,
        "landtype",
        "landtype_file longitude",
        "landtype_file latitude",
        nlons_source,
        nlats_source,
    )?;
    let mut landtypes_global = vec![vec![0_i32; nlats_source + 1]; nlons_source + 1];
    let mut maxlc = 0_i32;
    for lon_offset in 0..nlons_source {
        for lat_offset in 0..nlats_source {
            let value = i32::from(values[lon_offset * nlats_source + lat_offset]);
            landtypes_global[lon_offset + 1][lat_offset + 1] = value;
            maxlc = maxlc.max(value);
        }
    }

    Ok(LandtypeDataPreprocessReport {
        source: build_v3_data_source_descriptor(V3DataSourceKind::Landtype, landtype_file)?,
        gridnum_perdegree,
        nlons_source,
        nlats_source,
        lon_i: axes.lon_i,
        lat_i: axes.lat_i,
        lon_vertex: axes.lon_vertex,
        lat_vertex: axes.lat_vertex,
        landtypes_global,
        maxlc,
    })
}

/// Sample `landtype` values at mesh/grid cell centres without materialising the
/// full global source raster.
pub fn sample_landtype_values_for_points_fortran_indexed(
    landtype_file: impl AsRef<Path>,
    gridnum_perdegree: usize,
    points: &[LonLatPoint],
) -> io::Result<Vec<i32>> {
    if gridnum_perdegree == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "gridnum_perdegree must be positive for landtype sampling",
        ));
    }
    let nlons_source = gridnum_perdegree.checked_mul(360).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "gridnum_perdegree * 360 overflows usize",
        )
    })?;
    let nlats_source = gridnum_perdegree.checked_mul(180).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "gridnum_perdegree * 180 overflows usize",
        )
    })?;
    let axes =
        build_global_source_axes_fortran_indexed(gridnum_perdegree, nlons_source, nlats_source)?;
    if axes.lon_i.len() < 3 || axes.lat_i.len() < 3 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "land-type axes too short to derive sampling step",
        ));
    }

    let file = netcdf::open(landtype_file.as_ref()).map_err(netcdf_to_io_error)?;
    let lon_dim = first_existing_dimension_len(&file, &["lon", "longitude"])?;
    let lat_dim = first_existing_dimension_len(&file, &["lat", "latitude"])?;
    if lon_dim != nlons_source {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "nlons_source from landtype_file {lon_dim} != gridnum_perdegree * 360 {nlons_source}"
            ),
        ));
    }
    if lat_dim != nlats_source {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "nlats_source from landtype_file {lat_dim} != gridnum_perdegree * 180 {nlats_source}"
            ),
        ));
    }

    let variable = file
        .variable("landtype")
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "missing landtype variable"))?;
    let dimensions = variable.dimensions();
    if dimensions.len() != 2 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "landtype must be 2-D over longitude and latitude",
        ));
    }
    let dimension_names = dimensions
        .iter()
        .map(|dimension| dimension.name())
        .collect::<Vec<_>>();
    let dimension_lengths = dimensions
        .iter()
        .map(|dimension| dimension.len())
        .collect::<Vec<_>>();
    let lon_lat_order = if dimension_lengths == [nlons_source, nlats_source] {
        true
    } else if dimension_lengths == [nlats_source, nlons_source] {
        false
    } else {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "landtype dimensions {:?} with lengths {:?} do not match expected longitude x latitude",
                dimension_names, dimension_lengths
            ),
        ));
    };

    let lon0 = axes.lon_i[1];
    let lat0 = axes.lat_i[1];
    let dlon = axes.lon_i[2] - axes.lon_i[1];
    let dlat = axes.lat_i[2] - axes.lat_i[1];
    let mut cache = BTreeMap::<(usize, usize), i32>::new();
    let mut sampled = Vec::with_capacity(points.len());
    for point in points {
        let lon_index =
            (((point.lon - lon0) / dlon).round() as i64).rem_euclid(nlons_source as i64) as usize;
        let lat_index =
            (((point.lat - lat0) / dlat).round() as i64).clamp(0, nlats_source as i64 - 1) as usize;
        let value = if let Some(value) = cache.get(&(lon_index, lat_index)) {
            *value
        } else {
            let raw = if lon_lat_order {
                variable
                    .get_value::<i8, _>((lon_index, lat_index))
                    .map_err(netcdf_to_io_error)?
            } else {
                variable
                    .get_value::<i8, _>((lat_index, lon_index))
                    .map_err(netcdf_to_io_error)?
            };
            let value = i32::from(raw);
            cache.insert((lon_index, lat_index), value);
            value
        };
        sampled.push(value);
    }
    Ok(sampled)
}

/// Sample land-type values at points and return preview/coupling surface class
/// codes: 1=LAND, 2=OCEAN. Coast classes require separate hydro/coast data.
pub fn sample_landtype_surface_class_codes_for_points_fortran_indexed(
    landtype_file: impl AsRef<Path>,
    gridnum_perdegree: usize,
    points: &[LonLatPoint],
) -> io::Result<Vec<i8>> {
    sample_landtype_values_for_points_fortran_indexed(landtype_file, gridnum_perdegree, points).map(
        |values| {
            values
                .into_iter()
                .map(
                    |value| match classify_area_judge_landtype_fortran_indexed(value) {
                        AreaJudgeLandtypeClass::Land => 1,
                        AreaJudgeLandtypeClass::Ocean => 2,
                    },
                )
                .collect()
        },
    )
}

/// Read the `data_preprocess` landtype source and immediately build the
/// `Area_judge` sea/land source mask used by containment/refinement.
pub fn read_data_preprocess_area_judge_source_fortran_indexed(
    landtype_file: impl AsRef<Path>,
    gridnum_perdegree: usize,
    is_in_domain: &[Vec<i32>],
    bounds: AreaJudgeSourceBounds,
    mesh_type: &str,
    refine: bool,
) -> io::Result<DataPreprocessAreaJudgeSourceReport> {
    let preprocess =
        read_landtype_data_preprocess_fortran_indexed(landtype_file, gridnum_perdegree)?;
    let expected_lon = preprocess.nlons_source + 1;
    let expected_lat = preprocess.nlats_source + 1;
    validate_i32_matrix_shape("IsInDmArea_grid", is_in_domain, expected_lon, expected_lat)?;
    let seaorland = build_area_judge_seaorland_fortran_indexed(
        is_in_domain,
        &preprocess.landtypes_global,
        bounds,
        mesh_type,
        refine,
    )?;
    Ok(DataPreprocessAreaJudgeSourceReport {
        preprocess,
        seaorland,
    })
}

/// Read `data_preprocess` landtype data and build the non-restart
/// `Area_judge` base state from file-level inputs, matching the Fortran
/// `data_preprocess(); Area_judge()` handoff without module globals.
pub fn read_data_preprocess_area_judge_base_state_fortran_indexed(
    file_dir: impl AsRef<Path>,
    landtype_file: impl AsRef<Path>,
    gridnum_perdegree: usize,
    mask_domain_global: bool,
    mask_domain_type: &str,
    mask_domain_ndm: usize,
    mesh_type: &str,
    refine: bool,
) -> io::Result<AreaJudgeBaseStateReport> {
    let preprocess =
        read_landtype_data_preprocess_fortran_indexed(landtype_file, gridnum_perdegree)?;
    build_area_judge_base_state_fortran_indexed(
        file_dir,
        mask_domain_global,
        mask_domain_type,
        mask_domain_ndm,
        &preprocess.landtypes_global,
        mesh_type,
        refine,
        &preprocess.lon_vertex,
        &preprocess.lat_vertex,
        &preprocess.lon_i,
        &preprocess.lat_i,
        gridnum_perdegree,
        preprocess.nlons_source,
        preprocess.nlats_source,
    )
}

/// Build the owned source-state bundle consumed by migrated `mkgrd` refine
/// executors from `data_preprocess` landtype data plus `Area_judge` domain
/// classification.
pub fn build_mkgrd_data_preprocess_source_state_fortran_indexed(
    file_dir: impl AsRef<Path>,
    landtype_file: impl AsRef<Path>,
    gridnum_perdegree: usize,
    mask_domain_global: bool,
    mask_domain_type: &str,
    mask_domain_ndm: usize,
    mesh_type: &str,
    refine: bool,
    num_vertex: usize,
    first_triangle_id: usize,
) -> io::Result<MkgrdDataPreprocessSourceState> {
    let preprocess =
        read_landtype_data_preprocess_fortran_indexed(landtype_file, gridnum_perdegree)?;
    let base = build_area_judge_base_state_fortran_indexed(
        file_dir,
        mask_domain_global,
        mask_domain_type,
        mask_domain_ndm,
        &preprocess.landtypes_global,
        mesh_type,
        refine,
        &preprocess.lon_vertex,
        &preprocess.lat_vertex,
        &preprocess.lon_i,
        &preprocess.lat_i,
        gridnum_perdegree,
        preprocess.nlons_source,
        preprocess.nlats_source,
    )?;

    Ok(MkgrdDataPreprocessSourceState {
        lon_vertex: preprocess.lon_vertex,
        lat_vertex: preprocess.lat_vertex,
        lon_i: preprocess.lon_i,
        lat_i: preprocess.lat_i,
        gridnum_perdegree,
        nlons_source: preprocess.nlons_source,
        nlats_source: preprocess.nlats_source,
        first_triangle_id,
        num_vertex,
        sources: vec![preprocess.source.clone()],
        is_in_domain: base.domain.is_in_domain,
        seaorland: base.seaorland.seaorland,
        landtypes_global: preprocess.landtypes_global,
        maxlc: preprocess.maxlc,
    })
}

/// Build the owned `data_preprocess` source-state bundle from parsed mkgrd
/// namelist config plus CLI/source-state overrides.
///
/// This centralizes the direct `mkgrd` front-end expansion of `NL%landtype_file`,
/// `NL%gridnum_perdegree`, `NL%mode_grid`, domain flags, and source first-id
/// values before the migrated refine executors consume typed Rust state.
pub fn build_mkgrd_data_preprocess_source_state_from_config_fortran_indexed(
    file_dir: impl AsRef<Path>,
    config: &EarthmeshConfig,
    source_gridnum_perdegree: Option<usize>,
    source_first_triangle_id: usize,
) -> io::Result<MkgrdDataPreprocessSourceState> {
    let gridnum_perdegree = match source_gridnum_perdegree {
        Some(value) => value,
        None => usize::try_from(config.gridnum_perdegree).map_err(|_| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                format!(
                    "NL%gridnum_perdegree must be positive for data_preprocess source state, got {}",
                    config.gridnum_perdegree
                ),
            )
        })?,
    };
    if gridnum_perdegree == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "NL%gridnum_perdegree must be positive for data_preprocess source state, got {}",
                config.gridnum_perdegree
            ),
        ));
    }
    build_mkgrd_data_preprocess_source_state_fortran_indexed(
        file_dir,
        Path::new(config.landtype_file.trim()),
        gridnum_perdegree,
        config.mask_domain_global,
        config.mask_domain_type.trim(),
        1,
        config.mesh_type.trim(),
        config.refine,
        1,
        source_first_triangle_id,
    )
}

fn earthmesh_runtime_state_from_compact_mesh(
    config: &EarthmeshConfig,
    mesh: &UnstructuredMesh,
) -> io::Result<EarthmeshRuntimeState> {
    validate_unstructured_mesh(mesh)?;
    let nma = mesh.m_points.len();
    let nwa = mesh.w_points.len();
    let mut state = EarthmeshRuntimeState::new(config.clone());
    state.grid = GridMemory {
        nma,
        nua: 0,
        nva: 0,
        nwa,
        mma: nma,
        mua: 0,
        mva: 0,
        mwa: nwa,
        ..GridMemory::default()
    };
    state.grid.allocate_xyzem(nma);
    state.grid.allocate_xyzew(nwa);
    state.grid.allocate_grid_lonlatmw(nma, 0, nwa);
    for (idx, point) in mesh.m_points.iter().enumerate() {
        state.grid.glonm[idx] = point.lon as f32;
        state.grid.glatm[idx] = point.lat as f32;
    }
    for (idx, point) in mesh.w_points.iter().enumerate() {
        state.grid.glonw[idx] = point.lon as f32;
        state.grid.glatw[idx] = point.lat as f32;
    }

    state
        .record_mesh_counts_for_step(1, nma, nwa)
        .map_err(|err| io::Error::new(io::ErrorKind::InvalidInput, err))?;

    state.ijtabs = IjTabs::allocate(nma, 0, nwa);
    for (idx, row) in mesh.m_to_w.iter().enumerate() {
        state.ijtabs.m[idx].imp = usize_to_i32("compact mesh M index", idx + 1)?;
        state.ijtabs.m[idx].imglobe = state.ijtabs.m[idx].imp;
        state.ijtabs.m[idx].npoly = 3;
        state.ijtabs.m[idx].iw = *row;
    }
    for (idx, row) in mesh.w_to_m.iter().enumerate() {
        state.ijtabs.w[idx].iwp = usize_to_i32("compact mesh W index", idx + 1)?;
        state.ijtabs.w[idx].iwglobe = state.ijtabs.w[idx].iwp;
        state.ijtabs.w[idx].npoly = *mesh.n_w_to_m.get(idx).unwrap_or(&0);
        for (slot, value) in row.iter().copied().take(7).enumerate() {
            state.ijtabs.w[idx].im[slot] = value;
        }
    }

    Ok(state)
}

/// Rust data shape written by `MOD_file_preprocess.F90:Contain_Save`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ContainMesh {
    pub ustr_id: Vec<Vec<i32>>,
    pub ustr_ii: Vec<Vec<i32>>,
    pub is_in_area_ustr: Vec<i32>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FlatContainMesh {
    pub ustr_id_values: Vec<i32>,
    pub ustr_id_width: usize,
    pub ustr_ii_values: Vec<i32>,
    pub ustr_ii_width: usize,
    pub is_in_area_ustr: Vec<i32>,
}

impl FlatContainMesh {
    pub fn num_ustr(&self) -> usize {
        self.ustr_id_values
            .len()
            .checked_div(self.ustr_id_width)
            .unwrap_or(0)
    }

    pub fn num_ii(&self) -> usize {
        self.ustr_ii_values
            .len()
            .checked_div(self.ustr_ii_width)
            .unwrap_or(0)
    }

    pub fn to_contain_mesh(&self) -> io::Result<ContainMesh> {
        validate_flat_contain_mesh(self)?;
        Ok(ContainMesh {
            ustr_id: rows_from_flat_i32(&self.ustr_id_values, self.ustr_id_width),
            ustr_ii: rows_from_flat_i32(&self.ustr_ii_values, self.ustr_ii_width),
            is_in_area_ustr: self.is_in_area_ustr.clone(),
        })
    }
}

/// Runtime inputs for a file-backed `MOD_GetContain.F90:Get_Contain(iter)`
/// refinement pass. The input gridfile is the current triangular refine grid,
/// and `area_grid_file` is the selected `Area_judge_refine(iter)` grid.
#[derive(Debug, Clone, Copy)]
pub struct GetContainRefineFileRunConfig<'a> {
    pub gridfile: &'a Path,
    pub area_grid_file: &'a Path,
    pub output: &'a Path,
    pub mesh_kind: GetContainMeshKind,
    pub seaorland: &'a [Vec<i32>],
    pub lon_vertex: &'a [f64],
    pub lat_vertex: &'a [f64],
    pub lon_i: &'a [f64],
    pub lat_i: &'a [f64],
    pub num_vertex: usize,
}

/// Explicit runtime counter handoff that Fortran stored in
/// `consts_coms:num_mp_step`, `num_wp_step`, and `num_vertex` during
/// `MOD_GetContain.F90:Get_Contain(iter)`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct GetContainRuntimeCounts {
    pub current_num_mp_step: usize,
    pub current_num_wp_step: usize,
    pub previous_num_vertex: usize,
}

/// Evidence from writing one refine `Contain_Save` file.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct GetContainRefineFileRunReport {
    pub output: PathBuf,
    pub active_unstructured_cells: usize,
    pub contained_source_pixels: usize,
    pub runtime_counts: GetContainRuntimeCounts,
    pub write: ContainWriteReport,
}

/// Axis-aligned domain/refinement bounds used by
/// `MOD_GetContain.F90:IsInArea_ustr_Calculation`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct GetContainAreaBounds {
    pub west: f64,
    pub east: f64,
    pub south: f64,
    pub north: f64,
}

/// Mesh-specific containment semantics from
/// `MOD_GetContain.F90:Contain_Calculation`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum GetContainMeshKind {
    Land,
    Ocean,
    Atmos,
    Loc,
}

impl GetContainMeshKind {
    fn ustr_id_width(self) -> usize {
        match self {
            Self::Ocean | Self::Loc => 3,
            Self::Land | Self::Atmos => 2,
        }
    }

    fn ustr_ii_width(self) -> usize {
        match self {
            Self::Atmos | Self::Loc => 3,
            Self::Land | Self::Ocean => 2,
        }
    }
}

fn getcontain_mesh_kind_from_mesh_type(mesh_type: &str) -> io::Result<GetContainMeshKind> {
    match mesh_type {
        "landmesh" => Ok(GetContainMeshKind::Land),
        "oceanmesh" => Ok(GetContainMeshKind::Ocean),
        "atmosmesh" => Ok(GetContainMeshKind::Atmos),
        "LOCmesh" | "earthmesh" => Ok(GetContainMeshKind::Loc),
        other => Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("unsupported Get_Contain mesh_type {other}"),
        )),
    }
}

/// Port of `MOD_GetContain.F90:IsInArea_ustr_Calculation`.
///
/// The inputs keep Fortran indexing conventions: row `0` is normally a dummy,
/// vertex ids in `cell_to_vertices` are one-based, and rows `<= num_vertex`
/// are preserved as unselected because the Fortran loop starts at
/// `num_vertex + 1`.
pub fn getcontain_is_in_area_ustr_fortran_indexed(
    bounds: GetContainAreaBounds,
    vertices: &[LonLatPoint],
    cell_to_vertices: &[Vec<i32>],
    n_edges: &[i32],
    num_vertex: usize,
) -> io::Result<Vec<i32>> {
    if n_edges.len() != cell_to_vertices.len() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "n_edges length {} must match cell_to_vertices rows {}",
                n_edges.len(),
                cell_to_vertices.len()
            ),
        ));
    }
    if bounds.west >= bounds.east || bounds.south >= bounds.north {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "area bounds must satisfy west < east and south < north",
        ));
    }

    let mut is_in_area_ustr = vec![0; cell_to_vertices.len()];
    let start_row = num_vertex.saturating_add(1);

    for cell_index in start_row..cell_to_vertices.len() {
        let polygon = getcontain_cell_polygon(cell_index, vertices, cell_to_vertices, n_edges)?;
        if polygon.iter().any(|point| {
            point.x > bounds.west
                && point.x < bounds.east
                && point.y > bounds.south
                && point.y < bounds.north
        }) {
            is_in_area_ustr[cell_index] = 1;
        }
    }

    let domain_corners = [
        AreaJudgePoint::new(bounds.east, bounds.north),
        AreaJudgePoint::new(bounds.west, bounds.north),
        AreaJudgePoint::new(bounds.west, bounds.south),
        AreaJudgePoint::new(bounds.east, bounds.south),
    ];
    for cell_index in start_row..cell_to_vertices.len() {
        if is_in_area_ustr[cell_index] != 0 {
            continue;
        }
        let polygon = getcontain_cell_polygon(cell_index, vertices, cell_to_vertices, n_edges)?;
        if polygon.is_empty() {
            continue;
        }
        let (min_lon, max_lon) = polygon.iter().fold(
            (f64::INFINITY, f64::NEG_INFINITY),
            |(min_lon, max_lon), point| (min_lon.min(point.x), max_lon.max(point.x)),
        );
        for corner in domain_corners {
            if is_point_in_convex_polygon(&polygon, corner) {
                if max_lon - min_lon > 180.0 {
                    break;
                }
                is_in_area_ustr[cell_index] = 1;
                break;
            }
        }
    }

    Ok(is_in_area_ustr)
}

/// Non-polar core of `MOD_GetContain.F90:Contain_Calculation`.
///
/// This covers the main land/ocean/atmos scan that fills `ustr_id` and
/// `ustr_ii` after `Data_Updata` has identified active unstructured cells,
/// including the Fortran `icl_points` dateline-shift branch, south-pole
/// triangle reshaping, and south-pole pentagon virtual-wedge split/merge.
/// Refine-adjacent polar polygon adjustments remain a separate migration slice.
pub fn getcontain_containment_matrix_fortran_indexed(
    mesh_kind: GetContainMeshKind,
    vertices: &[LonLatPoint],
    cell_to_vertices: &[Vec<i32>],
    n_edges: &[i32],
    is_in_area_ustr: &[i32],
    is_in_area_grid: &[Vec<i32>],
    seaorland: &[Vec<i32>],
    lon_i: &[f64],
    lat_i: &[f64],
    num_vertex: usize,
) -> io::Result<ContainMesh> {
    getcontain_containment_matrix_flat_fortran_indexed(
        mesh_kind,
        vertices,
        cell_to_vertices,
        n_edges,
        is_in_area_ustr,
        is_in_area_grid,
        seaorland,
        lon_i,
        lat_i,
        num_vertex,
    )?
    .to_contain_mesh()
}

pub fn getcontain_containment_matrix_flat_fortran_indexed(
    mesh_kind: GetContainMeshKind,
    vertices: &[LonLatPoint],
    cell_to_vertices: &[Vec<i32>],
    n_edges: &[i32],
    is_in_area_ustr: &[i32],
    is_in_area_grid: &[Vec<i32>],
    seaorland: &[Vec<i32>],
    lon_i: &[f64],
    lat_i: &[f64],
    num_vertex: usize,
) -> io::Result<FlatContainMesh> {
    if is_in_area_ustr.len() != cell_to_vertices.len() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "IsInArea_ustr length {} must match cell_to_vertices rows {}",
                is_in_area_ustr.len(),
                cell_to_vertices.len()
            ),
        ));
    }
    if lon_i.len() < 2 || lat_i.len() < 2 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "lon_i and lat_i must include a dummy slot plus at least one source point",
        ));
    }
    getcontain_validate_source_matrix("IsInArea_grid", is_in_area_grid, lon_i.len(), lat_i.len())?;
    getcontain_validate_source_matrix("seaorland", seaorland, lon_i.len(), lat_i.len())?;

    let global_min_lat = vertices
        .iter()
        .filter_map(|point| point.lat.is_finite().then_some(point.lat))
        .fold(f64::INFINITY, f64::min);
    if !global_min_lat.is_finite() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "vertices must include at least one finite latitude",
        ));
    }

    let id_width = mesh_kind.ustr_id_width();
    let ii_width = mesh_kind.ustr_ii_width();
    let mut ustr_id_values = vec![0_i32; cell_to_vertices.len() * id_width];
    let mut ustr_ii_values = Vec::<i32>::new();
    let mut selected_mask = is_in_area_ustr.to_vec();
    let start_row = num_vertex.saturating_add(1);

    for cell_index in start_row..cell_to_vertices.len() {
        if is_in_area_ustr[cell_index] != 1 {
            continue;
        }
        let polygon = getcontain_cell_polygon(cell_index, vertices, cell_to_vertices, n_edges)?;
        let scan_polygons = getcontain_south_pole_scan_polygons(&polygon, global_min_lat);

        let mut total_inside = 0;
        let entry_start = ustr_ii_values.len();
        for mut scan_polygon in scan_polygons {
            let (min_lon, max_lon) = scan_polygon.iter().fold(
                (f64::INFINITY, f64::NEG_INFINITY),
                |(min_lon, max_lon), point| (min_lon.min(point.x), max_lon.max(point.x)),
            );
            let crosses_dateline = max_lon - min_lon > 180.0;
            if crosses_dateline {
                scan_polygon = shift_longitudes_for_dateline_crossing(&scan_polygon);
            }

            let (min_lon, max_lon) = scan_polygon.iter().fold(
                (f64::INFINITY, f64::NEG_INFINITY),
                |(min_lon, max_lon), point| (min_lon.min(point.x), max_lon.max(point.x)),
            );
            let (min_lat, max_lat) = scan_polygon.iter().fold(
                (f64::INFINITY, f64::NEG_INFINITY),
                |(min_lat, max_lat), point| (min_lat.min(point.y), max_lat.max(point.y)),
            );
            let Some(lon_range) = getcontain_axis_candidate_range(lon_i, min_lon, max_lon) else {
                continue;
            };
            let Some(lat_range) = getcontain_axis_candidate_range(lat_i, min_lat, max_lat) else {
                continue;
            };

            for i in lon_range {
                let restored_i = if crosses_dateline {
                    getcontain_restore_dateline_source_index(i, lon_i.len() - 1)?
                } else {
                    i
                };
                for j in lat_range.clone() {
                    if is_in_area_grid[restored_i][j] == 0 {
                        continue;
                    }
                    let point = AreaJudgePoint::new(lon_i[i], lat_i[j]);
                    if !is_point_in_convex_polygon(&scan_polygon, point) {
                        continue;
                    }
                    total_inside += 1;
                    match mesh_kind {
                        GetContainMeshKind::Land => {
                            if seaorland[restored_i][j] == 1 {
                                ustr_ii_values.extend_from_slice(&[restored_i as i32, j as i32]);
                            }
                        }
                        GetContainMeshKind::Ocean => {
                            if seaorland[restored_i][j] == 0 {
                                ustr_ii_values.extend_from_slice(&[restored_i as i32, j as i32]);
                            }
                        }
                        GetContainMeshKind::Atmos => {
                            ustr_ii_values.extend_from_slice(&[
                                restored_i as i32,
                                j as i32,
                                if seaorland[restored_i][j] == 1 { 1 } else { 0 },
                            ]);
                        }
                        GetContainMeshKind::Loc => {
                            ustr_ii_values.extend_from_slice(&[
                                restored_i as i32,
                                j as i32,
                                if seaorland[restored_i][j] == 1 { 1 } else { 0 },
                            ]);
                        }
                    }
                }
            }
        }

        let contained =
            i32::try_from((ustr_ii_values.len() - entry_start) / ii_width).map_err(|_| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "contained source-pixel count exceeds i32",
                )
            })?;
        let id_offset = cell_index * id_width;
        ustr_id_values[id_offset] = contained;
        if mesh_kind == GetContainMeshKind::Ocean {
            ustr_id_values[id_offset + 2] = total_inside;
        }
        if contained == 0 {
            selected_mask[cell_index] = 0;
        }
    }

    let mut next_start = 1;
    if num_vertex > 0 && num_vertex < cell_to_vertices.len() {
        let id_offset = num_vertex * id_width;
        ustr_id_values[id_offset + 1] = next_start;
        next_start += ustr_id_values[id_offset];
    }
    for row in start_row..cell_to_vertices.len() {
        let id_offset = row * id_width;
        ustr_id_values[id_offset + 1] = next_start;
        next_start += ustr_id_values[id_offset];
    }

    let numpatch = usize::try_from(next_start - 1).map_err(|_| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            "contained source-pixel count exceeds usize",
        )
    })?;
    if numpatch != ustr_ii_values.len() / ii_width {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "internal containment entry count mismatch",
        ));
    }

    Ok(FlatContainMesh {
        ustr_id_values,
        ustr_id_width: id_width,
        ustr_ii_values,
        ustr_ii_width: ii_width,
        is_in_area_ustr: selected_mask,
    })
}

fn getcontain_axis_candidate_range(
    axis: &[f64],
    min_value: f64,
    max_value: f64,
) -> Option<std::ops::Range<usize>> {
    if axis.len() < 2 || !min_value.is_finite() || !max_value.is_finite() {
        return None;
    }
    let lower = min_value.min(max_value) - 1.0e-12;
    let upper = min_value.max(max_value) + 1.0e-12;
    let values = &axis[1..];
    let first = values[0];
    let last = *values.last()?;
    let (start_offset, end_offset) = if first <= last {
        (
            values.partition_point(|value| *value < lower),
            values.partition_point(|value| *value <= upper),
        )
    } else {
        (
            values.partition_point(|value| *value > upper),
            values.partition_point(|value| *value >= lower),
        )
    };
    let start = start_offset + 1;
    let end = end_offset + 1;
    (start < end).then_some(start..end)
}

fn getcontain_south_pole_scan_polygons(
    polygon: &[AreaJudgePoint],
    global_min_lat: f64,
) -> Vec<Vec<AreaJudgePoint>> {
    let cell_min_lat = polygon
        .iter()
        .map(|point| point.y)
        .fold(f64::INFINITY, f64::min);
    if (cell_min_lat - global_min_lat).abs() > 1.0e-12 {
        return vec![polygon.to_vec()];
    }

    if polygon.len() == 3 {
        return vec![vec![
            AreaJudgePoint::new(polygon[2].x, polygon[0].y),
            AreaJudgePoint::new(polygon[1].x, polygon[0].y),
            polygon[1],
            polygon[2],
        ]];
    }

    if polygon.len() != 5 {
        return vec![polygon.to_vec()];
    }

    let mut sorted = polygon.to_vec();
    sorted.sort_by(|left, right| {
        left.x
            .partial_cmp(&right.x)
            .unwrap_or(std::cmp::Ordering::Equal)
    });

    let mut wedges = Vec::with_capacity(sorted.len());
    for i in 0..sorted.len() {
        let j = (i + 1) % sorted.len();
        wedges.push(vec![
            sorted[j],
            sorted[i],
            AreaJudgePoint::new(sorted[i].x, -90.0),
            AreaJudgePoint::new(sorted[j].x, -90.0),
        ]);
    }
    wedges
}

fn getcontain_restore_dateline_source_index(
    index: usize,
    nlons_source: usize,
) -> io::Result<usize> {
    if nlons_source == 0 || !nlons_source.is_multiple_of(2) {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "dateline containment requires a positive even nlons_source, got {nlons_source}"
            ),
        ));
    }
    if index == 0 || index > nlons_source {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("dateline source index {index} is outside 1..={nlons_source}"),
        ));
    }
    let half = nlons_source / 2;
    if index < half + 1 {
        Ok(index + half)
    } else {
        Ok(index - half)
    }
}

fn getcontain_cell_polygon(
    cell_index: usize,
    vertices: &[LonLatPoint],
    cell_to_vertices: &[Vec<i32>],
    n_edges: &[i32],
) -> io::Result<Vec<AreaJudgePoint>> {
    let edge_count = usize::try_from(n_edges[cell_index]).map_err(|_| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "cell {cell_index} has negative edge count {}",
                n_edges[cell_index]
            ),
        )
    })?;
    let row = &cell_to_vertices[cell_index];
    if edge_count > row.len() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "cell {cell_index} edge count {edge_count} exceeds vertex row width {}",
                row.len()
            ),
        ));
    }

    let mut polygon = Vec::with_capacity(edge_count);
    for vertex_id in row.iter().take(edge_count) {
        if *vertex_id <= 0 {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                format!("cell {cell_index} references missing vertex {vertex_id}"),
            ));
        }
        let vertex_index = usize::try_from(*vertex_id).map_err(|_| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                format!("cell {cell_index} references missing vertex {vertex_id}"),
            )
        })?;
        let vertex = vertices.get(vertex_index).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                format!("cell {cell_index} references missing vertex {vertex_id}"),
            )
        })?;
        polygon.push(AreaJudgePoint::new(vertex.lon, vertex.lat));
    }
    Ok(polygon)
}

fn getcontain_validate_source_matrix(
    name: &str,
    matrix: &[Vec<i32>],
    lon_len: usize,
    lat_len: usize,
) -> io::Result<()> {
    if matrix.len() != lon_len {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "{name} longitude rows {} must match lon_i length {lon_len}",
                matrix.len()
            ),
        ));
    }
    for (index, row) in matrix.iter().enumerate() {
        if row.len() != lat_len {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!(
                    "{name} row {index} latitude length {} must match lat_i length {lat_len}",
                    row.len()
                ),
            ));
        }
    }
    Ok(())
}

