/// Write the simple MPAS mesh schema produced by
/// `MOD_file_preprocess.F90:MPAS_Mesh_Simple_Save`.
pub fn write_mpas_simple_mesh_netcdf(
    output: impl AsRef<Path>,
    mesh: &MpasSimpleMesh,
) -> io::Result<MpasSimpleMeshWriteReport> {
    validate_mpas_simple_mesh(mesh)?;
    let output = output.as_ref();
    if let Some(parent) = output.parent() {
        fs::create_dir_all(parent)?;
    }

    let n_cells = mesh.x_cell.len() - 1;
    let n_vertices = mesh.x_vertex.len() - 1;

    let mut file = netcdf::create(output).map_err(netcdf_to_io_error)?;
    file.add_dimension("nCells", n_cells)
        .map_err(netcdf_to_io_error)?;
    file.add_dimension("nVertices", n_vertices)
        .map_err(netcdf_to_io_error)?;
    file.add_dimension("vertexDegree", 3)
        .map_err(netcdf_to_io_error)?;

    write_f64_1d(&mut file, "xCell", "nCells", &mesh.x_cell[1..])?;
    write_f64_1d(&mut file, "yCell", "nCells", &mesh.y_cell[1..])?;
    write_f64_1d(&mut file, "zCell", "nCells", &mesh.z_cell[1..])?;
    write_f64_1d(&mut file, "xVertex", "nVertices", &mesh.x_vertex[1..])?;
    write_f64_1d(&mut file, "yVertex", "nVertices", &mesh.y_vertex[1..])?;
    write_f64_1d(&mut file, "zVertex", "nVertices", &mesh.z_vertex[1..])?;
    {
        let mut var = file
            .add_variable::<i32>("cellsOnVertex", &["nVertices", "vertexDegree"])
            .map_err(netcdf_to_io_error)?;
        var.put_attribute("units", "-")
            .map_err(netcdf_to_io_error)?;
        var.put_attribute("long_name", "IDs of the cells that meet at a vertex")
            .map_err(netcdf_to_io_error)?;
        var.put_values(&flatten_i32_rows(&mesh.cells_on_vertex[1..]), (.., ..))
            .map_err(netcdf_to_io_error)?;
    }
    write_f64_1d(&mut file, "meshDensity", "nCells", &mesh.mesh_density[1..])?;

    file.add_attribute("on_a_sphere", "YES")
        .map_err(netcdf_to_io_error)?;
    file.add_attribute("sphere_radius", 1.0_f64)
        .map_err(netcdf_to_io_error)?;

    Ok(MpasSimpleMeshWriteReport {
        output: output.to_path_buf(),
        n_cells,
        n_vertices,
    })
}

/// Write the full MPAS mesh schema produced by
/// `MOD_file_preprocess.F90:MPAS_Mesh_Save`.
///
/// The Rust data shape preserves the legacy placeholder row at index `0`; all
/// MPAS-facing variables are written from index `1..`, matching Fortran slices
/// such as `2:num_dbx`, `2:num_sjx`, and `2:num_edge`. Connectivity ids have
/// the internal placeholder row removed before writing, so valid file ids stay
/// 1-based while `0` remains the no-neighbour/missing marker.
pub fn write_mpas_mesh_netcdf(
    output: impl AsRef<Path>,
    mesh: &MpasMesh,
) -> io::Result<MpasMeshWriteReport> {
    validate_mpas_mesh(mesh)?;
    let output = output.as_ref();
    if let Some(parent) = output.parent() {
        fs::create_dir_all(parent)?;
    }

    let n_cells = mesh.x_cell.len() - 1;
    let n_vertices = mesh.x_vertex.len() - 1;
    let n_edges = mesh.x_edge.len() - 1;

    let mut file = netcdf::create(output).map_err(netcdf_to_io_error)?;
    file.add_dimension("nCells", n_cells)
        .map_err(netcdf_to_io_error)?;
    file.add_dimension("nVertices", n_vertices)
        .map_err(netcdf_to_io_error)?;
    file.add_dimension("nEdges", n_edges)
        .map_err(netcdf_to_io_error)?;
    file.add_dimension("maxEdges", 10)
        .map_err(netcdf_to_io_error)?;
    file.add_dimension("maxEdges2", 20)
        .map_err(netcdf_to_io_error)?;
    file.add_dimension("TWO", 2).map_err(netcdf_to_io_error)?;
    file.add_dimension("vertexDegree", 3)
        .map_err(netcdf_to_io_error)?;

    write_i32_1d(
        &mut file,
        "indexToCellID",
        "nCells",
        &one_to_n_i32(n_cells, "indexToCellID")?,
    )?;
    write_f64_1d(&mut file, "latCell", "nCells", &mesh.lat_cell[1..])?;
    write_f64_1d(&mut file, "lonCell", "nCells", &mesh.lon_cell[1..])?;
    write_f64_1d(&mut file, "xCell", "nCells", &mesh.x_cell[1..])?;
    write_f64_1d(&mut file, "yCell", "nCells", &mesh.y_cell[1..])?;
    write_f64_1d(&mut file, "zCell", "nCells", &mesh.z_cell[1..])?;
    write_i32_1d(
        &mut file,
        "indexToVertexID",
        "nVertices",
        &one_to_n_i32(n_vertices, "indexToVertexID")?,
    )?;
    write_f64_1d(&mut file, "latVertex", "nVertices", &mesh.lat_vertex[1..])?;
    write_f64_1d(&mut file, "lonVertex", "nVertices", &mesh.lon_vertex[1..])?;
    write_f64_1d(&mut file, "xVertex", "nVertices", &mesh.x_vertex[1..])?;
    write_f64_1d(&mut file, "yVertex", "nVertices", &mesh.y_vertex[1..])?;
    write_f64_1d(&mut file, "zVertex", "nVertices", &mesh.z_vertex[1..])?;
    write_i32_1d(
        &mut file,
        "indexToEdgeID",
        "nEdges",
        &one_to_n_i32(n_edges, "indexToEdgeID")?,
    )?;
    write_f64_1d(&mut file, "latEdge", "nEdges", &mesh.lat_edge[1..])?;
    write_f64_1d(&mut file, "lonEdge", "nEdges", &mesh.lon_edge[1..])?;
    write_f64_1d(&mut file, "xEdge", "nEdges", &mesh.x_edge[1..])?;
    write_f64_1d(&mut file, "yEdge", "nEdges", &mesh.y_edge[1..])?;
    write_f64_1d(&mut file, "zEdge", "nEdges", &mesh.z_edge[1..])?;
    write_i32_1d(
        &mut file,
        "nEdgesOnCell",
        "nCells",
        &mesh.n_edges_on_cell[1..],
    )?;
    write_i32_matrix_rows(
        &mut file,
        "cellsOnCell",
        &["nCells", "maxEdges"],
        &mesh.cells_on_cell[1..],
    )?;
    write_i32_matrix_rows(
        &mut file,
        "verticesOnCell",
        &["nCells", "maxEdges"],
        &mesh.vertices_on_cell[1..],
    )?;
    write_i32_matrix_rows(
        &mut file,
        "edgesOnCell",
        &["nCells", "maxEdges"],
        &mesh.edges_on_cell[1..],
    )?;
    write_i32_matrix_rows(
        &mut file,
        "cellsOnVertex",
        &["nVertices", "vertexDegree"],
        &mesh.cells_on_vertex[1..],
    )?;
    write_i32_matrix_rows(
        &mut file,
        "edgesOnVertex",
        &["nVertices", "vertexDegree"],
        &mesh.edges_on_vertex[1..],
    )?;
    write_i32_pair_rows(
        &mut file,
        "cellsOnEdge",
        &["nEdges", "TWO"],
        &mesh.cells_on_edge[1..],
    )?;
    write_i32_pair_rows(
        &mut file,
        "verticesOnEdge",
        &["nEdges", "TWO"],
        &mesh.vertices_on_edge[1..],
    )?;
    write_i32_1d(
        &mut file,
        "nEdgesOnEdge",
        "nEdges",
        &mesh.n_edges_on_edge[1..],
    )?;
    write_i32_matrix_rows(
        &mut file,
        "edgesOnEdge",
        &["nEdges", "maxEdges2"],
        &mesh.edges_on_edge[1..],
    )?;
    write_f64_1d(&mut file, "areaCell", "nCells", &mesh.area_cell[1..])?;
    write_f64_1d(
        &mut file,
        "areaTriangle",
        "nVertices",
        &mesh.area_triangle[1..],
    )?;
    write_f64_matrix_rows(
        &mut file,
        "kiteAreasOnVertex",
        &["nVertices", "vertexDegree"],
        &mesh.kite_areas_on_vertex[1..],
    )?;
    write_f64_1d(&mut file, "dvEdge", "nEdges", &mesh.dv_edge[1..])?;
    write_f64_1d(&mut file, "dcEdge", "nEdges", &mesh.dc_edge[1..])?;
    write_f64_1d(&mut file, "angleEdge", "nEdges", &mesh.angle_edge[1..])?;
    write_f64_matrix_rows(
        &mut file,
        "weightsOnEdge",
        &["nEdges", "maxEdges2"],
        &mesh.weights_on_edge[1..],
    )?;
    write_f64_1d(&mut file, "meshDensity", "nCells", &mesh.mesh_density[1..])?;
    {
        let mut var = file
            .add_variable::<f64>("nominalMinDc", &[])
            .map_err(netcdf_to_io_error)?;
        var.put_values(&[mesh.nominal_min_dc], ..)
            .map_err(netcdf_to_io_error)?;
    }
    write_f64_1d(
        &mut file,
        "error_segment",
        "nEdges",
        &mesh.error_segment[1..],
    )?;

    file.add_attribute("mesh_spec", "1.0")
        .map_err(netcdf_to_io_error)?;
    file.add_attribute("on_a_sphere", "YES")
        .map_err(netcdf_to_io_error)?;
    file.add_attribute("sphere_radius", 1.0_f64)
        .map_err(netcdf_to_io_error)?;
    file.add_attribute("is_periodic", "NO")
        .map_err(netcdf_to_io_error)?;
    file.add_attribute("x_period", 0.0_f64)
        .map_err(netcdf_to_io_error)?;
    file.add_attribute("y_period", 0.0_f64)
        .map_err(netcdf_to_io_error)?;
    file.add_attribute("file_id", "bbdd9043")
        .map_err(netcdf_to_io_error)?;
    file.add_attribute("source", "Generated by EarthMesh")
        .map_err(netcdf_to_io_error)?;

    Ok(MpasMeshWriteReport {
        output: output.to_path_buf(),
        n_cells,
        n_vertices,
        n_edges,
    })
}

/// Write the METIS-style `graph.info` text produced by
/// `MOD_file_preprocess.F90:MPAS_info_Save`.
///
/// Inputs keep the legacy placeholder row at Rust index `0`; only rows/edges
/// from index `1` onward are written or counted, matching Fortran `2:nCells`
/// and `2:nEdges` loops after internal placeholder-row removal.
pub fn write_mpas_graph_info(
    output: impl AsRef<Path>,
    max_edges: usize,
    cells_on_cell: &[Vec<i32>],
    cells_on_edge: &[[i32; 2]],
    n_edges_on_cell: &[i32],
) -> io::Result<MpasGraphInfoWriteReport> {
    if max_edges == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "max_edges must be positive",
        ));
    }
    if cells_on_cell.is_empty() || cells_on_edge.is_empty() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "MPAS graph info inputs must include the legacy placeholder row",
        ));
    }
    if cells_on_cell.len() != n_edges_on_cell.len() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "n_edges_on_cell length {} must match cells_on_cell length {}",
                n_edges_on_cell.len(),
                cells_on_cell.len()
            ),
        ));
    }
    for (idx, row) in cells_on_cell.iter().enumerate() {
        if row.len() < max_edges {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!(
                    "cells_on_cell row {idx} width {} must be at least max_edges {max_edges}",
                    row.len()
                ),
            ));
        }
    }
    if n_edges_on_cell.iter().any(|&value| value < 0) {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "n_edges_on_cell values must be non-negative",
        ));
    }

    let mut n_edges_on_cell_usize = Vec::with_capacity(n_edges_on_cell.len());
    for (idx, &value) in n_edges_on_cell.iter().enumerate() {
        let count = usize::try_from(value).map_err(|_| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("n_edges_on_cell row {idx} is out of range"),
            )
        })?;
        if count > max_edges {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("n_edges_on_cell row {idx} exceeds max_edges {max_edges}"),
            ));
        }
        n_edges_on_cell_usize.push(count);
    }

    let interior_edges = cells_on_edge
        .iter()
        .skip(1)
        .filter(|edge| edge[0] != 0 && edge[1] != 0)
        .count();
    let output = output.as_ref();
    if let Some(parent) = output.parent() {
        fs::create_dir_all(parent)?;
    }
    let mut file = fs::File::create(output)?;
    writeln!(file, "{:10}{:10}", cells_on_cell.len() - 1, interior_edges)?;

    let mut cells_with_boundary_edges = 0;
    for cell_id in 1..cells_on_cell.len() {
        let expected_edges = n_edges_on_cell_usize[cell_id];
        let mut neighbors = Vec::new();
        for &neighbor in cells_on_cell[cell_id].iter().take(expected_edges) {
            if neighbor > 0 {
                neighbors.push(neighbor);
            }
        }
        for neighbor in &neighbors {
            write!(file, "{:10}", neighbor)?;
        }
        writeln!(file)?;
        if neighbors.len() < expected_edges {
            cells_with_boundary_edges += 1;
        }
    }

    Ok(MpasGraphInfoWriteReport {
        output: output.to_path_buf(),
        n_cells_written: cells_on_cell.len() - 1,
        interior_edges,
        cells_with_boundary_edges,
    })
}

/// Build the in-memory payload produced by
/// `MOD_mask_postproc.F90:MPAS_Mesh_Cal_Simple` before
/// `MPAS_Mesh_Simple_Save` writes NetCDF.
///
/// The legacy file includes a first placeholder/non-existent polygon/vertex
/// record.  This adapter preserves that record at Rust index `0`, computes
/// unit-sphere Cartesian coordinates with the same `lonlat2xyz` convention,
/// converts `ngrmw`/`m_to_w` to MPAS zero-based `cellsOnVertex`, and derives
/// `meshDensity = (min(cellwidth) / cellwidth) ** 4` using the full legacy
/// `1:num_dbx` cellwidth range.
/// Build the in-memory payload produced by `MOD_mask_postproc.F90:MPAS_Mesh_Cal`
/// before `MPAS_Mesh_Save` and `MPAS_info_Save` write side effects.
///
/// The input mesh preserves EarthMesh/Fortran indexing. The returned payload
/// keeps a placeholder row at index 0. Connectivity ids have that internal
/// placeholder removed before `write_mpas_mesh_netcdf` writes rows, so `0` stays
/// a missing/boundary marker and valid file ids start at `1`.
pub fn build_mpas_mesh_from_unstructured_fortran_indexed(
    mesh: &UnstructuredMesh,
    cellwidth: &[f64],
    nxp: usize,
    step: usize,
) -> io::Result<MpasMesh> {
    let original_cell_rows = mesh.w_points.len();
    let original_vertex_rows = mesh.m_points.len();
    let (mesh, cellwidth) = normalize_mpas_legacy_placeholder_inputs(mesh, cellwidth)?;
    let mesh = &mesh;
    let extra_cell_rows = mesh.w_points.len().saturating_sub(original_cell_rows);
    let extra_vertex_rows = mesh.m_points.len().saturating_sub(original_vertex_rows);
    let cellwidth = cellwidth.as_slice();
    validate_unstructured_mesh(mesh)?;
    if cellwidth.len() != mesh.w_points.len() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "cellwidth length {} must match w_points length {}",
                cellwidth.len(),
                mesh.w_points.len()
            ),
        ));
    }
    if nxp == 0 || step == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "nxp and step must be positive for MPAS nominalMinDc",
        ));
    }
    if cellwidth
        .iter()
        .any(|value| !value.is_finite() || *value <= 0.0)
    {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "cellwidth values must be finite and positive",
        ));
    }

    let cells_on_triangle = cells_on_triangle_fortran_indexed_from_mesh(mesh)?;
    let vertices_on_cell = triangles_on_cell_fortran_indexed_from_mesh(mesh)?;
    let n_edges_on_cell = n_edges_on_cell_usize_from_mesh(mesh)?;
    let triangle_lonlat = lonlat_degrees_from_points(&mesh.m_points);
    let cell_lonlat = lonlat_degrees_from_points(&mesh.w_points);
    let edge_output = get_edge_from_unstructured_mesh(mesh)?;

    let vertices = lonlat_points_to_unit_xyz(&triangle_lonlat);
    let cells = lonlat_points_to_unit_xyz(&cell_lonlat);
    let edge_points = lonlat_points_to_unit_xyz(&edge_output.edge_points);

    let ordered_vertices_on_cell = order_vertices_on_cell_fortran_indexed(
        &cells,
        &vertices,
        &vertices_on_cell,
        &n_edges_on_cell,
    )
    .and_then(|ordered| {
        standardize_vertices_on_cell_rotation_fortran_indexed(&ordered, &n_edges_on_cell)
    })
    .ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            "failed to order MPAS verticesOnCell from unstructured mesh",
        )
    })?;
    let mut ordered_vertices_on_cell = ordered_vertices_on_cell;
    let mut cell_connectivity = connect_on_cell_fortran_indexed(
        &n_edges_on_cell,
        &edge_output.cells_on_edge,
        &edge_output.edges_on_vertex,
        &ordered_vertices_on_cell,
    );
    if cell_connectivity.is_none() {
        if let Some(topological_order) = order_vertices_on_cell_by_shared_edges_fortran_indexed(
            &vertices_on_cell,
            &n_edges_on_cell,
            &edge_output.edges_on_vertex,
        )
        .and_then(|ordered| {
            standardize_vertices_on_cell_rotation_fortran_indexed(&ordered, &n_edges_on_cell)
        }) {
            if let Some(topological_connectivity) = connect_on_cell_fortran_indexed(
                &n_edges_on_cell,
                &edge_output.cells_on_edge,
                &edge_output.edges_on_vertex,
                &topological_order,
            ) {
                ordered_vertices_on_cell = topological_order;
                cell_connectivity = Some(topological_connectivity);
            }
        }
    }
    let cell_connectivity = cell_connectivity.ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            "failed to build MPAS cell connectivity from unstructured mesh",
        )
    })?;

    let area = get_area_production_fortran_indexed(GetAreaUnitInput {
        vertices: &vertices,
        edge_points: &edge_points,
        cell_points: &cells,
        cells_on_vertex: &cells_on_triangle,
        edges_on_vertex: &edge_output.edges_on_vertex,
        cells_on_edge: &edge_output.cells_on_edge,
        vertices_on_cell: &ordered_vertices_on_cell,
        n_edges_on_cell: &n_edges_on_cell,
    })
    .ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            "failed to compute MPAS area payload from unstructured mesh",
        )
    })?;

    let lon_edge_degrees = edge_output
        .edge_points
        .iter()
        .map(|point| point.lon_degrees)
        .collect::<Vec<_>>();
    let lat_edge_degrees = edge_output
        .edge_points
        .iter()
        .map(|point| point.lat_degrees)
        .collect::<Vec<_>>();
    let lat_vertex_degrees = triangle_lonlat
        .iter()
        .map(|point| point.lat_degrees)
        .collect::<Vec<_>>();
    let edge_metrics = edge_distance_angle_fortran_indexed(
        &vertices,
        &cells,
        &edge_points,
        &edge_output.vertices_on_edge,
        &edge_output.cells_on_edge,
        &lat_vertex_degrees,
        &lon_edge_degrees,
        &lat_edge_degrees,
    )
    .ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            "failed to compute MPAS edge distance/angle payload",
        )
    })?;

    let weights = set_weights_on_edge_fortran_indexed(
        &area.unit.area_cell,
        &edge_metrics.angle_edge,
        &edge_metrics.dc_edge,
        &edge_metrics.dv_edge,
        &area.unit.kite_areas_on_vertex,
        &cell_connectivity.edges_on_cell,
        &cells_on_triangle,
        &edge_output.cells_on_edge,
        &ordered_vertices_on_cell,
        &edge_output.vertices_on_edge,
        &n_edges_on_cell,
    )
    .ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            "failed to compute MPAS weightsOnEdge payload",
        )
    })?;

    let (x_vertex, y_vertex, z_vertex) = split_cartesian_components(&vertices);
    let (x_cell, y_cell, z_cell) = split_cartesian_components(&cells);
    let (x_edge, y_edge, z_edge) = split_cartesian_components(&edge_points);
    let (lat_cell, lon_cell) = mpas_lat_lon_radians(&cell_lonlat);
    let (lat_vertex, lon_vertex) = mpas_lat_lon_radians(&triangle_lonlat);
    let (lat_edge, lon_edge) = mpas_lat_lon_radians(&edge_output.edge_points);

    let min_cellwidth = cellwidth.iter().copied().fold(f64::INFINITY, f64::min);
    let mesh_density = cellwidth
        .iter()
        .map(|width| (min_cellwidth / width).powi(4))
        .collect::<Vec<_>>();
    let nominal_min_dc = (7680 / nxp / 2_usize.pow((step - 1) as u32)) as f64
        / earthmesh_core::EARTH_RADIUS_METERS
        * 1000.0;

    let mut mpas = MpasMesh {
        lat_cell,
        lon_cell,
        x_cell,
        y_cell,
        z_cell,
        lat_vertex,
        lon_vertex,
        x_vertex,
        y_vertex,
        z_vertex,
        lat_edge,
        lon_edge,
        x_edge,
        y_edge,
        z_edge,
        n_edges_on_cell: usize_values_to_i32("n_edges_on_cell", &n_edges_on_cell)?,
        cells_on_cell: zero_based_padded_rows(
            "cells_on_cell",
            &cell_connectivity.cells_on_cell,
            10,
        )?,
        vertices_on_cell: zero_based_padded_rows(
            "vertices_on_cell",
            &ordered_vertices_on_cell,
            10,
        )?,
        edges_on_cell: zero_based_padded_rows(
            "edges_on_cell",
            &cell_connectivity.edges_on_cell,
            10,
        )?,
        cells_on_vertex: zero_based_triplet_rows("cells_on_vertex", &edge_output.cells_on_vertex)?,
        edges_on_vertex: zero_based_triplet_rows("edges_on_vertex", &edge_output.edges_on_vertex)?,
        cells_on_edge: zero_based_pair_rows("cells_on_edge", &edge_output.cells_on_edge)?,
        vertices_on_edge: zero_based_pair_rows("vertices_on_edge", &edge_output.vertices_on_edge)?,
        n_edges_on_edge: usize_values_to_i32("n_edges_on_edge", &weights.n_edges_on_edge)?,
        edges_on_edge: zero_based_padded_rows("edges_on_edge", &weights.edges_on_edge, 20)?,
        area_cell: area.unit.area_cell,
        area_triangle: area.unit.area_triangle,
        kite_areas_on_vertex: area
            .unit
            .kite_areas_on_vertex
            .into_iter()
            .map(|row| row.to_vec())
            .collect(),
        dv_edge: edge_metrics.dv_edge,
        dc_edge: edge_metrics.dc_edge,
        angle_edge: edge_metrics.angle_edge,
        weights_on_edge: pad_f64_rows(&weights.weights_on_edge, 20),
        mesh_density,
        nominal_min_dc,
        error_segment: weights.error_segment,
    };
    trim_mpas_leading_placeholders(&mut mpas, extra_cell_rows, extra_vertex_rows);
    validate_mpas_mesh(&mpas)?;
    Ok(mpas)
}

fn trim_mpas_leading_placeholders(
    mesh: &mut MpasMesh,
    extra_cell_rows: usize,
    extra_vertex_rows: usize,
) {
    if extra_cell_rows > 0 {
        drain_prefix(&mut mesh.lat_cell, extra_cell_rows);
        drain_prefix(&mut mesh.lon_cell, extra_cell_rows);
        drain_prefix(&mut mesh.x_cell, extra_cell_rows);
        drain_prefix(&mut mesh.y_cell, extra_cell_rows);
        drain_prefix(&mut mesh.z_cell, extra_cell_rows);
        drain_prefix(&mut mesh.n_edges_on_cell, extra_cell_rows);
        drain_prefix(&mut mesh.cells_on_cell, extra_cell_rows);
        drain_prefix(&mut mesh.vertices_on_cell, extra_cell_rows);
        drain_prefix(&mut mesh.edges_on_cell, extra_cell_rows);
        drain_prefix(&mut mesh.area_cell, extra_cell_rows);
        drain_prefix(&mut mesh.mesh_density, extra_cell_rows);
    }
    if extra_vertex_rows > 0 {
        drain_prefix(&mut mesh.lat_vertex, extra_vertex_rows);
        drain_prefix(&mut mesh.lon_vertex, extra_vertex_rows);
        drain_prefix(&mut mesh.x_vertex, extra_vertex_rows);
        drain_prefix(&mut mesh.y_vertex, extra_vertex_rows);
        drain_prefix(&mut mesh.z_vertex, extra_vertex_rows);
        drain_prefix(&mut mesh.cells_on_vertex, extra_vertex_rows);
        drain_prefix(&mut mesh.edges_on_vertex, extra_vertex_rows);
        drain_prefix(&mut mesh.area_triangle, extra_vertex_rows);
        drain_prefix(&mut mesh.kite_areas_on_vertex, extra_vertex_rows);
    }
    let extra_edge_rows = extra_cell_rows.max(extra_vertex_rows);
    if extra_edge_rows > 0 {
        drain_prefix(&mut mesh.lat_edge, extra_edge_rows);
        drain_prefix(&mut mesh.lon_edge, extra_edge_rows);
        drain_prefix(&mut mesh.x_edge, extra_edge_rows);
        drain_prefix(&mut mesh.y_edge, extra_edge_rows);
        drain_prefix(&mut mesh.z_edge, extra_edge_rows);
        drain_prefix(&mut mesh.cells_on_edge, extra_edge_rows);
        drain_prefix(&mut mesh.vertices_on_edge, extra_edge_rows);
        drain_prefix(&mut mesh.n_edges_on_edge, extra_edge_rows);
        drain_prefix(&mut mesh.edges_on_edge, extra_edge_rows);
        drain_prefix(&mut mesh.dv_edge, extra_edge_rows);
        drain_prefix(&mut mesh.dc_edge, extra_edge_rows);
        drain_prefix(&mut mesh.angle_edge, extra_edge_rows);
        drain_prefix(&mut mesh.weights_on_edge, extra_edge_rows);
        drain_prefix(&mut mesh.error_segment, extra_edge_rows);
    }
}

fn drain_prefix<T>(values: &mut Vec<T>, count: usize) {
    values.drain(0..count);
}

pub fn build_mpas_simple_mesh_from_unstructured_fortran_indexed(
    mesh: &UnstructuredMesh,
    cellwidth: &[f64],
) -> io::Result<MpasSimpleMesh> {
    let (mesh, cellwidth) = normalize_mpas_legacy_placeholder_inputs(mesh, cellwidth)?;
    let mesh = &mesh;
    let cellwidth = cellwidth.as_slice();
    validate_unstructured_mesh(mesh)?;
    if cellwidth.len() != mesh.w_points.len() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "cellwidth length {} must match w_points length {}",
                cellwidth.len(),
                mesh.w_points.len()
            ),
        ));
    }
    if cellwidth.is_empty() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "cellwidth must include the legacy placeholder row",
        ));
    }
    if cellwidth
        .iter()
        .any(|value| !value.is_finite() || *value <= 0.0)
    {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "cellwidth values must be finite and positive",
        ));
    }

    let vertex_xyz = lonlat_points_to_unit_xyz(&lonlat_degrees_from_points(&mesh.m_points));
    let cell_xyz = lonlat_points_to_unit_xyz(&lonlat_degrees_from_points(&mesh.w_points));
    let (x_vertex, y_vertex, z_vertex) = split_cartesian_components(&vertex_xyz);
    let (x_cell, y_cell, z_cell) = split_cartesian_components(&cell_xyz);

    let cells_on_vertex = mesh
        .m_to_w
        .iter()
        .enumerate()
        .map(|(row_idx, row)| {
            row.iter()
                .map(|&value| {
                    value.checked_sub(1).ok_or_else(|| {
                        io::Error::new(
                            io::ErrorKind::InvalidInput,
                            format!("m_to_w row {row_idx} contains non-positive cell id {value}"),
                        )
                    })
                })
                .collect::<io::Result<Vec<i32>>>()
        })
        .collect::<io::Result<Vec<Vec<i32>>>>()?;

    let min_cellwidth = cellwidth.iter().copied().fold(f64::INFINITY, f64::min);
    let mesh_density = cellwidth
        .iter()
        .map(|width| (min_cellwidth / width).powi(4))
        .collect();

    let simple = MpasSimpleMesh {
        x_cell,
        y_cell,
        z_cell,
        x_vertex,
        y_vertex,
        z_vertex,
        cells_on_vertex,
        mesh_density,
    };
    validate_mpas_simple_mesh(&simple)?;
    Ok(simple)
}

fn normalize_mpas_legacy_placeholder_inputs(
    mesh: &UnstructuredMesh,
    cellwidth: &[f64],
) -> io::Result<(UnstructuredMesh, Vec<f64>)> {
    if cellwidth.len() != mesh.w_points.len() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "cellwidth length {} must match w_points length {}",
                cellwidth.len(),
                mesh.w_points.len()
            ),
        ));
    }

    let normalized = normalize_unstructured_mesh_legacy_placeholders(mesh)?;
    let mut normalized_cellwidth = cellwidth.to_vec();
    if normalized.w_points.len() > cellwidth.len() {
        let missing_placeholders = normalized.w_points.len() - cellwidth.len();
        let placeholder_cellwidth = normalized_cellwidth.first().copied().unwrap_or(1.0);
        for _ in 0..missing_placeholders {
            normalized_cellwidth.insert(0, placeholder_cellwidth);
        }
    }
    if normalized_cellwidth.len() != normalized.w_points.len() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "cellwidth length {} must match normalized w_points length {}",
                normalized_cellwidth.len(),
                normalized.w_points.len()
            ),
        ));
    }

    Ok((normalized, normalized_cellwidth))
}

fn normalize_unstructured_mesh_legacy_placeholders(
    mesh: &UnstructuredMesh,
) -> io::Result<UnstructuredMesh> {
    validate_unstructured_mesh(mesh)?;
    let max_cell_id = mesh
        .m_to_w
        .iter()
        .flat_map(|row| row.iter().copied())
        .filter_map(|value| usize::try_from(value).ok())
        .max()
        .unwrap_or(0);
    let max_triangle_id = mesh
        .w_to_m
        .iter()
        .flat_map(|row| row.iter().copied())
        .filter_map(|value| usize::try_from(value).ok())
        .max()
        .unwrap_or(0);
    let missing_cell_placeholder = max_cell_id >= mesh.w_points.len();
    let missing_triangle_placeholder = max_triangle_id >= mesh.m_points.len();

    if !missing_cell_placeholder && !missing_triangle_placeholder {
        return Ok(mesh.clone());
    }

    let mut normalized = mesh.clone();
    let placeholder = LonLatPoint { lon: 0.0, lat: 0.0 };
    if has_single_legacy_placeholder_row(mesh) {
        if missing_triangle_placeholder {
            normalized.m_points.insert(0, placeholder);
            normalized.m_to_w.insert(0, [1, 1, 1]);
        }
        if missing_cell_placeholder {
            normalized.w_points.insert(0, placeholder);
            normalized.w_to_m.insert(0, vec![1]);
            normalized.n_w_to_m.insert(0, 1);
        }
        return Ok(normalized);
    }

    if missing_triangle_placeholder {
        for row in &mut normalized.w_to_m {
            for value in row {
                if *value > 0 {
                    *value = value.checked_add(1).ok_or_else(|| {
                        io::Error::new(
                            io::ErrorKind::InvalidInput,
                            "triangle id overflow while inserting legacy placeholder rows",
                        )
                    })?;
                }
            }
        }
    }
    if missing_cell_placeholder {
        for row in &mut normalized.m_to_w {
            for value in row {
                if *value > 0 {
                    *value = value.checked_add(1).ok_or_else(|| {
                        io::Error::new(
                            io::ErrorKind::InvalidInput,
                            "cell id overflow while inserting legacy placeholder rows",
                        )
                    })?;
                }
            }
        }
    }
    if missing_triangle_placeholder {
        normalized.m_points.splice(0..0, [placeholder, placeholder]);
        normalized.m_to_w.splice(0..0, [[1, 1, 1], [1, 1, 1]]);
    }
    if missing_cell_placeholder {
        normalized.w_points.splice(0..0, [placeholder, placeholder]);
        normalized.w_to_m.splice(0..0, [vec![1], vec![1]]);
        normalized.n_w_to_m.splice(0..0, [1, 1]);
    }
    Ok(normalized)
}

fn restore_unstructured_mesh_shape(
    original: &UnstructuredMesh,
    adjusted: &UnstructuredMesh,
) -> io::Result<UnstructuredMesh> {
    if adjusted.m_points.len() < original.m_points.len()
        || adjusted.w_points.len() < original.w_points.len()
        || adjusted.m_to_w.len() < original.m_to_w.len()
        || adjusted.w_to_m.len() < original.w_to_m.len()
        || adjusted.n_w_to_m.len() < original.n_w_to_m.len()
    {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "adjusted mesh is smaller than original mesh shape",
        ));
    }

    let triangle_offset = adjusted.m_points.len() - original.m_points.len();
    let cell_offset = adjusted.w_points.len() - original.w_points.len();
    let mut restored = UnstructuredMesh {
        m_points: adjusted.m_points[triangle_offset..].to_vec(),
        w_points: adjusted.w_points[cell_offset..].to_vec(),
        m_to_w: adjusted.m_to_w[triangle_offset..].to_vec(),
        w_to_m: adjusted.w_to_m[cell_offset..].to_vec(),
        n_w_to_m: adjusted.n_w_to_m[cell_offset..].to_vec(),
    };

    if triangle_offset > 0 {
        let subtract = infer_connectivity_delta(
            restored.w_to_m.iter().flat_map(|row| row.iter().copied()),
            original.w_to_m.iter().flat_map(|row| row.iter().copied()),
        )
        .unwrap_or(0);
        if subtract > 0 {
            for row in &mut restored.w_to_m {
                for value in row {
                    if *value > 0 {
                        *value -= subtract;
                    }
                }
            }
        }
    }
    if cell_offset > 0 {
        let subtract = infer_connectivity_delta(
            restored.m_to_w.iter().flat_map(|row| row.iter().copied()),
            original.m_to_w.iter().flat_map(|row| row.iter().copied()),
        )
        .unwrap_or(0);
        if subtract > 0 {
            for row in &mut restored.m_to_w {
                for value in row {
                    if *value > 0 {
                        *value -= subtract;
                    }
                }
            }
        }
    }

    validate_unstructured_mesh(&restored)?;
    Ok(restored)
}

fn infer_connectivity_delta(
    restored: impl Iterator<Item = i32>,
    original: impl Iterator<Item = i32>,
) -> Option<i32> {
    let mut delta = None;
    for (restored_id, original_id) in restored.zip(original) {
        if restored_id <= 0 || original_id <= 0 {
            continue;
        }
        let current = restored_id.checked_sub(original_id)?;
        if current < 0 {
            return None;
        }
        match delta {
            Some(existing) if existing != current => return None,
            Some(_) => {}
            None => delta = Some(current),
        }
    }
    delta
}

fn has_single_legacy_placeholder_row(mesh: &UnstructuredMesh) -> bool {
    mesh.m_to_w
        .first()
        .is_some_and(|row| row.iter().all(|value| *value == 1))
        && mesh
            .w_to_m
            .first()
            .is_some_and(|row| !row.is_empty() && row.iter().all(|value| *value == 1))
        && mesh
            .n_w_to_m
            .first()
            .is_some_and(|value| matches!(*value, 0 | 1))
}

/// File-level replacement for the `MPAS_Mesh_Cal_Simple` path that reads the
/// EarthMesh gridfile plus `cellwidth_NXP####_global.nc4`, builds the simple
/// MPAS payload, and writes `MPASOUT_NXP####_global_Simple.nc4`-compatible
/// NetCDF.
pub fn write_mpas_simple_mesh_from_netcdf_inputs(
    gridfile: impl AsRef<Path>,
    cellwidth_file: impl AsRef<Path>,
    output: impl AsRef<Path>,
) -> io::Result<MpasSimpleMeshWriteReport> {
    let mesh = read_unstructured_mesh_netcdf(gridfile)?;
    let cellwidth = read_cellwidth_netcdf(cellwidth_file)?;
    let simple = build_mpas_simple_mesh_from_unstructured_fortran_indexed(&mesh, &cellwidth)?;
    write_mpas_simple_mesh_netcdf(output, &simple)
}

/// File-level replacement for the full `MPAS_Mesh_Cal` path that reads the
/// EarthMesh gridfile plus `cellwidth_NXP####_global.nc4`, builds the full MPAS
/// payload, and writes both `MPASOUT_NXP####_global.nc4` and graph.info.
pub fn write_mpas_mesh_from_netcdf_inputs(
    gridfile: impl AsRef<Path>,
    cellwidth_file: impl AsRef<Path>,
    mesh_output: impl AsRef<Path>,
    graph_output: impl AsRef<Path>,
    nxp: usize,
    step: usize,
) -> io::Result<MpasFullMeshPipelineReport> {
    let mesh = read_unstructured_mesh_netcdf(gridfile)?;
    let cellwidth = read_cellwidth_netcdf(cellwidth_file)?;
    let mpas = build_mpas_mesh_from_unstructured_fortran_indexed(&mesh, &cellwidth, nxp, step)?;
    let mesh_report = write_mpas_mesh_netcdf(mesh_output, &mpas)?;
    let graph_info = write_mpas_graph_info(
        graph_output,
        10,
        &mpas.cells_on_cell,
        &mpas.cells_on_edge,
        &mpas.n_edges_on_cell,
    )?;
    Ok(MpasFullMeshPipelineReport {
        mesh: mesh_report,
        graph_info,
    })
}

/// Build a standard MPAS mesh NetCDF (+ `graph.info`) straight from a base
/// `gridfile`, without the spring/refine pipeline or a cellwidth file. A uniform
/// cellwidth is synthesized: for an unrefined mesh every cell has the same width,
/// so `meshDensity ≡ 1`, which is exactly correct. Reuses the same validated
/// builder/writer as the full pipeline, so the output is the standard MPAS schema.
pub fn write_standard_mpas_from_gridfile(
    gridfile: impl AsRef<Path>,
    mesh_output: impl AsRef<Path>,
    graph_output: impl AsRef<Path>,
    nxp: usize,
) -> io::Result<MpasFullMeshPipelineReport> {
    let mesh = read_unstructured_mesh_netcdf(gridfile)?;
    let base_width = if nxp > 0 { 7680.0 / nxp as f64 } else { 1.0 };
    let cellwidth = vec![base_width; mesh.w_points.len()];
    let mpas = build_mpas_mesh_from_unstructured_fortran_indexed(&mesh, &cellwidth, nxp, 1)?;
    let mesh_report = write_mpas_mesh_netcdf(mesh_output, &mpas)?;
    let graph_info = write_mpas_graph_info(
        graph_output,
        10,
        &mpas.cells_on_cell,
        &mpas.cells_on_edge,
        &mpas.n_edges_on_cell,
    )?;
    Ok(MpasFullMeshPipelineReport {
        mesh: mesh_report,
        graph_info,
    })
}

/// Write a regional (limited-area) MPAS mesh + graph.info from a global hex
/// gridfile, keeping only the cells whose centre falls inside `region`.
///
/// Builds the full global MPAS mesh (the validated path), then [`subset_mpas_mesh`]
/// re-indexes it to the region: every kept cell is geometrically complete and its
/// geometry is preserved exactly, while connectivity to dropped cells collapses to
/// the MPAS `0` no-neighbour marker (boundary cells/edges). Returns the report and
/// the number of cells kept.
pub fn write_regional_mpas_from_gridfile(
    gridfile: impl AsRef<Path>,
    mesh_output: impl AsRef<Path>,
    graph_output: impl AsRef<Path>,
    region: &GridRegion,
    nxp: usize,
) -> io::Result<(MpasFullMeshPipelineReport, usize)> {
    let mesh = read_unstructured_mesh_netcdf(gridfile)?;
    let base_width = if nxp > 0 { 7680.0 / nxp as f64 } else { 1.0 };
    let cellwidth = vec![base_width; mesh.w_points.len()];
    let global = build_mpas_mesh_from_unstructured_fortran_indexed(&mesh, &cellwidth, nxp, 1)?;

    // MpasMesh stores lon/lat in radians (lon in 0..2π); GridRegion wants degrees.
    let n_cells = global.lat_cell.len();
    let mut keep_cell = vec![false; n_cells];
    let mut kept = 0usize;
    for c in 1..n_cells {
        let lon_deg = global.lon_cell[c].to_degrees();
        let lat_deg = global.lat_cell[c].to_degrees();
        if region.contains(lon_deg, lat_deg) {
            keep_cell[c] = true;
            kept += 1;
        }
    }
    if kept == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "region contains no cells",
        ));
    }

    let regional = subset_mpas_mesh(&global, &keep_cell)?;
    let mesh_report = write_mpas_mesh_netcdf(mesh_output, &regional)?;
    let graph_info = write_mpas_graph_info(
        graph_output,
        10,
        &regional.cells_on_cell,
        &regional.cells_on_edge,
        &regional.n_edges_on_cell,
    )?;
    Ok((
        MpasFullMeshPipelineReport {
            mesh: mesh_report,
            graph_info,
        },
        kept,
    ))
}

/// Carve a CLEAN regional ocean (FVCOM) mesh from a global gridfile + a close
/// polygon + a landtype NetCDF — in pure Rust, WITHOUT the refine pipeline and
/// WITHOUT reading any criterion data (LAI/slope/…). It reuses the engine's
/// Area_judge → Get_Contain → ocean `mask_postproc` chain (the same clean tri
/// boundary peeling the production path uses), so the result has a proper 0/2
/// boundary that the FVCOM writer accepts. Reads only: the gridfile, the close
/// polygon, and the landtype file. Writes intermediates under `work_dir`.
pub fn write_clean_regional_ocean_fvcom(
    global_gridfile: &Path,
    close_points: &[LonLatPoint],
    landtype_file: &Path,
    nxp: usize,
    gridnum_perdegree: usize,
    mask_sea_ratio: f64,
    work_dir: &Path,
    output_2dm: &Path,
) -> io::Result<usize> {
    // Source axes + landtype (read landtype once).
    let pre = read_landtype_data_preprocess_fortran_indexed(landtype_file, gridnum_perdegree)?;

    // Write the close polygon where the domain builder looks for it.
    let close_path = work_dir.join("tmpfile").join("mask_domain_close_0_001.nc4");
    if let Some(p) = close_path.parent() {
        fs::create_dir_all(p)?;
    }
    write_close_mask_netcdf(
        &close_path,
        &CloseMask {
            refine_degree: 0,
            points: close_points.to_vec(),
        },
    )?;

    // Domain membership (is_in_domain) from the close curve — geometric, no data.
    let domain = build_area_judge_domain_fortran_indexed(
        work_dir,
        false,
        "close",
        1,
        &pre.lon_vertex,
        &pre.lat_vertex,
        &pre.lon_i,
        &pre.lat_i,
        gridnum_perdegree,
        pre.nlons_source,
        pre.nlats_source,
    )?;
    let bounds = domain.bounds;

    // Sea/land classification from the already-read landtype grid.
    let sol = build_area_judge_seaorland_fortran_indexed(
        &domain.is_in_domain,
        &pre.landtypes_global,
        bounds,
        "oceanmesh",
        false,
    )?;

    // Fixed I/O layout under work_dir; the global gridfile must sit at source.
    let plan = plan_mask_postproc_domain_io(work_dir, nxp, "tri", "oceanmesh", false)?;
    if let Some(p) = plan.source_gridfile.parent() {
        fs::create_dir_all(p)?;
    }
    fs::copy(global_gridfile, &plan.source_gridfile)?;

    // Area_judge payload → Get_Contain (Ocean) → contain file the carve reads.
    let payload = select_area_judge_grid_fortran_indexed(
        &domain.is_in_domain,
        None,
        &pre.lon_i,
        &pre.lat_i,
        bounds,
    )?;
    let area_grid_file = work_dir.join("tmpfile").join("area_judge_domain.nc4");
    write_area_judge_grid_netcdf(&area_grid_file, &payload)?;
    run_getcontain_refine_file_fortran_indexed(GetContainRefineFileRunConfig {
        gridfile: &plan.source_gridfile,
        area_grid_file: &area_grid_file,
        output: &plan.contain_domain,
        mesh_kind: GetContainMeshKind::Ocean,
        seaorland: &sol.seaorland,
        lon_vertex: &pre.lon_vertex,
        lat_vertex: &pre.lat_vertex,
        lon_i: &pre.lon_i,
        lat_i: &pre.lat_i,
        num_vertex: 0,
    })?;

    // Clean ocean carve (tri boundary peel + carved gridfile + OBC).
    run_mask_postproc_ocean_domain(
        &plan,
        MaskPostprocOceanRunOptions {
            mask_sea_ratio,
            num_vertex: 0,
        },
    )?;

    // Carved mesh → FVCOM .2dm. The mask_postproc output uses a 2-placeholder +
    // (0,0) boundary-marker convention the generic writer doesn't expect, so emit
    // the .2dm over real cells/nodes only, renumbered 1-based, plus the open
    // boundary from the carve's OBC file.
    let carved = read_unstructured_mesh_netcdf(&plan.result_gridfile)?;
    let obc_order = match &plan.obc_output {
        Some(p) if p.exists() => read_obc_order_netcdf(p)?,
        _ => Vec::new(),
    };
    write_fvcom_2dm_from_carved(&carved, &obc_order, output_2dm)
}

/// Write an SMS/FVCOM `.2dm` from a carved (`mask_postproc`) ocean mesh, which
/// uses two leading placeholder rows and a `(0,0)` boundary marker. Real nodes
/// are renumbered 1-based; triangles touching a placeholder/marker are dropped;
/// the open boundary (`obc_order`, in carved-id space) is re-mapped and written
/// as NS records so the `.2dm` carries its open-boundary specification.
fn write_fvcom_2dm_from_carved(
    mesh: &UnstructuredMesh,
    obc_order: &[usize],
    output: &Path,
) -> io::Result<usize> {
    if let Some(parent) = output.parent() {
        fs::create_dir_all(parent)?;
    }
    let is_marker = |p: &LonLatPoint| p.lon == 0.0 && p.lat == 0.0;
    // carved 1-based vertex id → new 1-based node id (real nodes only).
    let mut new_id = vec![0usize; mesh.w_points.len() + 2];
    let mut nodes: Vec<(usize, LonLatPoint)> = Vec::new();
    let mut next = 1usize;
    for (idx, p) in mesh.w_points.iter().enumerate() {
        if idx == 0 || is_marker(p) {
            continue;
        }
        new_id[idx + 1] = next; // Fortran id = idx + 1
        nodes.push((next, *p));
        next += 1;
    }
    let mut file = fs::File::create(output)?;
    writeln!(file, "MESH2D")?;
    writeln!(file, "MESHNAME \"FVCOM Mesh\"")?;
    let mut elements = 0usize;
    for tri in mesh.m_to_w.iter().skip(1) {
        let ids = [tri[0], tri[1], tri[2]];
        if ids
            .iter()
            .any(|&v| v < 1 || (v as usize) >= new_id.len() || new_id[v as usize] == 0)
        {
            continue; // touches a placeholder / boundary marker
        }
        elements += 1;
        writeln!(
            file,
            "E3T {} {} {} {} 1",
            elements, new_id[ids[0] as usize], new_id[ids[1] as usize], new_id[ids[2] as usize]
        )?;
    }
    for (id, p) in &nodes {
        writeln!(file, "ND {} {:.6} {:.6} {:.6}", id, p.lon, p.lat, 0.0)?;
    }
    // Open boundary: re-map carved ids to new node ids. `write_fvcom_ns_records`
    // emits `id - 1`, so pass `new_id + 1`; 1 stays the segment separator, and a
    // marker (no real node) also acts as a separator.
    if !obc_order.is_empty() {
        let remapped: Vec<usize> = obc_order
            .iter()
            .map(|&id| {
                if id == 1 || id >= new_id.len() || new_id[id] == 0 {
                    1
                } else {
                    new_id[id] + 1
                }
            })
            .collect();
        write_fvcom_ns_records(&mut file, &remapped)?;
    }
    Ok(elements)
}

/// Write the standard FVCOM `.2dm` mesh straight from a base gridfile, in pure
/// Rust. Open-boundary segments are omitted (none for a from-scratch mesh).
pub fn write_standard_fvcom_from_gridfile(
    gridfile: impl AsRef<Path>,
    output_2dm: impl AsRef<Path>,
) -> io::Result<FvcomMesh2dmWriteReport> {
    let mesh = read_unstructured_mesh_netcdf(gridfile)?;
    write_fvcom_mesh_2dm(output_2dm, &mesh, &[])
}

/// A geographic region used to carve a gridfile down to an area of interest.
#[derive(Debug, Clone)]
pub enum GridRegion {
    Bbox {
        west: f64,
        east: f64,
        north: f64,
        south: f64,
    },
    Circle {
        lon: f64,
        lat: f64,
        radius_km: f64,
    },
    Close {
        points: Vec<LonLatPoint>,
    },
    Any(Vec<GridRegion>),
}

impl GridRegion {
    fn contains(&self, lon: f64, lat: f64) -> bool {
        let norm = |x: f64| ((x + 180.0).rem_euclid(360.0)) - 180.0;
        match self {
            GridRegion::Bbox {
                west,
                east,
                north,
                south,
            } => {
                let (s, n) = ((*south).min(*north), (*south).max(*north));
                let (w, e) = (norm(*west), norm(*east));
                let lon = norm(lon);
                lat >= s && lat <= n && lon >= w.min(e) && lon <= w.max(e)
            }
            GridRegion::Circle {
                lon: clon,
                lat: clat,
                radius_km,
            } => {
                let r = 6371.0_f64;
                let (la1, la2) = (clat.to_radians(), lat.to_radians());
                let dlat = (lat - *clat).to_radians();
                let dlon = (norm(lon) - norm(*clon)).to_radians();
                let a =
                    (dlat / 2.0).sin().powi(2) + la1.cos() * la2.cos() * (dlon / 2.0).sin().powi(2);
                2.0 * r * a.sqrt().asin() <= *radius_km
            }
            GridRegion::Close { points } => point_in_close_region(points, lon, lat),
            GridRegion::Any(regions) => regions.iter().any(|region| region.contains(lon, lat)),
        }
    }
}

fn point_in_close_region(points: &[LonLatPoint], lon: f64, lat: f64) -> bool {
    if points.len() < 3 || !lon.is_finite() || !lat.is_finite() {
        return false;
    }
    let norm = |x: f64| ((x + 180.0).rem_euclid(360.0)) - 180.0;
    let lon0 = norm(lon);
    let unwrap = |x: f64| {
        let mut y = norm(x);
        if y - lon0 > 180.0 {
            y -= 360.0;
        } else if y - lon0 < -180.0 {
            y += 360.0;
        }
        y
    };
    let mut inside = false;
    let eps = 1.0e-12;
    for i in 0..points.len() {
        let a = points[i];
        let b = points[(i + 1) % points.len()];
        if !a.lon.is_finite() || !a.lat.is_finite() || !b.lon.is_finite() || !b.lat.is_finite() {
            return false;
        }
        let ax = unwrap(a.lon);
        let bx = unwrap(b.lon);
        let ay = a.lat;
        let by = b.lat;
        let cross = (lon0 - ax) * (by - ay) - (lat - ay) * (bx - ax);
        let on_segment = cross.abs() <= eps
            && lon0 >= ax.min(bx) - eps
            && lon0 <= ax.max(bx) + eps
            && lat >= ay.min(by) - eps
            && lat <= ay.max(by) + eps;
        if on_segment {
            return true;
        }
        if (ay > lat) != (by > lat) {
            let x_at_lat = ax + (lat - ay) * (bx - ax) / (by - ay);
            if lon0 < x_at_lat {
                inside = !inside;
            }
        }
    }
    inside
}

/// Carve a global gridfile down to `region` and write the regional gridfile, in
/// pure Rust. Reuses the engine's mask-postproc compaction/re-index: cells whose
/// centre is outside the region are dropped and the mesh is renumbered. The
/// gridfile's leading placeholder (Fortran id 1 / array index 0) is preserved.
/// Returns the number of cells kept. `mode_grid` selects the primal cells
/// (`hex` → hexagons / W cells, `tri` → triangles / M cells).
pub fn write_regional_gridfile(
    global_gridfile: impl AsRef<Path>,
    regional_gridfile: impl AsRef<Path>,
    region: &GridRegion,
    mode_grid: &str,
) -> io::Result<usize> {
    let mesh = read_unstructured_mesh_netcdf(global_gridfile)?;
    let raw_layout = mask_postproc_layout_from_unstructured_mesh(&mesh, mode_grid)?;
    let layout = ensure_leading_mask_postproc_placeholder(raw_layout);
    let mut is_in_domain = vec![-1i32; layout.ustr_points];
    let mut kept = 0usize;
    // Indices 0 and 1 are reserved placeholder points in the Fortran-indexed
    // mask-postproc layout.
    if !is_in_domain.is_empty() {
        is_in_domain[0] = 0;
    }
    if is_in_domain.len() > 1 {
        is_in_domain[1] = 0;
    }
    for i in 2..layout.ustr_points {
        let c = layout.center_points[i];
        if region.contains(c.lon, c.lat) {
            is_in_domain[i] = 1;
            kept += 1;
        }
    }
    let report =
        finalize_mask_postproc_layout_with_reindex_report(&layout, &is_in_domain, mode_grid)?;
    write_unstructured_mesh_netcdf(regional_gridfile, &report.mesh)?;
    Ok(kept)
}

/// Carve a gridfile to land-only or ocean-only cells from a land-type NetCDF.
///
/// This is the direct, post-run counterpart of the data_preprocess/Area_judge
/// sea-land classification: sample each grid cell centre against `landtype_file`,
/// keep land cells for `landmesh`, keep ocean cells for `oceanmesh`, then use the
/// existing mask-postproc finalization path so connectivity is compacted and
/// renumbered consistently. Returns the number of cells kept.
pub fn write_landtype_masked_gridfile(
    input_gridfile: impl AsRef<Path>,
    output_gridfile: impl AsRef<Path>,
    landtype_file: impl AsRef<Path>,
    gridnum_perdegree: usize,
    mode_grid: &str,
    mesh_type: &str,
) -> io::Result<usize> {
    let keep_land = match mesh_type.trim() {
        "landmesh" => true,
        "oceanmesh" => false,
        other => {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("landtype masked gridfile supports landmesh or oceanmesh, got {other}"),
            ))
        }
    };
    let mesh = read_unstructured_mesh_netcdf(input_gridfile)?;
    let raw_layout = mask_postproc_layout_from_unstructured_mesh(&mesh, mode_grid)?;
    let layout = ensure_leading_mask_postproc_placeholder(raw_layout);
    let landtype_values = sample_landtype_values_for_points_fortran_indexed(
        landtype_file,
        gridnum_perdegree,
        &layout.center_points[2..],
    )?;

    let mut is_in_domain = vec![-1i32; layout.ustr_points];
    let mut kept = 0usize;
    if !is_in_domain.is_empty() {
        is_in_domain[0] = 0;
    }
    if is_in_domain.len() > 1 {
        is_in_domain[1] = 0;
    }
    for (i, landtype_value) in (2..layout.ustr_points).zip(landtype_values) {
        let is_land = matches!(
            classify_area_judge_landtype_fortran_indexed(landtype_value),
            AreaJudgeLandtypeClass::Land
        );
        if is_land == keep_land {
            is_in_domain[i] = 1;
            kept += 1;
        }
    }
    if kept == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("{mesh_type} landtype mask kept no cells"),
        ));
    }
    let report =
        finalize_mask_postproc_layout_with_reindex_report(&layout, &is_in_domain, mode_grid)?;
    write_unstructured_mesh_netcdf(output_gridfile, &report.mesh)?;
    Ok(kept)
}

/// Rust entry point for the `mask_postproc_Atmos` branch when
/// `output_format == 'MPAS-Simple'`.
///
/// This preserves the legacy result-file names used by
/// `MPAS_Mesh_Cal_Simple`:
/// `result/gridfile_NXP####_<mode_grid>.nc4`,
/// `result/cellwidth_NXP####_global.nc4`, and
/// `result/MPASOUT_NXP####_global_Simple.nc4`.
pub fn write_mask_postproc_atmos_mpas_simple_netcdf(
    file_dir: impl AsRef<Path>,
    nxp: usize,
    mode_grid: &str,
    mesh_type: &str,
    output_format: &str,
) -> io::Result<MpasSimpleMeshWriteReport> {
    if !matches!(mesh_type.trim(), "atmos" | "atmosmesh") {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "MPAS-Simple mask_postproc writer requires mesh_type atmosmesh",
        ));
    }
    if output_format.trim() != "MPAS-Simple" {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "MPAS-Simple mask_postproc writer requires output_format MPAS-Simple",
        ));
    }
    let mode_grid = mode_grid.trim();
    if !matches!(mode_grid, "tri" | "hex") {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "MPAS-Simple mask_postproc writer supports tri or hex mode_grid only",
        ));
    }

    let file_dir = file_dir.as_ref();
    let nxpc = format!("{nxp:04}");
    let gridfile = file_dir
        .join("result")
        .join(format!("gridfile_NXP{nxpc}_{mode_grid}.nc4"));
    let cellwidth = file_dir
        .join("result")
        .join(format!("cellwidth_NXP{nxpc}_global.nc4"));
    let output = file_dir
        .join("result")
        .join(format!("MPASOUT_NXP{nxpc}_global_Simple.nc4"));

    write_mpas_simple_mesh_from_netcdf_inputs(gridfile, cellwidth, output)
}

/// Rust entry point for the `mask_postproc_Atmos` branch when
/// `output_format == 'MPAS'`.
///
/// This preserves the legacy result-file names used by `MPAS_Mesh_Cal`:
/// `result/gridfile_NXP####_<mode_grid>.nc4`,
