/// Load the two NetCDF inputs common to `mask_postproc_Earth`,
/// `mask_postproc_Lnd`, and `mask_postproc_Ocn`: the source unstructured
/// gridfile and the contain-domain mask table.
pub fn read_mask_postproc_domain_inputs(
    plan: &MaskPostprocDomainIoPlan,
) -> io::Result<MaskPostprocDomainInputs> {
    let source_mesh = read_unstructured_mesh_netcdf(&plan.source_gridfile)?;
    let contain = read_contain_netcdf(&plan.contain_domain)?;
    let layout = normalize_mask_postproc_layout_for_contain_domain(
        mask_postproc_layout_from_unstructured_mesh(&source_mesh, &plan.mode_grid)?,
        contain.is_in_area_ustr.len(),
    );
    let is_in_domain_ustr = contain.is_in_area_ustr.clone();

    Ok(MaskPostprocDomainInputs {
        layout,
        contain,
        is_in_domain_ustr,
    })
}

fn normalize_mask_postproc_layout_for_contain_domain(
    layout: MaskPostprocLayout,
    contain_ustr_len: usize,
) -> MaskPostprocLayout {
    let max_vertex_id = layout
        .center_neighbors
        .iter()
        .zip(layout.center_neighbor_counts.iter())
        .flat_map(|(row, &count)| row.iter().take(count).copied())
        .max()
        .unwrap_or(0);
    if contain_ustr_len <= layout.ustr_points || max_vertex_id < layout.ustr_bounds {
        return layout;
    }

    add_leading_mask_postproc_placeholder(layout)
}

fn ensure_leading_mask_postproc_placeholder(layout: MaskPostprocLayout) -> MaskPostprocLayout {
    if has_leading_mask_postproc_placeholder(&layout) {
        layout
    } else {
        add_leading_mask_postproc_placeholder(layout)
    }
}

fn has_leading_mask_postproc_placeholder(layout: &MaskPostprocLayout) -> bool {
    let is_zero_point = |point: &LonLatPoint| point.lon == 0.0 && point.lat == 0.0;
    layout.center_points.len() > 1
        && layout.vertex_points.len() > 1
        && is_zero_point(&layout.center_points[0])
        && is_zero_point(&layout.center_points[1])
        && is_zero_point(&layout.vertex_points[0])
        && is_zero_point(&layout.vertex_points[1])
        && layout
            .center_neighbor_counts
            .get(0..=1)
            .is_some_and(|counts| counts.iter().all(|&count| count == 0))
}

fn add_leading_mask_postproc_placeholder(mut layout: MaskPostprocLayout) -> MaskPostprocLayout {
    layout.ustr_points += 1;
    layout.ustr_bounds += 1;
    layout
        .center_points
        .insert(0, LonLatPoint { lon: 0.0, lat: 0.0 });
    layout
        .vertex_points
        .insert(0, LonLatPoint { lon: 0.0, lat: 0.0 });
    let center_width = layout
        .center_neighbors
        .first()
        .map(|row| row.len())
        .unwrap_or(0);
    let vertex_width = layout
        .vertex_neighbors
        .first()
        .map(|row| row.len())
        .unwrap_or(0);
    layout.center_neighbors.insert(0, vec![1; center_width]);
    layout.vertex_neighbors.insert(0, vec![1; vertex_width]);
    layout.center_neighbor_counts.insert(0, 0);
    layout.vertex_neighbor_counts.insert(0, 0);
    layout
}

/// File-backed composition of the migrated
/// `MOD_mask_postproc.F90:mask_postproc_Earth` branch.
///
/// This runner intentionally composes already-migrated pure/data helpers:
/// contain-domain reading, Earth land/sea patchtype classification, `PatchID`
/// output, final clipped gridfile writing, and `earthmesh_info.nc4` output.
pub fn run_mask_postproc_earth_domain(
    plan: &MaskPostprocDomainIoPlan,
    options: MaskPostprocEarthRunOptions<'_>,
) -> io::Result<MaskPostprocEarthDomainReport> {
    if plan.mesh_type != "earthmesh" {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "earth mask_postproc runner requires earthmesh plan, got {}",
                plan.mesh_type
            ),
        ));
    }

    let inputs = read_mask_postproc_domain_inputs(plan)?;
    let patchtypes = build_earth_patchtypes_fortran_indexed(
        &inputs.contain,
        options.mask_sea_ratio,
        options.minlon_dm_area,
        options.maxlat_dm_area,
        options.nlons_dm_select,
        options.nlats_dm_select,
    )?;
    let patchtype = write_mask_postproc_patchtype_netcdf(
        plan,
        patchtypes.patchtypes_select.clone(),
        options.minlon_dm_area,
        options.maxlat_dm_area,
        options.lon_vertex,
        options.lat_vertex,
        options.lon_i,
        options.lat_i,
    )?;
    let final_gridfile =
        write_mask_postproc_final_gridfile(plan, &inputs.layout, &inputs.is_in_domain_ustr)?;
    let earthmesh_info = write_mask_postproc_earth_info_netcdf(
        plan,
        options.num_mp_step,
        options.sjx_points,
        &inputs.layout,
        &inputs.is_in_domain_ustr,
        &patchtypes.seaorland_ustr,
    )?;

    Ok(MaskPostprocEarthDomainReport {
        patchtypes,
        patchtype,
        final_gridfile,
        earthmesh_info,
    })
}

/// File-backed composition of the migrated
/// `MOD_mask_postproc.F90:mask_postproc_Lnd` branch.
///
/// The source-grid clipping uses the contain-domain mask exactly like the
/// Fortran branch, while land-specific patchtype assignment is delegated to the
/// already-migrated pure `build_land_patchtypes_fortran_indexed` helper.
pub fn run_mask_postproc_land_domain(
    plan: &MaskPostprocDomainIoPlan,
    options: MaskPostprocLandRunOptions<'_>,
) -> io::Result<MaskPostprocLandDomainReport> {
    if plan.mesh_type != "landmesh" {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "land mask_postproc runner requires landmesh plan, got {}",
                plan.mesh_type
            ),
        ));
    }

    let inputs = read_mask_postproc_domain_inputs(plan)?;
    let patchtypes = build_land_patchtypes_fortran_indexed(
        &inputs.contain,
        options.seaorland,
        options.minlon_dm_area,
        options.maxlat_dm_area,
        options.nlons_dm_select,
        options.nlats_dm_select,
    )?;
    let patchtype = write_mask_postproc_patchtype_netcdf(
        plan,
        patchtypes.patchtypes_select.clone(),
        options.minlon_dm_area,
        options.maxlat_dm_area,
        options.lon_vertex,
        options.lat_vertex,
        options.lon_i,
        options.lat_i,
    )?;
    let final_gridfile =
        write_mask_postproc_final_gridfile(plan, &inputs.layout, &inputs.is_in_domain_ustr)?;

    Ok(MaskPostprocLandDomainReport {
        patchtypes,
        patchtype,
        final_gridfile,
    })
}

/// File-backed composition of the migrated
/// `MOD_mask_postproc.F90:mask_postproc_Ocn` branch.
///
/// This runner composes contain-domain reading, the ocean sea-ratio mask
/// adjustment, tri/hex renewal, final gridfile writing, and tri-only boundary
/// outputs (`obc*.nc4`/`obcv2*.nc4`).
pub fn run_mask_postproc_ocean_domain(
    plan: &MaskPostprocDomainIoPlan,
    options: MaskPostprocOceanRunOptions,
) -> io::Result<MaskPostprocOceanDomainReport> {
    if plan.mesh_type != "oceanmesh" {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "ocean mask_postproc runner requires oceanmesh plan, got {}",
                plan.mesh_type
            ),
        ));
    }

    let inputs = read_mask_postproc_domain_inputs(plan)?;
    let ocean_mask = apply_ocean_mask_sea_ratio_fortran_indexed(
        &inputs.contain,
        options.num_vertex,
        options.mask_sea_ratio,
    )?;
    let renewal = renew_mask_postproc_ocean_domain_fortran_indexed(
        &inputs.layout,
        &ocean_mask,
        &plan.mode_grid,
    )?;
    let finalization = finalize_mask_postproc_layout_with_reindex_report(
        &inputs.layout,
        &renewal.is_in_domain_ustr,
        &plan.mode_grid,
    )?;
    let final_gridfile = write_unstructured_mesh_netcdf(&plan.result_gridfile, &finalization.mesh)?;

    let mut boundary_orders = None;
    let mut obc = None;
    let mut obcv2 = None;
    if plan.mode_grid == "tri" {
        let boundary = renewal.boundary.as_ref().ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                "tri ocean renewal did not produce boundary connection metadata",
            )
        })?;
        let isolated = renewal.isolated.as_ref().ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                "tri ocean renewal did not produce isolated-ocean metadata",
            )
        })?;
        let obcv2_output = plan.obcv2_output.as_ref().ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                "tri ocean plan is missing obcv2 output path",
            )
        })?;
        obcv2 = Some(write_obcv2_boundary_netcdf(obcv2_output, boundary)?);

        let orders = classify_boundary_orders_fortran_indexed(
            isolated.num_bdy_long,
            &isolated.bdy_long_order,
            &inputs.layout.vertex_neighbors,
            &inputs.layout.vertex_neighbor_counts,
            &finalization.vertex_reindex.vertex_mapping,
            &renewal.is_in_domain_ustr,
        )?;
        let obc_output = plan.obc_output.as_ref().ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                "tri ocean plan is missing obc output path",
            )
        })?;
        obc = Some(write_obc_boundary_netcdf(obc_output, &orders)?);
        boundary_orders = Some(orders);
    }

    Ok(MaskPostprocOceanDomainReport {
        renewal,
        finalization,
        final_gridfile,
        boundary_orders,
        obc,
        obcv2,
    })
}

/// Legacy output path for `MOD_mask_postproc.F90:bdy_calculation`.
pub fn obc_boundary_output_path(file_dir: impl AsRef<Path>, mask_patch_on: bool) -> PathBuf {
    let filename = if mask_patch_on {
        "obc_patch.nc4"
    } else {
        "obc.nc4"
    };
    file_dir.as_ref().join("result").join(filename)
}

/// Legacy output path for `MOD_mask_postproc.F90:bdy_connection`.
pub fn obcv2_boundary_output_path(file_dir: impl AsRef<Path>, mask_patch_on: bool) -> PathBuf {
    let filename = if mask_patch_on {
        "obcv2_patch.nc4"
    } else {
        "obcv2.nc4"
    };
    file_dir.as_ref().join("result").join(filename)
}

/// Plan the legacy file names used by Earth/Lnd/Ocn mask post-processing.
///
/// This is the side-effect-free I/O contract around the migrated pure helpers:
/// source mesh and contain-domain inputs, final clipped mesh output, optional
/// land/earth `patchtype` output, and ocean-tri OBC outputs.
pub fn plan_mask_postproc_domain_io(
    file_dir: impl AsRef<Path>,
    nxp: usize,
    mode_grid: &str,
    mesh_type: &str,
    mask_patch_on: bool,
) -> io::Result<MaskPostprocDomainIoPlan> {
    let file_dir = file_dir.as_ref();
    let mode_grid = mode_grid.trim();
    let mesh_type = mesh_type.trim();
    if !matches!(mode_grid, "tri" | "hex") {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "mask_postproc domain I/O supports tri or hex mode_grid only",
        ));
    }
    if !matches!(mesh_type, "earthmesh" | "landmesh" | "oceanmesh") {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "domain mask_postproc I/O plan supports earthmesh, landmesh, or oceanmesh; atmos/atmosmesh uses the MPAS branch",
        ));
    }

    let nxpc = format!("{nxp:04}");
    let source_gridfile = file_dir
        .join("result")
        .join(format!("gridfile_NXP{nxpc}_{mode_grid}.nc4"));
    let contain_domain = file_dir.join("contain").join(format!(
        "contain_{mesh_type}_domain_NXP{nxpc}_{mode_grid}.nc4"
    ));
    let result_suffix = if mask_patch_on { "_patch" } else { "" };
    let result_gridfile = file_dir.join("result").join(format!(
        "gridfile_NXP{nxpc}_{mode_grid}_{mesh_type}{result_suffix}.nc4"
    ));
    let patchtype_output = matches!(mesh_type, "earthmesh" | "landmesh").then(|| {
        file_dir
            .join("patchtype")
            .join(format!("patchtype_NXP{nxpc}_{mode_grid}.nc4"))
    });
    let writes_ocean_boundary = mesh_type == "oceanmesh" && mode_grid == "tri";
    let obc_output =
        writes_ocean_boundary.then(|| obc_boundary_output_path(file_dir, mask_patch_on));
    let obcv2_output =
        writes_ocean_boundary.then(|| obcv2_boundary_output_path(file_dir, mask_patch_on));

    Ok(MaskPostprocDomainIoPlan {
        file_dir: file_dir.to_path_buf(),
        mesh_type: mesh_type.to_string(),
        mode_grid: mode_grid.to_string(),
        source_gridfile,
        contain_domain,
        result_gridfile,
        patchtype_output,
        obc_output,
        obcv2_output,
    })
}

/// Write the `obc.nc4`/`obc_patch.nc4` schema produced by
/// `MOD_mask_postproc.F90:bdy_calculation`.
pub fn write_obc_boundary_netcdf(
    output: impl AsRef<Path>,
    orders: &BoundaryOrders,
) -> io::Result<ObcBoundaryWriteReport> {
    let bdy_num = orders.bdy_order.len();
    require_len("obc_order", orders.obc_order.len(), bdy_num)?;
    require_len("ibc_order", orders.ibc_order.len(), bdy_num)?;

    let output = output.as_ref();
    if let Some(parent) = output.parent() {
        fs::create_dir_all(parent)?;
    }

    let mut file = netcdf::create(output).map_err(netcdf_to_io_error)?;
    file.add_dimension("bdy_num", bdy_num)
        .map_err(netcdf_to_io_error)?;
    {
        let mut var = file
            .add_variable::<i32>("bdy_order", &["bdy_num"])
            .map_err(netcdf_to_io_error)?;
        var.put_values(&usize_values_to_i32("bdy_order", &orders.bdy_order)?, ..)
            .map_err(netcdf_to_io_error)?;
    }
    {
        let mut var = file
            .add_variable::<i32>("obc_order", &["bdy_num"])
            .map_err(netcdf_to_io_error)?;
        var.put_values(&usize_values_to_i32("obc_order", &orders.obc_order)?, ..)
            .map_err(netcdf_to_io_error)?;
    }
    {
        let mut var = file
            .add_variable::<i32>("ibc_order", &["bdy_num"])
            .map_err(netcdf_to_io_error)?;
        var.put_values(&usize_values_to_i32("ibc_order", &orders.ibc_order)?, ..)
            .map_err(netcdf_to_io_error)?;
    }

    Ok(ObcBoundaryWriteReport {
        output: output.to_path_buf(),
        boundary_points: bdy_num,
    })
}

/// Write the `obcv2.nc4`/`obcv2_patch.nc4` schema produced by
/// `MOD_mask_postproc.F90:bdy_connection`.
pub fn write_obcv2_boundary_netcdf(
    output: impl AsRef<Path>,
    connection: &BoundaryConnection,
) -> io::Result<Obcv2BoundaryWriteReport> {
    let num1 = connection.curves.num_bdy_long[0];
    let num2 = connection.curves.num_closed_curve;
    if connection.curves.close_curves.len() < num2 + 1 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "close_curves must include the placeholder plus num_closed_curve records",
        ));
    }
    if connection.curves.n_close_curve.len() < num2 + 1 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "n_close_curve must include the placeholder plus num_closed_curve records",
        ));
    }

    let output = output.as_ref();
    if let Some(parent) = output.parent() {
        fs::create_dir_all(parent)?;
    }

    let close_curve_values =
        flatten_close_curves_for_netcdf(&connection.curves.close_curves, num1, num2)?;
    let n_close_curve_values =
        usize_values_to_i32("n_close_curve", &connection.curves.n_close_curve[1..=num2])?;

    let mut file = netcdf::create(output).map_err(netcdf_to_io_error)?;
    file.add_dimension("num1", num1)
        .map_err(netcdf_to_io_error)?;
    file.add_dimension("num2", num2)
        .map_err(netcdf_to_io_error)?;
    {
        let mut var = file
            .add_variable::<i32>("close_curve", &["num2", "num1"])
            .map_err(netcdf_to_io_error)?;
        var.put_values(&close_curve_values, (.., ..))
            .map_err(netcdf_to_io_error)?;
    }
    {
        let mut var = file
            .add_variable::<i32>("n_close_curve", &["num2"])
            .map_err(netcdf_to_io_error)?;
        var.put_values(&n_close_curve_values, ..)
            .map_err(netcdf_to_io_error)?;
    }

    Ok(Obcv2BoundaryWriteReport {
        output: output.to_path_buf(),
        longest_curve_slots: num1,
        closed_curves: num2,
    })
}

#[derive(Debug, Clone)]
struct ColmCouplingCsvRow {
    cell_id: String,
    cell_index: i32,
    center_lon: f64,
    center_lat: f64,
    surface_class: String,
    has_river: bool,
    river_class: String,
    river_fraction: f64,
    estimated_river_area_m2: f64,
    has_coast: bool,
    coast_class: String,
    coastal_fraction: f64,
    normalized_cell_area_m2: f64,
    source_area_cell: f64,
}

/// Per-surface-class cell tally from [`write_colm_coupling_csv_from_mesh`].
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct ColmSurfaceCounts {
    pub land: usize,
    pub ocean: usize,
    pub coast: usize,
}

/// A CoLM coupling surface class tied to one mesh-cell centre.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct ColmSurfaceClassPoint {
    pub lon: f64,
    pub lat: f64,
    /// `surface_class_code`: 0=UNKNOWN, 1=LAND, 2=OCEAN, 3=COAST.
    pub code: i8,
}

/// Generate a CoLM coupling CSV directly from a mesh gridfile and a global
/// land-type NetCDF, in pure Rust — the first half of the CoLM surface-data
/// workflow (its output feeds [`write_colm_coupling_netcdf_from_csv`]).
///
/// Each cell centre (W cells for `hex`, M cells for `tri`) is sampled against
/// the land-type grid and classified LAND/OCEAN with the engine's Area_judge
/// rule ([`classify_area_judge_landtype_fortran_indexed`]: `landtype==0` ⇒
/// ocean). Coastal classification needs neighbour adjacency and the
/// river/coast attributes need the MERIT-Hydro/CaMa per-cell assignment, so
/// those columns are written as `none`/`0` for now — `[需数据]`: wire
/// `assign_hydro_coast_to_mesh_cells` once that data is available. Returns the
/// per-class cell counts.
/// CoLM coupling CSV fields, in the order of `util/hydro_mesh/colm_coupling.py`'s
/// `COUPLING_FIELDS`. `cell_id` is index 0, `river_class` index 2 (the sort keys).
const COLM_COUPLING_FIELDS: &[&str] = &[
    "cell_id",
    "cell_index",
    "river_class",
    "river_fraction",
    "estimated_river_area_m2",
    "normalized_cell_area_m2",
    "center_lon",
    "center_lat",
    "domain_clip_applied",
    "area_normalization",
];

fn format_coupling_number(n: f64) -> String {
    if n.is_finite() && n.fract() == 0.0 && n.abs() < 1e15 {
        format!("{}", n as i64)
    } else {
        format!("{n}")
    }
}

/// Render a GeoJSON property as a CSV cell, mirroring Python's pass-through
/// (`str(value)` for scalars, `""` for missing/None).
fn coupling_prop_string(props: &BTreeMap<String, JsonNode>, key: &str) -> String {
    match props.get(key) {
        Some(JsonNode::String(s)) => s.clone(),
        Some(JsonNode::Number(n)) => format_coupling_number(*n),
        Some(JsonNode::Bool(b)) => b.to_string(),
        _ => String::new(),
    }
}

/// Faithful Rust port of `util/hydro_mesh/colm_coupling.py::intersections_to_coupling_rows`:
/// read an EarthMesh cell×river intersection GeoJSON FeatureCollection and assemble CoLM
/// coupling rows. A feature is kept only if `river_fraction >= min_fraction` and both
/// `cell_id` and `river_class` are non-empty; rows are sorted by `(cell_id, river_class)`.
/// Pure parsing (the cell×mask overlay that produced the intersections is
/// `earthmesh_geometry::overlay_cell`); no shapely.
pub fn colm_coupling_rows_from_intersections(
    geojson_text: &str,
    min_fraction: f64,
) -> io::Result<Vec<Vec<String>>> {
    if !(0.0..=1.0).contains(&min_fraction) {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "min_fraction must be between 0 and 1",
        ));
    }
    let root = JsonParser::new(geojson_text).parse()?;
    let mut rows: Vec<Vec<String>> = Vec::new();
    for feature in geojson_feature_nodes(&root) {
        let Some(props) = feature
            .as_object()
            .and_then(|object| object.get("properties"))
            .and_then(JsonNode::as_object)
        else {
            continue;
        };
        // _as_float: number, or a numeric string, else 0.0.
        let river_fraction = match props.get("river_fraction") {
            Some(JsonNode::Number(n)) => *n,
            Some(JsonNode::String(s)) => s.trim().parse().unwrap_or(0.0),
            _ => 0.0,
        };
        if river_fraction < min_fraction {
            continue;
        }
        let cell_id = coupling_prop_string(props, "cell_id");
        let river_class = coupling_prop_string(props, "river_class");
        if cell_id.is_empty() || river_class.is_empty() {
            continue;
        }
        let row: Vec<String> = COLM_COUPLING_FIELDS
            .iter()
            .map(|&field| match field {
                "cell_id" => cell_id.clone(),
                "river_class" => river_class.clone(),
                "river_fraction" => format_coupling_number(river_fraction),
                other => coupling_prop_string(props, other),
            })
            .collect();
        rows.push(row);
    }
    rows.sort_by(|a, b| (a[0].as_str(), a[2].as_str()).cmp(&(b[0].as_str(), b[2].as_str())));
    Ok(rows)
}

/// Faithful Rust port of `colm_coupling.py::write_colm_coupling_csv`: intersection
/// GeoJSON -> CoLM coupling CSV. Returns the row count.
pub fn write_colm_coupling_csv_from_intersections(
    input_geojson: impl AsRef<Path>,
    output_csv: impl AsRef<Path>,
    min_fraction: f64,
) -> io::Result<usize> {
    let text = fs::read_to_string(input_geojson.as_ref())?;
    let rows = colm_coupling_rows_from_intersections(&text, min_fraction)?;
    let mut out = String::new();
    out.push_str(&COLM_COUPLING_FIELDS.join(","));
    out.push('\n');
    for row in &rows {
        out.push_str(&row.join(","));
        out.push('\n');
    }
    if let Some(parent) = output_csv.as_ref().parent() {
        fs::create_dir_all(parent)?;
    }
    fs::write(output_csv, out)?;
    Ok(rows.len())
}

/// Unit-sphere radius used by `util/hydro_mesh/earthmesh_intersection.py`.
const HYDRO_EARTH_RADIUS_M: f64 = 6_371_000.0;

fn round12(value: f64) -> f64 {
    (value * 1e12).round() / 1e12
}

/// `statistics.median`: middle for odd n, mean of the two middle for even n.
fn slice_median(values: &mut [f64]) -> f64 {
    values.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    let n = values.len();
    if n % 2 == 1 {
        values[n / 2]
    } else {
        (values[n / 2 - 1] + values[n / 2]) / 2.0
    }
}

/// All `-?\d+` integers on a line (faithful to the regex in refinement_eval.py).
fn line_integers(line: &str) -> Vec<i64> {
    let bytes = line.as_bytes();
    let mut out = Vec::new();
    let mut i = 0;
    while i < bytes.len() {
        let neg = bytes[i] == b'-';
        let start = i;
        let digit_start = if neg { i + 1 } else { i };
        let mut j = digit_start;
        while j < bytes.len() && bytes[j].is_ascii_digit() {
            j += 1;
        }
        if j > digit_start {
            if let Ok(v) = line[start..j].parse::<i64>() {
                out.push(v);
            }
            i = j;
        } else {
            i += 1;
        }
    }
    out
}

#[derive(Debug, Clone, Default)]
pub struct HydroBackgroundSummary {
    pub cell_count: usize,
    pub size_km_min: Option<f64>,
    pub size_km_median: Option<f64>,
    pub size_km_max: Option<f64>,
}

#[derive(Debug, Clone, Default)]
pub struct HydroIntersectionSummary {
    pub feature_count: usize,
    pub class_counts: BTreeMap<String, usize>,
    pub fraction_min: Option<f64>,
    pub fraction_median: Option<f64>,
    pub fraction_max: Option<f64>,
    pub area_sum: Option<f64>,
}

/// Faithful port of `refinement_eval.py::summarize_background_cells`.
fn summarize_background_cells(root: &JsonNode, unit_sphere_area: bool) -> HydroBackgroundSummary {
    let features = geojson_feature_nodes(root);
    let mut sizes_km = Vec::new();
    for feature in &features {
        let props = feature
            .as_object()
            .and_then(|o| o.get("properties"))
            .and_then(JsonNode::as_object);
        let Some(props) = props else { continue };
        let area = if let Some(a) = props
            .get("normalized_cell_area_m2")
            .and_then(JsonNode::as_f64)
        {
            Some(a)
        } else {
            props
                .get("source_areaCell")
                .and_then(JsonNode::as_f64)
                .map(|s| {
                    if unit_sphere_area {
                        s * HYDRO_EARTH_RADIUS_M * HYDRO_EARTH_RADIUS_M
                    } else {
                        s
                    }
                })
        };
        if let Some(a) = area {
            if a > 0.0 {
                sizes_km.push(a.sqrt() / 1000.0);
            }
        }
    }
    let mut summary = HydroBackgroundSummary {
        cell_count: features.len(),
        ..Default::default()
    };
    if !sizes_km.is_empty() {
        let min = sizes_km.iter().cloned().fold(f64::INFINITY, f64::min);
        let max = sizes_km.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
        summary.size_km_min = Some(round12(min));
        summary.size_km_median = Some(round12(slice_median(&mut sizes_km)));
        summary.size_km_max = Some(round12(max));
    }
    summary
}

fn summarize_intersection_generic(
    root: &JsonNode,
    class_keys: &[&str],
    fraction_keys: &[&str],
    area_keys: &[&str],
) -> HydroIntersectionSummary {
    let features = geojson_feature_nodes(root);
    let mut class_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut fractions = Vec::new();
    let mut area_sum = 0.0;
    for feature in &features {
        let Some(props) = feature
            .as_object()
            .and_then(|o| o.get("properties"))
            .and_then(JsonNode::as_object)
        else {
            continue;
        };
        let class = class_keys
            .iter()
            .find_map(|k| {
                props
                    .get(*k)
                    .and_then(JsonNode::as_str)
                    .filter(|s| !s.is_empty())
            })
            .unwrap_or("");
        if !class.is_empty() {
            *class_counts.entry(class.to_string()).or_insert(0) += 1;
        }
        for fk in fraction_keys {
            if let Some(v) = props.get(*fk).and_then(JsonNode::as_f64) {
                fractions.push(v);
                break;
            }
        }
        for ak in area_keys {
            if let Some(v) = props.get(*ak).and_then(JsonNode::as_f64) {
                area_sum += v;
                break;
            }
        }
    }
    let mut summary = HydroIntersectionSummary {
        feature_count: features.len(),
        class_counts,
        ..Default::default()
    };
    if !fractions.is_empty() {
        let min = fractions.iter().cloned().fold(f64::INFINITY, f64::min);
        let max = fractions.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
        summary.fraction_min = Some(round12(min));
        summary.fraction_median = Some(round12(slice_median(&mut fractions)));
        summary.fraction_max = Some(round12(max));
    }
    if area_sum > 0.0 {
        summary.area_sum = Some(round12(area_sum));
    }
    summary
}

/// Faithful port of `refinement_eval.py::summarize_intersections` (river).
fn summarize_river_intersections(root: &JsonNode) -> HydroIntersectionSummary {
    summarize_intersection_generic(
        root,
        &["river_class"],
        &["river_fraction"],
        &["estimated_river_area_m2"],
    )
}

/// Faithful port of `refinement_eval.py::summarize_coast_intersections`.
fn summarize_coast_intersections(root: &JsonNode) -> HydroIntersectionSummary {
    summarize_intersection_generic(
        root,
        &["mask_class", "overlap_class", "coast_class"],
        &["coastal_fraction", "coast_fraction"],
        &["estimated_coastal_area_m2", "estimated_coast_area_m2"],
    )
}

/// Faithful port of `refinement_eval.py::parse_refinement_log`.
pub fn parse_refinement_log(log_text: &str) -> BTreeMap<String, BTreeMap<String, i64>> {
    let mut result: BTreeMap<String, BTreeMap<String, i64>> = BTreeMap::new();
    let mut current: Option<String> = None;
    for line in log_text.lines() {
        let nums = line_integers(line);
        let last = nums.last().copied();
        let norm = line.split_whitespace().collect::<Vec<_>>().join(" ");
        if line.contains("refine_degree") {
            if let Some(d) = last {
                current = Some(d.to_string());
                result.entry(d.to_string()).or_default();
            }
        } else if line.contains("需要细化的三角形个数") {
            if let (Some(d), Some(v)) = (&current, last) {
                result
                    .entry(d.clone())
                    .or_default()
                    .insert("selected_triangles".into(), v);
            }
        } else if norm.contains("before num_ref") {
            if let (Some(d), Some(v)) = (&current, last) {
                result
                    .entry(d.clone())
                    .or_default()
                    .insert("before_nested_cleanup_triangles".into(), v);
            }
        } else if norm.contains("after num_ref") {
            if let (Some(d), Some(v)) = (&current, last) {
                result
                    .entry(d.clone())
                    .or_default()
                    .insert("after_nested_cleanup_triangles".into(), v);
            }
        } else if line.contains("去除孤立细化三角形后") {
            if let (Some(d), Some(v)) = (&current, last) {
                result
                    .entry(d.clone())
                    .or_default()
                    .insert("retained_triangles".into(), v);
            }
        }
    }
    result
}

fn opt_num_field(buf: &mut String, key: &str, value: Option<f64>) {
    if let Some(v) = value {
        if v.is_finite() {
            buf.push_str(&format!(",\n    \"{key}\": {v}"));
        }
    }
}

fn intersection_summary_json(summary: &HydroIntersectionSummary, kind: &str) -> String {
    let cc = summary
        .class_counts
        .iter()
        .map(|(k, v)| format!("\"{}\": {}", k.replace('"', "\\\""), v))
        .collect::<Vec<_>>()
        .join(", ");
    let mut s = format!(
        "{{\n    \"feature_count\": {},\n    \"class_counts\": {{{cc}}}",
        summary.feature_count
    );
    let (fmin, fmed, fmax, asum) = if kind == "river" {
        (
            "river_fraction_min",
            "river_fraction_median",
            "river_fraction_max",
            "estimated_river_area_m2_sum",
        )
    } else {
        (
            "coastal_fraction_min",
            "coastal_fraction_median",
            "coastal_fraction_max",
            "estimated_coastal_area_m2_sum",
        )
    };
    opt_num_field(&mut s, fmin, summary.fraction_min);
    opt_num_field(&mut s, fmed, summary.fraction_median);
    opt_num_field(&mut s, fmax, summary.fraction_max);
    opt_num_field(&mut s, asum, summary.area_sum);
    s.push_str("\n  }");
    s
}

/// Assemble the refinement-eval report JSON (faithful to `build_refinement_eval`).
pub fn build_refinement_eval_json(
    background: &HydroBackgroundSummary,
    river: &HydroIntersectionSummary,
    coast: Option<&HydroIntersectionSummary>,
    log: Option<&BTreeMap<String, BTreeMap<String, i64>>>,
) -> String {
    let mut s = String::from("{\n  \"kind\": \"earthmesh_hydro_refinement_eval\",\n");
    let mut bg = format!(
        "  \"background_cells\": {{\n    \"cell_count\": {}",
        background.cell_count
    );
    opt_num_field(
        &mut bg,
        "equivalent_cell_size_km_min",
        background.size_km_min,
    );
    opt_num_field(
        &mut bg,
        "equivalent_cell_size_km_median",
        background.size_km_median,
    );
    opt_num_field(
        &mut bg,
        "equivalent_cell_size_km_max",
        background.size_km_max,
    );
    bg.push_str("\n  }");
    s.push_str(&bg);
    s.push_str(",\n  \"river_intersections\": ");
    s.push_str(&intersection_summary_json(river, "river"));
    if let Some(c) = coast {
        s.push_str(",\n  \"coast_intersections\": ");
        s.push_str(&intersection_summary_json(c, "coast"));
    }
    if let Some(log) = log {
        s.push_str(",\n  \"refinement_log\": {");
        let degrees: Vec<String> = log
            .iter()
            .map(|(deg, metrics)| {
                let inner = metrics
                    .iter()
                    .map(|(k, v)| format!("\"{k}\": {v}"))
                    .collect::<Vec<_>>()
                    .join(", ");
                format!("\n    \"{deg}\": {{{inner}}}")
            })
            .collect();
        s.push_str(&degrees.join(","));
        s.push_str("\n  }");
    }
    s.push_str("\n}\n");
    s
}

/// Faithful port of `refinement_eval.py::write_refinement_eval_json`.
pub fn write_refinement_eval_json(
    background_geojson: impl AsRef<Path>,
    intersections_geojson: impl AsRef<Path>,
    output_json: impl AsRef<Path>,
    coast_intersections_geojson: Option<&Path>,
    log_path: Option<&Path>,
    unit_sphere_area: bool,
) -> io::Result<()> {
    let bg_root = JsonParser::new(&fs::read_to_string(background_geojson.as_ref())?).parse()?;
    let river_root =
        JsonParser::new(&fs::read_to_string(intersections_geojson.as_ref())?).parse()?;
    let background = summarize_background_cells(&bg_root, unit_sphere_area);
    let river = summarize_river_intersections(&river_root);
    let coast = match coast_intersections_geojson {
        Some(p) => Some(summarize_coast_intersections(
            &JsonParser::new(&fs::read_to_string(p)?).parse()?,
        )),
        None => None,
    };
    let log = match log_path {
        Some(p) => Some(parse_refinement_log(&fs::read_to_string(p)?)),
        None => None,
    };
    let json = build_refinement_eval_json(&background, &river, coast.as_ref(), log.as_ref());
    if let Some(parent) = output_json.as_ref().parent() {
        fs::create_dir_all(parent)?;
    }
    fs::write(output_json, json)
}

// ---- util/hydro_mesh/refinement_sweep.py port ----

/// Build one composite close-mask recipe JSON for an (r2_cap, coast_cap) sweep case
/// (faithful to `refinement_sweep.py::build_river_coast_sweep`).
fn build_sweep_recipe_json(
    river_geojson: &str,
    coast_geojson: &str,
    r2_cap: i64,
    coast_cap: i64,
    r3_cap: i64,
) -> String {
    let esc = |v: &str| v.replace('\\', "\\\\").replace('"', "\\\"");
    format!(
        "{{\n  \"max_masks_per_refine_degree\": 999,\n  \"components\": [\n    \
         {{\"name\": \"coastline_support\", \"input_geojson\": \"{coast}\", \
         \"class_refine\": {{\"COAST\": 1}}, \"max_rings_by_class\": {{\"COAST\": {coast_cap}}}, \
         \"simplify_tolerance_deg\": 0.005}},\n    \
         {{\"name\": \"ranked_river_corridors\", \"input_geojson\": \"{river}\", \
         \"class_refine\": {{\"R2\": 1, \"R3\": 3}}, \
         \"max_rings_by_class\": {{\"R2\": {r2_cap}, \"R3\": {r3_cap}}}, \
         \"buffer_deg_by_refine_degree\": {{\"1\": 1.5, \"2\": 1.0, \"3\": 0.5}}, \
         \"simplify_tolerance_deg\": 0.005}}\n  ]\n}}\n",
        coast = esc(coast_geojson),
        river = esc(river_geojson),
    )
}

/// Faithful port of `refinement_sweep.py::write_sweep_recipes`: write one recipe JSON
/// per (r2_cap, coast_cap) case + a `sweep_manifest.json`.
pub fn write_sweep_recipes(
    output_dir: impl AsRef<Path>,
    river_geojson: &str,
    coast_geojson: &str,
    mut r2_caps: Vec<i64>,
    mut coast_caps: Vec<i64>,
    r3_cap: i64,
) -> io::Result<usize> {
    let dir = output_dir.as_ref();
    fs::create_dir_all(dir)?;
    r2_caps.sort_unstable();
    coast_caps.sort_unstable();
    let esc = |v: &str| v.replace('\\', "\\\\").replace('"', "\\\"");
    let mut manifest_cases = Vec::new();
    for &r2_cap in &r2_caps {
        for &coast_cap in &coast_caps {
            let case_name = format!("r2cap{r2_cap}_coast{coast_cap}");
            let recipe_path = dir.join(format!("{case_name}_recipe.json"));
            fs::write(
                &recipe_path,
                build_sweep_recipe_json(river_geojson, coast_geojson, r2_cap, coast_cap, r3_cap),
            )?;
            manifest_cases.push(format!(
                "    {{\"case_name\": \"{case_name}\", \"r2_cap\": {r2_cap}, \"coast_cap\": {coast_cap}, \"recipe_json\": \"{}\"}}",
                esc(&recipe_path.display().to_string())
            ));
        }
    }
    let case_count = manifest_cases.len();
    let ints = |v: &[i64]| {
        v.iter()
            .map(|n| n.to_string())
            .collect::<Vec<_>>()
            .join(", ")
    };
    let manifest = format!(
        "{{\n  \"kind\": \"earthmesh_refinement_sweep_manifest\",\n  \"case_count\": {},\n  \
         \"river_geojson\": \"{}\",\n  \"coast_geojson\": \"{}\",\n  \"r2_caps\": [{}],\n  \
         \"coast_caps\": [{}],\n  \"r3_cap\": {},\n  \"cases\": [\n{}\n  ]\n}}\n",
        case_count,
        esc(river_geojson),
        esc(coast_geojson),
        ints(&r2_caps),
        ints(&coast_caps),
        r3_cap,
        manifest_cases.join(",\n"),
    );
    fs::write(dir.join("sweep_manifest.json"), manifest)?;
    Ok(case_count)
}

#[derive(Debug, Clone)]
pub struct RankedSweepCase {
    pub case_name: String,
    pub status: String,
    pub promotion_status: String,
    pub background_cell_count: i64,
    pub background_median_dx_km: f64,
    pub river_overlap_cells: i64,
    pub coast_overlap_cells: i64,
    pub retained: [i64; 3], // degrees 1,2,3
    pub rank: usize,
}

fn promotion_bucket(status: &str) -> i32 {
    match status {
        "candidate" => 0,
        "blocked_background_cell_cap" => 1,
        _ => 2,
    }
}

fn rankable_row(report: &JsonNode, max_background_cells: Option<i64>) -> RankedSweepCase {
    let obj = report.as_object();
    let get_obj = |key: &str| obj.and_then(|o| o.get(key)).and_then(JsonNode::as_object);
    let background = get_obj("background_cells");
    let river = get_obj("river_intersections");
    let coast = get_obj("coast_intersections");
    let num = |o: Option<&BTreeMap<String, JsonNode>>, k: &str| {
        o.and_then(|m| m.get(k))
            .and_then(JsonNode::as_f64)
            .unwrap_or(0.0)
    };
    let status = obj
        .and_then(|o| o.get("status"))
        .and_then(JsonNode::as_str)
        .unwrap_or("pass")
        .to_string();
    let background_cells = num(background, "cell_count") as i64;
    let promotion_status = if status != "pass" {
        "failed".to_string()
    } else if max_background_cells.is_some_and(|cap| background_cells > cap) {
        "blocked_background_cell_cap".to_string()
    } else {
        "candidate".to_string()
    };
    let retained_at = |deg: &str| {
        obj.and_then(|o| o.get("refinement_log"))
            .and_then(JsonNode::as_object)
            .and_then(|l| l.get(deg))
            .and_then(JsonNode::as_object)
            .and_then(|d| d.get("retained_triangles"))
            .and_then(JsonNode::as_f64)
            .unwrap_or(0.0) as i64
    };
    RankedSweepCase {
        case_name: obj
            .and_then(|o| o.get("case_name"))
            .and_then(JsonNode::as_str)
            .unwrap_or("")
            .to_string(),
        status,
        promotion_status,
        background_cell_count: background_cells,
        background_median_dx_km: num(background, "equivalent_cell_size_km_median"),
        river_overlap_cells: num(river, "feature_count") as i64,
        coast_overlap_cells: num(coast, "feature_count") as i64,
        retained: [retained_at("1"), retained_at("2"), retained_at("3")],
        rank: 0,
    }
}

/// Faithful port of `refinement_sweep.py::rank_sweep_reports`: sort eval reports into
/// promotion candidates (bucket, retained 3/2/1 desc, river/coast desc, median dx asc,
/// cell count asc, case name) and assign 1-based ranks.
fn rank_sweep_rows(mut rows: Vec<RankedSweepCase>) -> Vec<RankedSweepCase> {
    rows.sort_by(|a, b| {
        use std::cmp::Ordering;
        let key = |r: &RankedSweepCase| {
            (
                promotion_bucket(&r.promotion_status),
                -r.retained[2],
                -r.retained[1],
                -r.retained[0],
                -r.river_overlap_cells,
                -r.coast_overlap_cells,
            )
        };
        key(a)
            .cmp(&key(b))
            .then(
                a.background_median_dx_km
                    .partial_cmp(&b.background_median_dx_km)
                    .unwrap_or(Ordering::Equal),
            )
            .then(a.background_cell_count.cmp(&b.background_cell_count))
            .then(a.case_name.cmp(&b.case_name))
    });
    for (i, row) in rows.iter_mut().enumerate() {
        row.rank = i + 1;
    }
    rows
}

/// Faithful port of `refinement_sweep.py::write_sweep_ranking`.
pub fn write_sweep_ranking(
    report_paths: &[PathBuf],
    output_json: impl AsRef<Path>,
    max_background_cells: Option<i64>,
) -> io::Result<String> {
    let mut rows = Vec::new();
    for path in report_paths {
        let text = fs::read_to_string(path)?;
        let mut report = JsonParser::new(&text).parse()?;
        // Default case_name to the file stem when absent (Python behavior).
        if let JsonNode::Object(map) = &mut report {
            if !map.contains_key("case_name") {
                let stem = path
                    .file_stem()
                    .and_then(|s| s.to_str())
                    .unwrap_or("")
                    .to_string();
                map.insert("case_name".into(), JsonNode::String(stem));
            }
        }
        rows.push(rankable_row(&report, max_background_cells));
    }
    let ranked = rank_sweep_rows(rows);
    let recommended = ranked
        .iter()
        .find(|r| r.promotion_status == "candidate")
        .map(|r| r.case_name.clone());

    let mut s = String::from("{\n  \"kind\": \"earthmesh_refinement_sweep_ranking\",\n");
    match &recommended {
        Some(c) => s.push_str(&format!(
            "  \"recommended_case\": \"{}\",\n",
            c.replace('"', "\\\"")
        )),
        None => s.push_str("  \"recommended_case\": null,\n"),
    }
    s.push_str("  \"ranked_cases\": [\n");
    let n = ranked.len();
    for (i, r) in ranked.iter().enumerate() {
        let comma = if i + 1 < n { "," } else { "" };
        s.push_str(&format!(
            "    {{\"rank\": {}, \"case_name\": \"{}\", \"status\": \"{}\", \"promotion_status\": \"{}\", \
             \"background_cell_count\": {}, \"background_median_dx_km\": {}, \"river_overlap_cells\": {}, \
             \"coast_overlap_cells\": {}, \"retained_triangles\": {{\"1\": {}, \"2\": {}, \"3\": {}}}}}{}\n",
            r.rank,
            r.case_name.replace('"', "\\\""),
            r.status,
            r.promotion_status,
            r.background_cell_count,
            r.background_median_dx_km,
            r.river_overlap_cells,
            r.coast_overlap_cells,
            r.retained[0],
            r.retained[1],
            r.retained[2],
            comma
        ));
    }
    s.push_str("  ]\n}\n");
    if let Some(parent) = output_json.as_ref().parent() {
        fs::create_dir_all(parent)?;
    }
    fs::write(output_json, &s)?;
    Ok(recommended.unwrap_or_default())
}

// ---- util/hydro_mesh/coastal_band.py port (pure grid core) ----

/// Faithful port of `coastal_band.py::land_mask_from_elevation`: True where the CaMa
/// elevation value is finite and not the undef sentinel.
pub fn coastal_land_mask_from_elevation(elevation: &[Vec<f64>], undef: f64) -> Vec<Vec<bool>> {
    elevation
        .iter()
        .map(|row| row.iter().map(|&v| v.is_finite() && v != undef).collect())
        .collect()
}

/// Faithful port of `coastal_band.py::coastal_band_cells`: select cells within a
/// Chebyshev `radius_cells` of a land/ocean transition (a neighbor of the opposite
/// type). `include_land_side` / `include_ocean_side` straddle the coastline.
pub fn coastal_band_cells(
    land_mask: &[Vec<bool>],
    radius_cells: i64,
    include_land_side: bool,
    include_ocean_side: bool,
) -> io::Result<Vec<Vec<bool>>> {
    if radius_cells < 1 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "radius_cells must be at least 1",
        ));
    }
    let height = land_mask.len();
    if height == 0 || land_mask.iter().any(|r| r.len() != land_mask[0].len()) {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "land_mask must be a non-empty rectangular grid",
        ));
    }
    let width = land_mask[0].len();
    let r = radius_cells as usize;
    let mut band = vec![vec![false; width]; height];
    for y in 0..height {
        for x in 0..width {
            let is_land = land_mask[y][x];
            if is_land && !include_land_side {
                continue;
            }
            if !is_land && !include_ocean_side {
                continue;
            }
            let (y0, y1) = (y.saturating_sub(r), (y + r + 1).min(height));
            let (x0, x1) = (x.saturating_sub(r), (x + r + 1).min(width));
            let mut found_opposite = false;
            'scan: for yy in y0..y1 {
                for xx in x0..x1 {
                    if xx == x && yy == y {
                        continue;
                    }
                    if land_mask[yy][xx] != is_land {
                        found_opposite = true;
                        break 'scan;
                    }
                }
            }
            band[y][x] = found_opposite;
        }
    }
    Ok(band)
}

/// Ray-cast point-in-(arbitrary)-ring test, for nesting union holes under their outer.
fn point_in_polygon_ring(p: earthmesh_geometry::Point, ring: &[earthmesh_geometry::Point]) -> bool {
    let mut inside = false;
    let n = ring.len();
    let mut j = n - 1;
    for i in 0..n {
        let (a, b) = (ring[i], ring[j]);
        if ((a.y > p.y) != (b.y > p.y)) && (p.x < (b.x - a.x) * (p.y - a.y) / (b.y - a.y) + a.x) {
            inside = !inside;
        }
        j = i;
    }
    inside
}

/// Dissolve a coastal-band mask into a merged MultiPolygon GeoJSON (the `dissolve=True`
/// path of `coastal_band.py::coastal_band_geojson`). The band cells are equal grid
/// boxes, so the union is exact via `earthmesh_geometry::dissolve_axis_aligned_boxes`
/// (edge cancellation), then CW hole rings are nested under their containing CCW outer.
/// Returns the polygon (outer-ring) count.
pub fn write_coastal_band_dissolve_geojson(
    band: &[Vec<bool>],
    x_start: i64,
    y_start: i64,
    west: f64,
    south: f64,
    grid_size_deg: f64,
    output_geojson: impl AsRef<Path>,
) -> io::Result<usize> {
    use earthmesh_geometry::{dissolve_axis_aligned_boxes, signed_ring_area, Point};
    let mut boxes = Vec::new();
    let mut cell_count = 0usize;
    for (row, line) in band.iter().enumerate() {
        for (col, &selected) in line.iter().enumerate() {
            if !selected {
                continue;
            }
            cell_count += 1;
            let x0 = west + (x_start + col as i64) as f64 * grid_size_deg;
            let y0 = south + (y_start + row as i64) as f64 * grid_size_deg;
            boxes.push((x0, y0, x0 + grid_size_deg, y0 + grid_size_deg));
        }
    }
    let rings = dissolve_axis_aligned_boxes(&boxes);
    let outers: Vec<&Vec<Point>> = rings.iter().filter(|r| signed_ring_area(r) > 0.0).collect();
    let holes: Vec<&Vec<Point>> = rings.iter().filter(|r| signed_ring_area(r) < 0.0).collect();

    let ring_coords = |ring: &[Point]| -> String {
        let mut pts: Vec<String> = ring.iter().map(|p| format!("[{}, {}]", p.x, p.y)).collect();
        if let Some(first) = ring.first() {
            pts.push(format!("[{}, {}]", first.x, first.y)); // close the ring
        }
        format!("[{}]", pts.join(", "))
    };

    // assemble MultiPolygon: each outer + the holes whose first vertex lies inside it
    let mut polygons: Vec<String> = Vec::new();
    for &outer in &outers {
        let mut rings_json = vec![ring_coords(outer)];
        for &hole in &holes {
            if hole
                .first()
                .is_some_and(|p| point_in_polygon_ring(*p, outer))
            {
                rings_json.push(ring_coords(hole));
            }
        }
        polygons.push(format!("[{}]", rings_json.join(", ")));
    }

    let geometry = format!(
        "{{\"type\": \"MultiPolygon\", \"coordinates\": [{}]}}",
        polygons.join(", ")
    );
    let out = format!(
        "{{\n  \"type\": \"FeatureCollection\",\n  \"features\": [\n    {{\"type\": \"Feature\", \
         \"geometry\": {}, \"properties\": {{\"mask_class\": \"COAST\", \
         \"coastal_band_cell_count\": {}, \"corridor_source_geometry\": \"cama_elevtn_coastal_band\"}}}}\n  ]\n}}\n",
        geometry, cell_count
    );
    if let Some(parent) = output_geojson.as_ref().parent() {
        fs::create_dir_all(parent)?;
    }
    fs::write(output_geojson, out)?;
    Ok(outers.len())
}

/// Non-dissolve coastal-band output: one Polygon Feature per band cell (port of the
/// `coastal_band.py::coastal_band_geojson` dissolve=False path).
fn write_coastal_band_cells_geojson(
    band: &[Vec<bool>],
    land_mask: &[Vec<bool>],
    x_start: i64,
    y_start: i64,
    west: f64,
    south: f64,
    grid_size_deg: f64,
    output_geojson: impl AsRef<Path>,
) -> io::Result<usize> {
    let mut cells: Vec<(i64, i64, bool)> = Vec::new();
    for (row, line) in band.iter().enumerate() {
        for (col, &selected) in line.iter().enumerate() {
            if selected {
                let is_land = land_mask
                    .get(row)
                    .and_then(|r| r.get(col))
                    .copied()
                    .unwrap_or(false);
                cells.push((x_start + col as i64, y_start + row as i64, is_land));
            }
        }
    }
    let land_count = cells.iter().filter(|(_, _, l)| *l).count();
    let total = cells.len();
    let mut features = Vec::new();
    for (xi, yi, is_land) in &cells {
        let x0 = west + *xi as f64 * grid_size_deg;
        let y0 = south + *yi as f64 * grid_size_deg;
        let (x1, y1) = (x0 + grid_size_deg, y0 + grid_size_deg);
        features.push(format!(
            "    {{\"type\": \"Feature\", \"geometry\": {{\"type\": \"Polygon\", \"coordinates\": \
             [[[{x0}, {y0}], [{x1}, {y0}], [{x1}, {y1}], [{x0}, {y1}], [{x0}, {y0}]]]}}, \
             \"properties\": {{\"mask_class\": \"COAST\", \"coastal_band_cell_count\": {total}, \
             \"land_side_cell_count\": {land_count}, \"ocean_side_cell_count\": {}, \
             \"corridor_source_geometry\": \"cama_elevtn_coastal_band\", \"x_index\": {xi}, \
             \"y_index\": {yi}, \"coastal_side\": \"{}\"}}}}",
            total - land_count,
            if *is_land { "land" } else { "ocean" }
        ));
    }
    let out = format!(
        "{{\n  \"type\": \"FeatureCollection\",\n  \"features\": [\n{}\n  ]\n}}\n",
        features.join(",\n")
    );
    if let Some(parent) = output_geojson.as_ref().parent() {
        fs::create_dir_all(parent)?;
    }
    fs::write(output_geojson, out)?;
    Ok(total)
}

/// End-to-end port of `coastal_band.py::write_coastal_band_geojson`: read a CaMa map
/// directory (`params.txt` + `elevtn.bin`), derive the land mask over the bbox window,
/// select the coastal band, and write it as GeoJSON (dissolved MultiPolygon or per-cell
/// polygons). `y_reversed` matches Python's default `y_reversed_storage=True`.
#[allow(clippy::too_many_arguments)]
pub fn write_coastal_band_geojson_from_cama(
    map_dir: impl AsRef<Path>,
    output_geojson: impl AsRef<Path>,
    west: f64,
    south: f64,
    east: f64,
    north: f64,
    radius_cells: i64,
    y_reversed: bool,
    dissolve: bool,
    undef: f64,
) -> io::Result<usize> {
    let root = map_dir.as_ref();
    let mut grid = read_cama_grid_spec_from_params_file(root.join("params.txt"))?;
    grid.y_reversed_storage = y_reversed;
    let window = grid.window_for_bbox(west, east, south, north)?;
    let report = read_cama_elevtn_surface_window(root.join("elevtn.bin"), grid, window, undef)?;
    let land_mask: Vec<Vec<bool>> = report
        .surface_mask
        .iter()
        .map(|row| row.iter().map(|&c| c == CamaSurfaceClass::Land).collect())
        .collect();
    let band = coastal_band_cells(&land_mask, radius_cells, true, true)?;
    if dissolve {
        write_coastal_band_dissolve_geojson(
            &band,
            window.x_start as i64,
            window.y_start as i64,
            grid.west,
            grid.south,
            grid.grid_size_deg,
            output_geojson,
        )
    } else {
        write_coastal_band_cells_geojson(
            &band,
            &land_mask,
            window.x_start as i64,
            window.y_start as i64,
            grid.west,
            grid.south,
            grid.grid_size_deg,
            output_geojson,
        )
    }
}

// ---- util/hydro_mesh/earthmesh_intersection.py::read_mpas_cell_polygons port ----

fn mpas_deg_lon(rad: f64) -> f64 {
    let d = rad.to_degrees();
    let mut n = (d + 180.0).rem_euclid(360.0) - 180.0;
    if n == -180.0 && d > 0.0 {
        n = 180.0;
    }
    round12(n)
}
fn mpas_deg_lat(rad: f64) -> f64 {
    round12(rad.to_degrees())
}

/// Faithful port of `read_mpas_cell_polygons` geometry: MPAS/EarthMesh cell arrays
/// (lon/lat in radians, 1-based `vertices_on_cell` flattened `n_cells × max_edges`) →
/// cell-polygon GeoJSON (the cells input the overlay writers consume). `bbox` filters
/// by cell center; `area_cell` (if given) becomes `source_areaCell`.
#[allow(clippy::too_many_arguments)]
pub fn mpas_cell_polygons_geojson(
    lon_cell: &[f64],
    lat_cell: &[f64],
    lon_vertex: &[f64],
    lat_vertex: &[f64],
    n_edges_on_cell: &[i32],
    vertices_on_cell: &[i32],
    area_cell: Option<&[f64]>,
    bbox: Option<[f64; 4]>,
    max_cells: Option<usize>,
) -> String {
    let n_cells = lon_cell.len();
    let max_edges = vertices_on_cell.len().checked_div(n_cells).unwrap_or(0);
    let lon_v: Vec<f64> = lon_vertex.iter().map(|&r| mpas_deg_lon(r)).collect();
    let lat_v: Vec<f64> = lat_vertex.iter().map(|&r| mpas_deg_lat(r)).collect();
    let mut features: Vec<String> = Vec::new();
    for ci in 0..n_cells {
        let clon = mpas_deg_lon(lon_cell[ci]);
        let clat = mpas_deg_lat(lat_cell[ci]);
        if let Some(b) = bbox {
            if !(b[0] <= clon && clon <= b[2] && b[1] <= clat && clat <= b[3]) {
                continue;
            }
        }
        let ne = (n_edges_on_cell.get(ci).copied().unwrap_or(0).max(0) as usize).min(max_edges);
        let mut ring: Vec<(f64, f64)> = Vec::with_capacity(ne + 1);
        for k in 0..ne {
            let vid = vertices_on_cell[ci * max_edges + k];
            if vid > 0 && (vid as usize) <= lon_v.len() {
                ring.push((lon_v[vid as usize - 1], lat_v[vid as usize - 1]));
            }
        }
        if ring.len() < 3 {
            continue;
        }
        let first = ring[0];
        ring.push(first); // close
        let coords = ring
            .iter()
            .map(|(x, y)| format!("[{x}, {y}]"))
            .collect::<Vec<_>>()
            .join(", ");
        let mut props = format!(
            "\"cell_id\": \"{}\", \"cell_index\": {}, \"grid_kind\": \"earthmesh_cell\", \
             \"center_lon\": {}, \"center_lat\": {}",
            ci + 1,
            ci,
            clon,
            clat
        );
        if let Some(area) = area_cell {
            if let Some(a) = area.get(ci) {
                props.push_str(&format!(
                    ", \"source_areaCell\": {}, \"source_areaCell_units\": \"file_units\"",
                    a
                ));
            }
        }
        features.push(format!(
            "    {{\"type\": \"Feature\", \"geometry\": {{\"type\": \"Polygon\", \"coordinates\": [[{}]]}}, \"properties\": {{{}}}}}",
            coords, props
        ));
        if let Some(mc) = max_cells {
            if features.len() >= mc {
                break;
            }
        }
    }
    format!(
        "{{\n  \"type\": \"FeatureCollection\",\n  \"features\": [\n{}\n  ]\n}}\n",
        features.join(",\n")
    )
}

/// Read an MPAS/EarthMesh mesh NetCDF and write cell-polygon GeoJSON (the cells input
/// for `--hydro-cell-intersections` / `--hydro-complete-cell-mask`).
pub fn write_mpas_cell_polygons_geojson(
    mesh_netcdf: impl AsRef<Path>,
    output_geojson: impl AsRef<Path>,
    bbox: Option<[f64; 4]>,
    max_cells: Option<usize>,
) -> io::Result<usize> {
    let file = netcdf::open(mesh_netcdf.as_ref()).map_err(netcdf_to_io_error)?;
    let lon_cell = required_values_f64(&file, "lonCell")?;
    let lat_cell = required_values_f64(&file, "latCell")?;
    let lon_vertex = required_values_f64(&file, "lonVertex")?;
    let lat_vertex = required_values_f64(&file, "latVertex")?;
    let n_edges_on_cell = required_values_i32(&file, "nEdgesOnCell")?;
    let vertices_on_cell = required_values_i32_2d(&file, "verticesOnCell")?;
    let area_cell = required_values_f64(&file, "areaCell").ok();
    let json = mpas_cell_polygons_geojson(
        &lon_cell,
        &lat_cell,
        &lon_vertex,
        &lat_vertex,
        &n_edges_on_cell,
        &vertices_on_cell,
        area_cell.as_deref(),
        bbox,
        max_cells,
    );
    let feature_count = json.matches("\"type\": \"Feature\"").count();
    if let Some(parent) = output_geojson.as_ref().parent() {
        fs::create_dir_all(parent)?;
    }
    fs::write(output_geojson, json)?;
    Ok(feature_count)
}

// ---- util/hydro_mesh/refinement_package.py manifest builder port ----

fn manifest_feature_count(node: Option<&JsonNode>) -> i64 {
    node.and_then(JsonNode::as_object)
        .map(|m| {
            m.get("cell_count")
                .or_else(|| m.get("feature_count"))
                .and_then(JsonNode::as_f64)
                .unwrap_or(0.0) as i64
        })
        .unwrap_or(0)
}

fn manifest_retained_triangles(eval_root: &JsonNode) -> [i64; 3] {
    let log = eval_root
        .as_object()
        .and_then(|o| o.get("refinement_log"))
        .and_then(JsonNode::as_object);
    let at = |deg: &str| {
        log.and_then(|l| l.get(deg))
            .and_then(JsonNode::as_object)
            .and_then(|r| r.get("retained_triangles"))
            .and_then(JsonNode::as_f64)
            .unwrap_or(0.0) as i64
    };
    [at("1"), at("2"), at("3")]
}

/// Faithful port of `refinement_package.py::_build_manifest`: assemble the
/// `earthmesh_hydro_coast_delivery_package` manifest (the file QA gates consume) from
/// an eval report + ranking + artifact paths.
fn build_hydro_delivery_manifest_json(
    case_name: &str,
    eval_root: &JsonNode,
    ranking_root: &JsonNode,
    files: &[(String, String)],
    source_files: &[(String, String)],
) -> String {
    let esc = |v: &str| v.replace('\\', "\\\\").replace('"', "\\\"");
    let recommended = ranking_root
        .as_object()
        .and_then(|o| o.get("recommended_case"));
    let recommended_json = match recommended {
        Some(JsonNode::String(s)) => format!("\"{}\"", esc(s)),
        _ => "null".to_string(),
    };
    let eval_obj = eval_root.as_object();
    let bg = manifest_feature_count(eval_obj.and_then(|o| o.get("background_cells")));
    let river = manifest_feature_count(eval_obj.and_then(|o| o.get("river_intersections")));
    let coast = manifest_feature_count(eval_obj.and_then(|o| o.get("coast_intersections")));
    let ret = manifest_retained_triangles(eval_root);

    let obj_pairs = |pairs: &[(String, String)]| {
        let mut sorted = pairs.to_vec();
        sorted.sort_by(|a, b| a.0.cmp(&b.0));
        sorted
            .iter()
            .map(|(k, v)| format!("\"{}\": \"{}\"", esc(k), esc(v)))
            .collect::<Vec<_>>()
            .join(", ")
    };

    format!(
        "{{\n  \"kind\": \"earthmesh_hydro_coast_delivery_package\",\n  \"case_name\": \"{}\",\n  \
         \"recommended_case\": {},\n  \"files\": {{{}}},\n  \"source_files\": {{{}{}\"comparison_reports\": [], \"failed_reports\": []}},\n  \
         \"metrics\": {{\"background_cell_count\": {}, \"river_overlap_cells\": {}, \"coast_overlap_cells\": {}, \
         \"retained_triangles\": {{\"1\": {}, \"2\": {}, \"3\": {}}}}}\n}}\n",
        esc(case_name),
        recommended_json,
        obj_pairs(files),
        obj_pairs(source_files),
        if source_files.is_empty() { "" } else { ", " },
        bg,
        river,
        coast,
        ret[0],
        ret[1],
        ret[2],
    )
}

/// Faithful port of the manifest-assembly step of `write_refinement_delivery_package`:
/// read the eval + ranking JSON and write the delivery-package manifest. (The full
/// end-to-end orchestration also runs complete-cell-mask + leaflet, which depend on
/// the overlay-geojson writers / viz not yet in Rust.)
pub fn write_hydro_delivery_manifest(
    case_name: &str,
    eval_json: impl AsRef<Path>,
    ranking_json: impl AsRef<Path>,
    output_manifest: impl AsRef<Path>,
    files: &[(String, String)],
    source_files: &[(String, String)],
) -> io::Result<()> {
    let eval_root = JsonParser::new(&fs::read_to_string(eval_json.as_ref())?).parse()?;
    let ranking_root = JsonParser::new(&fs::read_to_string(ranking_json.as_ref())?).parse()?;
    let manifest = build_hydro_delivery_manifest_json(
        case_name,
        &eval_root,
        &ranking_root,
        files,
        source_files,
    );
    if let Some(parent) = output_manifest.as_ref().parent() {
        fs::create_dir_all(parent)?;
    }
    fs::write(output_manifest, manifest)
}

// ---- util/hydro_mesh/earthmesh_intersection.py port (cell x corridor overlay) ----

/// Serialize a JsonNode back to compact JSON (object keys sorted, to match Python's
/// sort_keys pass-through of cell properties). Whole-number floats print as integers.
fn json_node_to_string(node: &JsonNode) -> String {
    match node {
        JsonNode::Null => "null".into(),
        JsonNode::Bool(b) => b.to_string(),
        JsonNode::Number(n) => format_coupling_number(*n),
        JsonNode::String(s) => format!("\"{}\"", s.replace('\\', "\\\\").replace('"', "\\\"")),
        JsonNode::Array(items) => format!(
            "[{}]",
            items
                .iter()
                .map(json_node_to_string)
                .collect::<Vec<_>>()
                .join(", ")
        ),
        JsonNode::Object(map) => format!(
            "{{{}}}",
            map.iter()
                .map(|(k, v)| format!(
                    "\"{}\": {}",
                    k.replace('\\', "\\\\").replace('"', "\\\""),
                    json_node_to_string(v)
                ))
                .collect::<Vec<_>>()
                .join(", ")
        ),
    }
}

/// Outer ring(s) of a Polygon / MultiPolygon geometry node as lon/lat point lists.
/// Holes are ignored (the hydro masks are simple polygons).
/// Read all Polygon/MultiPolygon outer rings from a GeoJSON file (e.g. an analysis
/// domain) as lon/lat tuple rings. Used to feed an arbitrary-polygon domain into the
/// intersection writer.
pub fn read_polygon_outer_rings(geojson: impl AsRef<Path>) -> io::Result<Vec<Vec<(f64, f64)>>> {
    let root = JsonParser::new(&fs::read_to_string(geojson.as_ref())?).parse()?;
    let mut rings = Vec::new();
    for feature in geojson_feature_nodes(&root) {
        if let Some(geom) = feature.as_object().and_then(|o| o.get("geometry")) {
            for ring in geometry_outer_rings(geom) {
                if ring.len() >= 3 {
                    rings.push(ring.iter().map(|p| (p.x, p.y)).collect());
                }
            }
        }
    }
    Ok(rings)
}

fn geometry_outer_rings(geometry: &JsonNode) -> Vec<Vec<earthmesh_geometry::Point>> {
    use earthmesh_geometry::Point;
    let obj = geometry.as_object();
    let gtype = obj
        .and_then(|o| o.get("type"))
        .and_then(JsonNode::as_str)
        .unwrap_or("");
    let coords = obj
        .and_then(|o| o.get("coordinates"))
        .and_then(JsonNode::as_array);
    let ring_points = |ring: &JsonNode| -> Vec<Point> {
        ring.as_array()
            .map(|pts| {
                pts.iter()
                    .filter_map(|p| {
                        let a = p.as_array()?;
                        Some(Point::new(a.first()?.as_f64()?, a.get(1)?.as_f64()?))
                    })
                    .collect()
            })
            .unwrap_or_default()
    };
    match gtype {
        "Polygon" => coords
            .and_then(|c| c.first())
            .map(|r| vec![ring_points(r)])
            .unwrap_or_default(),
        "MultiPolygon" => coords
            .map(|polys| {
                polys
                    .iter()
                    .filter_map(|poly| poly.as_array().and_then(|p| p.first()).map(ring_points))
                    .collect()
            })
            .unwrap_or_default(),
        _ => Vec::new(),
    }
}

fn feature_river_class(props: Option<&BTreeMap<String, JsonNode>>) -> String {
    props
        .and_then(|p| {
            p.get("river_class")
                .and_then(JsonNode::as_str)
                .filter(|s| !s.is_empty())
                .or_else(|| p.get("mask_class").and_then(JsonNode::as_str))
        })
        .unwrap_or("")
        .to_string()
}

/// Faithful port of `earthmesh_intersection.py::earthmesh_cells_to_corridor_intersections`
/// (single-Polygon / MultiPolygon outer rings; no holes, no domain clip). Per class, the
/// per-cell overlap area is the SUM of `intersection_area(cell, corridor)` clamped to the
/// cell area — exact when same-class corridors are disjoint (river reaches), which is the
/// realistic case; Python unions same-class corridors first (matters only when they overlap).
#[allow(clippy::too_many_arguments)]
pub fn write_earthmesh_intersection_geojson(
    cell_geojson: impl AsRef<Path>,
    corridor_geojson: impl AsRef<Path>,
    output_geojson: impl AsRef<Path>,
    include_classes: &[String],
    min_fraction: f64,
    unit_sphere_area: bool,
    domain: Option<&[Vec<(f64, f64)>]>,
) -> io::Result<usize> {
    use earthmesh_geometry::{
        clip_convex_polygon, polygon_area, polygon_intersection_pieces, polygon_union_area, Point,
    };
    // Arbitrary-polygon analysis domain (lon/lat tuple rings) -> Point rings.
    let domain_polys: Option<Vec<Vec<Point>>> = domain.map(|polys| {
        polys
            .iter()
            .map(|ring| ring.iter().map(|&(x, y)| Point::new(x, y)).collect())
            .collect()
    });
    if !(0.0..=1.0).contains(&min_fraction) {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "min_fraction must be between 0 and 1",
        ));
    }
    let cells_root = JsonParser::new(&fs::read_to_string(cell_geojson.as_ref())?).parse()?;
    let corridors_root =
        JsonParser::new(&fs::read_to_string(corridor_geojson.as_ref())?).parse()?;
    let included: std::collections::BTreeSet<&str> =
        include_classes.iter().map(|s| s.as_str()).collect();

    // group corridor outer rings by class
    let mut class_rings: BTreeMap<String, Vec<Vec<earthmesh_geometry::Point>>> = BTreeMap::new();
    for feature in geojson_feature_nodes(&corridors_root) {
        let obj = feature.as_object();
        let class = feature_river_class(
            obj.and_then(|o| o.get("properties"))
                .and_then(JsonNode::as_object),
        );
        if class.is_empty() || !included.contains(class.as_str()) {
            continue;
        }
        if let Some(geom) = obj.and_then(|o| o.get("geometry")) {
            for ring in geometry_outer_rings(geom) {
                if ring.len() < 3 {
                    continue;
                }
                match &domain_polys {
                    // optional domain clip: corridor ∩ domain (arbitrary polygons,
                    // exact via triangulation); a piece per domain polygon, deduped
                    // later by the per-cell union.
                    Some(dpolys) => {
                        for dpoly in dpolys {
                            for piece in polygon_intersection_pieces(&ring, dpoly) {
                                class_rings.entry(class.clone()).or_default().push(piece);
                            }
                        }
                    }
                    None => class_rings.entry(class.clone()).or_default().push(ring),
                }
            }
        }
    }

    let esc = |v: &str| v.replace('\\', "\\\\").replace('"', "\\\"");
    let mut features = Vec::new();
    for cell in geojson_feature_nodes(&cells_root) {
        let cell_obj = cell.as_object();
        let Some(geom) = cell_obj.and_then(|o| o.get("geometry")) else {
            continue;
        };
        let cell_rings = geometry_outer_rings(geom);
        if cell_rings.is_empty() {
            continue;
        }
        let cell_area: f64 = cell_rings.iter().map(|r| polygon_area(r)).sum();
        if cell_area <= 0.0 {
            continue;
        }
        let cell_props = cell_obj
            .and_then(|o| o.get("properties"))
            .and_then(JsonNode::as_object);
        let cell_id = cell_props
            .and_then(|p| p.get("cell_id"))
            .map(|n| match n {
                JsonNode::String(s) => s.clone(),
                other => json_node_to_string(other),
            })
            .unwrap_or_default();
        let source_area = cell_props
            .and_then(|p| p.get("source_areaCell"))
            .and_then(JsonNode::as_f64);

        for (class, rings) in &class_rings {
            // area(cell ∩ union(same-class corridors)): clip each corridor to the
            // (convex) cell, then take the exact union area — counts overlap between
            // same-class corridors once (Python unions first; equivalent here).
            let mut clipped: Vec<Vec<earthmesh_geometry::Point>> = Vec::new();
            for cr in &cell_rings {
                for corridor in rings {
                    let piece = clip_convex_polygon(corridor, cr);
                    if piece.len() >= 3 {
                        clipped.push(piece);
                    }
                }
            }
            let inter = polygon_union_area(&clipped).min(cell_area);
            if inter <= 0.0 {
                continue;
            }
            let fraction = inter / cell_area;
            if fraction < min_fraction {
                continue;
            }
            // properties = cell properties (pass-through) + computed keys
            let mut props: BTreeMap<String, String> = BTreeMap::new();
            if let Some(cp) = cell_props {
                for (k, v) in cp {
                    props.insert(k.clone(), json_node_to_string(v));
                }
            }
            props.insert("cell_id".into(), format!("\"{}\"", esc(&cell_id)));
            props.insert("grid_kind".into(), "\"earthmesh_cell_preview\"".into());
            props.insert(
                "corridor_source_geometry".into(),
                "\"earthmesh_cell_intersection_preview\"".into(),
            );
            props.insert("cell_area_deg2".into(), format!("{cell_area}"));
            props.insert("intersection_area_deg2".into(), format!("{inter}"));
            props.insert("overlap_class".into(), format!("\"{}\"", esc(class)));
            props.insert("overlap_fraction".into(), format!("{fraction}"));
            props.insert("domain_clip_applied".into(), "false".into());
            if class.to_ascii_uppercase().starts_with('R') {
                props.insert("river_class".into(), format!("\"{}\"", esc(class)));
                props.insert("river_fraction".into(), format!("{fraction}"));
                if let Some(sa) = source_area {
                    props.insert(
                        "source_estimated_river_area".into(),
                        format!("{}", sa * fraction),
                    );
                    if unit_sphere_area {
                        let norm = sa * HYDRO_EARTH_RADIUS_M * HYDRO_EARTH_RADIUS_M;
                        props.insert(
                            "area_normalization".into(),
                            "\"unit_sphere_area_to_m2\"".into(),
                        );
                        props.insert("normalized_cell_area_m2".into(), format!("{norm}"));
                        props.insert(
                            "estimated_river_area_m2".into(),
                            format!("{}", norm * fraction),
                        );
                    }
                }
            } else {
                props.insert("mask_class".into(), format!("\"{}\"", esc(class)));
                if class == "COAST" || class.starts_with("COAST_") {
                    props.insert("coastal_fraction".into(), format!("{fraction}"));
                }
            }
            let body = props
                .iter()
                .map(|(k, v)| format!("\"{}\": {}", esc(k), v))
                .collect::<Vec<_>>()
                .join(", ");
            features.push(format!(
                "    {{\"type\": \"Feature\", \"geometry\": {}, \"properties\": {{{}}}}}",
                json_node_to_string(geom),
                body
            ));
        }
    }

    let out = format!(
        "{{\n  \"type\": \"FeatureCollection\",\n  \"features\": [\n{}\n  ]\n}}\n",
        features.join(",\n")
    );
    if let Some(parent) = output_geojson.as_ref().parent() {
        fs::create_dir_all(parent)?;
    }
    fs::write(output_geojson, out)?;
    Ok(features.len())
}

// ---- util/hydro_mesh/cell_mask_merge.py port (complete cell mask) ----

fn cell_mask_priority(class: &str) -> i32 {
    match class {
        "R3" => 30,
        "R2" => 20,
        "COAST" => 10,
        _ => 0,
    }
}

fn cell_feature_mask_class(props: Option<&BTreeMap<String, JsonNode>>) -> String {
    let get = |k: &str| props.and_then(|m| m.get(k)).and_then(JsonNode::as_str);
    if let Some(rc) = get("river_class") {
        if rc == "R2" || rc == "R3" {
            return rc.to_string();
        }
    }
    if get("mask_class") == Some("COAST") {
        return "COAST".into();
    }
    if let Some(mc) = get("mask_class") {
        if mc == "LAND" || mc == "OCEAN" {
            return mc.to_string();
        }
    }
    if let Some(sc) = get("surface_class") {
        if sc == "LAND" || sc == "OCEAN" {
            return sc.to_string();
        }
    }
    "BACKGROUND".into()
}

fn surface_class_from_coast(props: Option<&BTreeMap<String, JsonNode>>) -> String {
    let v = props.and_then(|p| {
        p.get("surface_class")
            .or_else(|| p.get("mask_class"))
            .or_else(|| p.get("coast_class"))
            .and_then(JsonNode::as_str)
    });
    match v {
        Some("COAST_LAND") => "LAND".into(),
        Some("COAST_OCEAN") => "OCEAN".into(),
        _ => "BACKGROUND".into(),
    }
}

/// Index sparse overlay features by `cell_id`, keeping the highest-priority per cell
/// (faithful to `_index_best_by_cell`).
fn index_best_by_cell(root: &JsonNode) -> BTreeMap<String, &JsonNode> {
    let mut best: BTreeMap<String, (&JsonNode, i32)> = BTreeMap::new();
    for feature in geojson_feature_nodes(root) {
        let props = feature
            .as_object()
            .and_then(|o| o.get("properties"))
            .and_then(JsonNode::as_object);
        let cell_id = props
            .and_then(|p| p.get("cell_id"))
            .and_then(JsonNode::as_str)
            .unwrap_or("")
            .to_string();
        if cell_id.is_empty() {
            continue;
        }
        let prio = cell_mask_priority(&cell_feature_mask_class(props));
        match best.get(&cell_id) {
            Some((_, p)) if *p >= prio => {}
            _ => {
                best.insert(cell_id, (feature, prio));
            }
        }
    }
    best.into_iter().map(|(k, (f, _))| (k, f)).collect()
}

/// Faithful port of `cell_mask_merge.py::write_complete_cell_mask_geojson`: every
/// background cell annotated with surface_class (max-area LAND/OCEAN overlay) and the
/// dominant mask_class (R3>R2>COAST>LAND/OCEAN/BACKGROUND), merging sparse river/coast
/// overlay properties. Uses `intersection_area` (no shapely).
pub fn write_complete_cell_mask_geojson(
    background_geojson: impl AsRef<Path>,
    output_geojson: impl AsRef<Path>,
    river_geojson: Option<&Path>,
    coast_geojson: Option<&Path>,
    surface_geojson: Option<&Path>,
) -> io::Result<usize> {
    use earthmesh_geometry::{intersection_area, Point};
    let read =
        |p: &Path| -> io::Result<JsonNode> { JsonParser::new(&fs::read_to_string(p)?).parse() };
    let background = read(background_geojson.as_ref())?;
    let river = river_geojson.map(read).transpose()?;
    let coast = coast_geojson.map(read).transpose()?;
    let surface = surface_geojson.map(read).transpose()?;

    let river_by_cell = river.as_ref().map(index_best_by_cell).unwrap_or_default();
    let coast_by_cell = coast.as_ref().map(index_best_by_cell).unwrap_or_default();

    // surface LAND/OCEAN polygons for the max-area classification
    let mut surface_polys: Vec<(String, Vec<Vec<Point>>)> = Vec::new();
    if let Some(surface) = &surface {
        for feature in geojson_feature_nodes(surface) {
            let obj = feature.as_object();
            let props = obj
                .and_then(|o| o.get("properties"))
                .and_then(JsonNode::as_object);
            let class = props
                .and_then(|p| {
                    p.get("surface_class")
                        .or_else(|| p.get("mask_class"))
                        .and_then(JsonNode::as_str)
                })
                .unwrap_or("");
            if class != "LAND" && class != "OCEAN" {
                continue;
            }
            if let Some(geom) = obj.and_then(|o| o.get("geometry")) {
                let rings = geometry_outer_rings(geom);
                if !rings.is_empty() {
                    surface_polys.push((class.to_string(), rings));
                }
            }
        }
    }

    let esc = |v: &str| v.replace('\\', "\\\\").replace('"', "\\\"");
    let mut out_features = Vec::new();
    for base in geojson_feature_nodes(&background) {
        let base_obj = base.as_object();
        let base_props = base_obj
            .and_then(|o| o.get("properties"))
            .and_then(JsonNode::as_object);
        let cell_id = match base_props
            .and_then(|p| p.get("cell_id"))
            .and_then(JsonNode::as_str)
        {
            Some(c) => c.to_string(),
            None => continue, // Python raises; we skip features lacking cell_id
        };
        let Some(geom) = base_obj.and_then(|o| o.get("geometry")) else {
            continue;
        };
        let cell_rings = geometry_outer_rings(geom);

        // surface_class = max-area LAND/OCEAN overlay
        let mut surface_class = "BACKGROUND".to_string();
        if !surface_polys.is_empty() && !cell_rings.is_empty() {
            let mut best_area = 0.0;
            for (class, rings) in &surface_polys {
                let mut area = 0.0;
                for cr in &cell_rings {
                    for sr in rings {
                        area += intersection_area(cr, sr);
                    }
                }
                if area > best_area {
                    best_area = area;
                    surface_class = class.clone();
                }
            }
        }

        let river = river_by_cell.get(&cell_id).copied();
        let coast = coast_by_cell.get(&cell_id).copied();
        let base_class = if surface_class == "LAND" || surface_class == "OCEAN" {
            surface_class.clone()
        } else {
            "BACKGROUND".to_string()
        };
        // candidates max by priority, first-wins on tie (base, coast, river)
        let mut candidates: Vec<String> = vec![base_class];
        if coast.is_some() {
            candidates.push("COAST".into());
        }
        if let Some(r) = river {
            candidates.push(cell_feature_mask_class(
                r.as_object()
                    .and_then(|o| o.get("properties"))
                    .and_then(JsonNode::as_object),
            ));
        }
        let mask_class = candidates
            .iter()
            .cloned()
            .reduce(|a, b| {
                if cell_mask_priority(&b) > cell_mask_priority(&a) {
                    b
                } else {
                    a
                }
            })
            .unwrap_or_else(|| "BACKGROUND".into());

        // merged properties (sorted -> matches Python sort_keys output ordering)
        let mut props: BTreeMap<String, String> = BTreeMap::new();
        if let Some(bp) = base_props {
            for (k, v) in bp {
                props.insert(k.clone(), json_node_to_string(v));
            }
        }
        let mut sources: Vec<&str> = Vec::new();
        let mut surface_class_final = surface_class.clone();
        if surface_class_final != "LAND" && surface_class_final != "OCEAN" {
            surface_class_final = surface_class_from_coast(
                coast
                    .and_then(|c| c.as_object())
                    .and_then(|o| o.get("properties"))
                    .and_then(JsonNode::as_object),
            );
        }
        if surface_class_final == "LAND" || surface_class_final == "OCEAN" {
            props.insert(
                "surface_class".into(),
                format!("\"{}\"", surface_class_final),
            );
            sources.push("surface");
        }
        for (name, overlay) in [("coast", coast), ("river", river)] {
            let Some(ov) = overlay else { continue };
            if let Some(op) = ov
                .as_object()
                .and_then(|o| o.get("properties"))
                .and_then(JsonNode::as_object)
            {
                for (k, v) in op {
                    if k != "mask_class" && k != "surface_class" {
                        props.insert(k.clone(), json_node_to_string(v));
                    }
                }
            }
            sources.push(name);
        }
        let prio = cell_mask_priority(&mask_class);
        props.insert("mask_class".into(), format!("\"{}\"", esc(&mask_class)));
        props.insert(
            "hydro_mask_class".into(),
            format!("\"{}\"", esc(&mask_class)),
        );
        props.insert("mask_priority".into(), prio.to_string());
        props.insert(
            "mask_source".into(),
            format!(
                "\"{}\"",
                if sources.is_empty() {
                    "background".to_string()
                } else {
                    sources.join("+")
                }
            ),
        );
        props.insert(
            "is_hydro_masked".into(),
            (mask_class == "COAST" || mask_class == "R2" || mask_class == "R3").to_string(),
        );

        let body = props
            .iter()
            .map(|(k, v)| format!("\"{}\": {}", esc(k), v))
            .collect::<Vec<_>>()
            .join(", ");
        out_features.push(format!(
            "    {{\"type\": \"Feature\", \"geometry\": {}, \"properties\": {{{}}}}}",
            json_node_to_string(geom),
            body
        ));
    }

    let out = format!(
        "{{\n  \"type\": \"FeatureCollection\",\n  \"features\": [\n{}\n  ]\n}}\n",
        out_features.join(",\n")
    );
    if let Some(parent) = output_geojson.as_ref().parent() {
        fs::create_dir_all(parent)?;
    }
    fs::write(output_geojson, out)?;
    Ok(out_features.len())
}

/// One hydro-mesh QA gate result (faithful to `qa_gates.py::_check`).
#[derive(Debug, Clone)]
pub struct HydroMeshQaCheck {
    pub id: String,
    pub passed: bool,
    pub observed: String,
    pub expected: Option<String>,
}

/// Delivery-package QA report (faithful port of `util/hydro_mesh/qa_gates.py`).
/// Distinct from `earthmesh_quality::coupling` (R7), which validates per-cell coupling;
/// this gates a *delivery package* (mask completeness, known surfaces, non-empty
/// river/coast overlays) before promotion.
#[derive(Debug, Clone)]
pub struct HydroMeshQaReport {
    pub status: String,
    pub background_cell_count: i64,
    pub complete_mask_cell_count: i64,
    pub surface_class_counts: BTreeMap<String, i64>,
    pub river_overlap_cells: i64,
    pub coast_overlap_cells: i64,
    pub min_river_cells: i64,
    pub min_coast_cells: i64,
    pub colm_rows_written: Option<i64>,
    pub checks: Vec<HydroMeshQaCheck>,
}

fn manifest_metric_i64(metrics: Option<&BTreeMap<String, JsonNode>>, key: &str) -> i64 {
    metrics
        .and_then(|m| m.get(key))
        .and_then(JsonNode::as_f64)
        .unwrap_or(0.0) as i64
}

/// Evaluate delivery-package QA gates. Faithful to `qa_gates.py::evaluate_hydro_mesh_qa`.
pub fn evaluate_hydro_mesh_qa(
    delivery_manifest_json: impl AsRef<Path>,
    colm_summary_json: Option<&Path>,
    min_river_cells: i64,
    min_coast_cells: i64,
) -> io::Result<HydroMeshQaReport> {
    let manifest_text = fs::read_to_string(delivery_manifest_json.as_ref())?;
    let manifest = JsonParser::new(&manifest_text).parse()?;
    let manifest_obj = manifest.as_object();
    let metrics = manifest_obj
        .and_then(|m| m.get("metrics"))
        .and_then(JsonNode::as_object);
    let background_count = manifest_metric_i64(metrics, "background_cell_count");
    let river_cells = manifest_metric_i64(metrics, "river_overlap_cells");
    let coast_cells = manifest_metric_i64(metrics, "coast_overlap_cells");

    let complete_mask_path = manifest_obj
        .and_then(|m| m.get("files"))
        .and_then(JsonNode::as_object)
        .and_then(|f| f.get("complete_cell_mask_geojson"))
        .and_then(JsonNode::as_str)
        .filter(|s| !s.is_empty())
        .map(PathBuf::from);

    let mut surface_counts: BTreeMap<String, i64> = BTreeMap::new();
    let mut complete_feature_count: i64 = 0;
    let mut unknown_surface_count: i64 = 0;
    if let Some(path) = &complete_mask_path {
        let text = fs::read_to_string(path)?;
        let root = JsonParser::new(&text).parse()?;
        for feature in geojson_feature_nodes(&root) {
            complete_feature_count += 1;
            let surface = feature
                .as_object()
                .and_then(|o| o.get("properties"))
                .and_then(JsonNode::as_object)
                .and_then(|p| p.get("surface_class"))
                .and_then(JsonNode::as_str)
                .filter(|s| !s.is_empty())
                .unwrap_or("UNKNOWN")
                .to_string();
            if surface != "LAND" && surface != "OCEAN" {
                unknown_surface_count += 1;
            }
            *surface_counts.entry(surface).or_insert(0) += 1;
        }
    }

    let surface_counts_str = format!(
        "{{{}}}",
        surface_counts
            .iter()
            .map(|(k, v)| format!("{k}={v}"))
            .collect::<Vec<_>>()
            .join(", ")
    );
    let mut checks = vec![
        HydroMeshQaCheck {
            id: "complete_mask_present".into(),
            passed: complete_mask_path.is_some(),
            observed: complete_mask_path
                .as_ref()
                .map(|p| p.display().to_string())
                .unwrap_or_default(),
            expected: None,
        },
        HydroMeshQaCheck {
            id: "complete_mask_cell_count_matches_background".into(),
            passed: complete_feature_count == background_count,
            observed: complete_feature_count.to_string(),
            expected: Some(background_count.to_string()),
        },
        HydroMeshQaCheck {
            id: "surface_classes_known".into(),
            passed: unknown_surface_count == 0,
            observed: unknown_surface_count.to_string(),
            expected: Some("0".into()),
        },
        HydroMeshQaCheck {
            id: "land_ocean_both_present".into(),
            passed: surface_counts.get("LAND").copied().unwrap_or(0) > 0
                && surface_counts.get("OCEAN").copied().unwrap_or(0) > 0,
            observed: surface_counts_str,
            expected: Some("{LAND: >0, OCEAN: >0}".into()),
        },
        HydroMeshQaCheck {
            id: "river_cells_present".into(),
            passed: river_cells >= min_river_cells,
            observed: river_cells.to_string(),
            expected: Some(format!(">={min_river_cells}")),
        },
        HydroMeshQaCheck {
            id: "coast_cells_present".into(),
            passed: coast_cells >= min_coast_cells,
            observed: coast_cells.to_string(),
            expected: Some(format!(">={min_coast_cells}")),
        },
    ];

    let mut colm_rows_written = None;
    if let Some(colm_path) = colm_summary_json {
        let text = fs::read_to_string(colm_path)?;
        let colm = JsonParser::new(&text).parse()?;
        let colm_obj = colm.as_object();
        let rows_written = colm_obj
            .and_then(|c| c.get("rows_written"))
            .and_then(JsonNode::as_f64)
            .unwrap_or(0.0) as i64;
        let unknown_colm = colm_obj
            .and_then(|c| c.get("surface_class_counts"))
            .and_then(JsonNode::as_object)
            .and_then(|s| s.get("UNKNOWN"))
            .and_then(JsonNode::as_f64)
            .unwrap_or(0.0) as i64;
        colm_rows_written = Some(rows_written);
        checks.push(HydroMeshQaCheck {
            id: "colm_rows_match_background".into(),
            passed: rows_written == background_count,
            observed: rows_written.to_string(),
            expected: Some(background_count.to_string()),
        });
        checks.push(HydroMeshQaCheck {
            id: "colm_surface_unknown_zero".into(),
            passed: unknown_colm == 0,
            observed: unknown_colm.to_string(),
            expected: Some("0".into()),
        });
    }

    let status = if checks.iter().all(|c| c.passed) {
        "pass"
    } else {
        "fail"
    }
    .to_string();

    Ok(HydroMeshQaReport {
        status,
        background_cell_count: background_count,
        complete_mask_cell_count: complete_feature_count,
        surface_class_counts: surface_counts,
        river_overlap_cells: river_cells,
        coast_overlap_cells: coast_cells,
        min_river_cells,
        min_coast_cells,
        colm_rows_written,
        checks,
    })
}

/// Serialize a [`HydroMeshQaReport`] to JSON (`kind=earthmesh_hydro_mesh_qa_report`).
pub fn hydro_mesh_qa_report_json(report: &HydroMeshQaReport) -> String {
    let esc = |v: &str| v.replace('\\', "\\\\").replace('"', "\\\"");
    let mut s = String::from("{\n  \"kind\": \"earthmesh_hydro_mesh_qa_report\",\n");
    s.push_str(&format!("  \"status\": \"{}\",\n", report.status));
    s.push_str("  \"thresholds\": {\n");
    s.push_str(&format!(
        "    \"min_river_cells\": {},\n    \"min_coast_cells\": {},\n    \"max_unknown_surface_cells\": 0,\n    \"require_land_ocean_both_present\": true\n  }},\n",
        report.min_river_cells, report.min_coast_cells
    ));
    s.push_str("  \"metrics\": {\n");
    s.push_str(&format!(
        "    \"background_cell_count\": {},\n    \"complete_mask_cell_count\": {},\n    \"river_overlap_cells\": {},\n    \"coast_overlap_cells\": {},\n",
        report.background_cell_count,
        report.complete_mask_cell_count,
        report.river_overlap_cells,
        report.coast_overlap_cells
    ));
    let sc = report
        .surface_class_counts
        .iter()
        .map(|(k, v)| format!("\"{}\": {}", esc(k), v))
        .collect::<Vec<_>>()
        .join(", ");
    s.push_str(&format!("    \"surface_class_counts\": {{{sc}}}"));
    if let Some(rows) = report.colm_rows_written {
        s.push_str(&format!(",\n    \"colm_rows_written\": {rows}"));
    }
    s.push_str("\n  },\n  \"checks\": [\n");
    for (i, c) in report.checks.iter().enumerate() {
        let comma = if i + 1 < report.checks.len() { "," } else { "" };
        let expected = c
            .expected
            .as_ref()
            .map(|e| format!(", \"expected\": \"{}\"", esc(e)))
            .unwrap_or_default();
        s.push_str(&format!(
            "    {{\"id\": \"{}\", \"status\": \"{}\", \"observed\": \"{}\"{}}}{}\n",
            esc(&c.id),
            if c.passed { "pass" } else { "fail" },
            esc(&c.observed),
            expected,
            comma
        ));
    }
    s.push_str("  ]\n}\n");
    s
}

/// Faithful port of `qa_gates.py::write_hydro_mesh_qa_report`.
pub fn write_hydro_mesh_qa_report(
    delivery_manifest_json: impl AsRef<Path>,
    output_json: impl AsRef<Path>,
    colm_summary_json: Option<&Path>,
    min_river_cells: i64,
    min_coast_cells: i64,
) -> io::Result<HydroMeshQaReport> {
    let report = evaluate_hydro_mesh_qa(
        delivery_manifest_json,
        colm_summary_json,
        min_river_cells,
        min_coast_cells,
    )?;
    if let Some(parent) = output_json.as_ref().parent() {
        fs::create_dir_all(parent)?;
    }
    fs::write(output_json, hydro_mesh_qa_report_json(&report))?;
    Ok(report)
}

pub fn write_colm_coupling_csv_from_mesh(
    gridfile: impl AsRef<Path>,
    landtype_file: impl AsRef<Path>,
    gridnum_perdegree: usize,
    case_name: &str,
    mode_grid: &str,
    output_csv: impl AsRef<Path>,
) -> io::Result<ColmSurfaceCounts> {
    let mesh = read_unstructured_mesh_netcdf(gridfile)?;
    let centers = match mode_grid.trim() {
        "tri" => &mesh.m_points,
        _ => &mesh.w_points,
    };
    let lt = read_landtype_data_preprocess_fortran_indexed(landtype_file, gridnum_perdegree)?;
    if lt.lon_i.len() < 3 || lt.lat_i.len() < 3 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "land-type axes too short to derive sampling step",
        ));
    }
    let (nlon, nlat) = (lt.nlons_source, lt.nlats_source);
    let lon0 = lt.lon_i[1];
    let lat0 = lt.lat_i[1];
    let dlon = lt.lon_i[2] - lt.lon_i[1];
    let dlat = lt.lat_i[2] - lt.lat_i[1];

    // Nearest source index; longitude wraps the globe, latitude is clamped.
    let sample = |lon: f64, lat: f64| -> i32 {
        let li = (((lon - lon0) / dlon).round() as i64).rem_euclid(nlon as i64);
        let lj = (((lat - lat0) / dlat).round() as i64).clamp(0, nlat as i64 - 1);
        lt.landtypes_global[(li + 1) as usize][(lj + 1) as usize]
    };

    let is_marker = |p: &LonLatPoint| p.lon == 0.0 && p.lat == 0.0;
    let mut counts = ColmSurfaceCounts::default();
    let mut out = String::from(
        "cell_id,cell_index,center_lon,center_lat,surface_class,has_river,river_class,river_fraction,estimated_river_area_m2,has_coast,coast_class,coastal_fraction,normalized_cell_area_m2,source_areaCell\n",
    );
    let mut idx = 0i32;
    for (i, c) in centers.iter().enumerate() {
        if i == 0 || is_marker(c) {
            continue;
        }
        idx += 1;
        let surface = match classify_area_judge_landtype_fortran_indexed(sample(c.lon, c.lat)) {
            AreaJudgeLandtypeClass::Ocean => {
                counts.ocean += 1;
                "OCEAN"
            }
            AreaJudgeLandtypeClass::Land => {
                counts.land += 1;
                "LAND"
            }
        };
        // river/coast columns are [需数据] placeholders until hydro assignment.
        out.push_str(&format!(
            "{case_name}_{idx},{idx},{lon:.6},{lat:.6},{surface},false,none,0.0,0.0,false,none,0.0,0.0,0.0\n",
            lon = c.lon,
            lat = c.lat,
        ));
    }
    if let Some(parent) = output_csv.as_ref().parent() {
        fs::create_dir_all(parent)?;
    }
    fs::write(output_csv, out)?;
    Ok(counts)
}

/// Write the CoLM package coupling metadata NetCDF schema from the package CSV.
///
/// This is a Rust-native equivalent of the numeric/string-code boundary in
/// `util.hydro_mesh.colm_coupling` so v3 hydro/coast package handoffs are not
/// Python-only.
pub fn write_colm_coupling_netcdf_from_csv(
    input_csv: impl AsRef<Path>,
    output_netcdf: impl AsRef<Path>,
    case_name: &str,
    delivery_manifest: impl AsRef<Path>,
) -> io::Result<ColmCouplingNetcdfWriteReport> {
    let rows = read_colm_coupling_csv_rows(input_csv)?;
    let output = output_netcdf.as_ref().to_path_buf();
    if let Some(parent) = output.parent() {
        fs::create_dir_all(parent)?;
    }
    let mut file = netcdf::create(&output).map_err(netcdf_to_io_error)?;
    file.add_dimension("cell", rows.len())
        .map_err(netcdf_to_io_error)?;
    file.add_attribute("kind", "earthmesh_colm_coupling_netcdf")
        .map_err(netcdf_to_io_error)?;
    file.add_attribute("case_name", case_name)
        .map_err(netcdf_to_io_error)?;
    file.add_attribute(
        "delivery_manifest",
        delivery_manifest.as_ref().to_string_lossy().as_ref(),
    )
    .map_err(netcdf_to_io_error)?;
    file.add_attribute(
        "surface_class_code_meanings",
        "0=UNKNOWN 1=LAND 2=OCEAN 3=COAST",
    )
    .map_err(netcdf_to_io_error)?;
    file.add_attribute("river_class_code_meanings", "0=none/R0 1=R1 2=R2 3=R3")
        .map_err(netcdf_to_io_error)?;
    file.add_attribute(
        "coast_class_code_meanings",
        "0=none 1=COAST 2=COAST_LAND 3=COAST_OCEAN",
    )
    .map_err(netcdf_to_io_error)?;

    {
        let mut var = file
            .add_string_variable("cell_id", &["cell"])
            .map_err(netcdf_to_io_error)?;
        for (index, row) in rows.iter().enumerate() {
            var.put_string(&row.cell_id, index)
                .map_err(netcdf_to_io_error)?;
        }
    }
    write_colm_i32_var(
        &mut file,
        "cell_index",
        &rows.iter().map(|row| row.cell_index).collect::<Vec<_>>(),
    )?;
    write_colm_f64_var(
        &mut file,
        "center_lon",
        &rows.iter().map(|row| row.center_lon).collect::<Vec<_>>(),
        Some("degrees_east"),
    )?;
    write_colm_f64_var(
        &mut file,
        "center_lat",
        &rows.iter().map(|row| row.center_lat).collect::<Vec<_>>(),
        Some("degrees_north"),
    )?;
    write_colm_i8_var(
        &mut file,
        "surface_class_code",
        &rows
            .iter()
            .map(|row| surface_class_code(&row.surface_class))
            .collect::<Vec<_>>(),
    )?;
    write_colm_i8_var(
        &mut file,
        "has_river",
        &rows
            .iter()
            .map(|row| i8::from(row.has_river))
            .collect::<Vec<_>>(),
    )?;
    write_colm_i8_var(
        &mut file,
        "river_class_code",
        &rows
            .iter()
            .map(|row| river_class_code(&row.river_class))
            .collect::<Vec<_>>(),
    )?;
    write_colm_f64_var(
        &mut file,
        "river_fraction",
        &rows
            .iter()
            .map(|row| row.river_fraction)
            .collect::<Vec<_>>(),
        Some("1"),
    )?;
    write_colm_f64_var(
        &mut file,
        "estimated_river_area_m2",
        &rows
            .iter()
            .map(|row| row.estimated_river_area_m2)
            .collect::<Vec<_>>(),
        Some("m2"),
    )?;
    write_colm_i8_var(
        &mut file,
        "has_coast",
        &rows
            .iter()
            .map(|row| i8::from(row.has_coast))
            .collect::<Vec<_>>(),
    )?;
    write_colm_i8_var(
        &mut file,
        "coast_class_code",
        &rows
            .iter()
            .map(|row| coast_class_code(&row.coast_class))
            .collect::<Vec<_>>(),
    )?;
    write_colm_f64_var(
        &mut file,
        "coastal_fraction",
        &rows
            .iter()
            .map(|row| row.coastal_fraction)
            .collect::<Vec<_>>(),
        Some("1"),
    )?;
    write_colm_f64_var(
        &mut file,
        "normalized_cell_area_m2",
        &rows
            .iter()
            .map(|row| row.normalized_cell_area_m2)
            .collect::<Vec<_>>(),
        Some("m2"),
    )?;
    write_colm_f64_var(
        &mut file,
        "source_areaCell",
        &rows
            .iter()
            .map(|row| row.source_area_cell)
            .collect::<Vec<_>>(),
        Some("source_areaCell_units from CSV when available"),
    )?;

    Ok(ColmCouplingNetcdfWriteReport {
        output,
        rows: rows.len(),
    })
}

/// Read the surface-class points from a CoLM coupling NetCDF for GUI preview
/// coloring and lightweight inspection.
pub fn read_colm_surface_class_points_netcdf(
    input_netcdf: impl AsRef<Path>,
) -> io::Result<Vec<ColmSurfaceClassPoint>> {
    let file = netcdf::open(input_netcdf.as_ref()).map_err(netcdf_to_io_error)?;
    let lon = required_values_f64(&file, "center_lon")?;
    let lat = required_values_f64(&file, "center_lat")?;
    let code = required_values_i8(&file, "surface_class_code")?;
    if lon.len() != lat.len() || lon.len() != code.len() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "CoLM coupling coordinate/class lengths differ: lon={} lat={} code={}",
                lon.len(),
                lat.len(),
                code.len()
            ),
        ));
    }
    Ok(lon
        .into_iter()
        .zip(lat)
        .zip(code)
        .map(|((lon, lat), code)| ColmSurfaceClassPoint { lon, lat, code })
        .collect())
}

/// Write a small CoLM restart-template handoff from the same package CSV used
/// by the coupling metadata exporter.
///
/// The template keeps EarthMesh hydro/coast fractions in model-ready NetCDF
/// columns so CoLM2024/CoLM20XX adapters can consume a Rust-written restart
/// seed without depending on Python-only postprocessing.
pub fn write_colm_restart_template_netcdf_from_csv(
    input_csv: impl AsRef<Path>,
    output_netcdf: impl AsRef<Path>,
    case_name: &str,
) -> io::Result<ColmRestartTemplateNetcdfWriteReport> {
    let rows = read_colm_coupling_csv_rows(input_csv)?;
    let output = output_netcdf.as_ref().to_path_buf();
    if let Some(parent) = output.parent() {
        fs::create_dir_all(parent)?;
    }
    let mut file = netcdf::create(&output).map_err(netcdf_to_io_error)?;
    file.add_dimension("cell", rows.len())
        .map_err(netcdf_to_io_error)?;
    file.add_attribute("kind", "earthmesh_colm_restart_template_netcdf")
        .map_err(netcdf_to_io_error)?;
    file.add_attribute("case_name", case_name)
        .map_err(netcdf_to_io_error)?;
    file.add_attribute(
        "land_fraction_definition",
        "LAND=1 OCEAN=0 COAST=1-coastal_fraction",
    )
    .map_err(netcdf_to_io_error)?;

    write_colm_i32_var(
        &mut file,
        "cell_index",
        &rows.iter().map(|row| row.cell_index).collect::<Vec<_>>(),
    )?;
    write_colm_f64_var(
        &mut file,
        "center_lon",
        &rows.iter().map(|row| row.center_lon).collect::<Vec<_>>(),
        Some("degrees_east"),
    )?;
    write_colm_f64_var(
        &mut file,
        "center_lat",
        &rows.iter().map(|row| row.center_lat).collect::<Vec<_>>(),
        Some("degrees_north"),
    )?;
    write_colm_f64_var(
        &mut file,
        "land_fraction",
        &rows.iter().map(colm_land_fraction).collect::<Vec<_>>(),
        Some("1"),
    )?;
    write_colm_f64_var(
        &mut file,
        "river_fraction",
        &rows
            .iter()
            .map(|row| row.river_fraction)
            .collect::<Vec<_>>(),
        Some("1"),
    )?;
    write_colm_f64_var(
        &mut file,
        "coastal_fraction",
        &rows
            .iter()
            .map(|row| row.coastal_fraction)
            .collect::<Vec<_>>(),
        Some("1"),
    )?;
    write_colm_f64_var(
        &mut file,
        "normalized_cell_area_m2",
        &rows
            .iter()
            .map(|row| row.normalized_cell_area_m2)
            .collect::<Vec<_>>(),
        Some("m2"),
    )?;

    Ok(ColmRestartTemplateNetcdfWriteReport {
        output,
        rows: rows.len(),
    })
}

/// Write a CoLM forcing-template handoff from the package CSV.
///
/// This converts the EarthMesh surface/hydro/coast fractions into area-weighted
/// model forcing columns so coupled-model adapters have a Rust-owned seed file
/// before full model-specific forcing generation is completed.
pub fn write_colm_forcing_template_netcdf_from_csv(
    input_csv: impl AsRef<Path>,
    output_netcdf: impl AsRef<Path>,
    case_name: &str,
) -> io::Result<ColmForcingTemplateNetcdfWriteReport> {
    let rows = read_colm_coupling_csv_rows(input_csv)?;
    let output = output_netcdf.as_ref().to_path_buf();
    if let Some(parent) = output.parent() {
        fs::create_dir_all(parent)?;
    }
    let mut file = netcdf::create(&output).map_err(netcdf_to_io_error)?;
    file.add_dimension("cell", rows.len())
        .map_err(netcdf_to_io_error)?;
    file.add_attribute("kind", "earthmesh_colm_forcing_template_netcdf")
        .map_err(netcdf_to_io_error)?;
    file.add_attribute("case_name", case_name)
        .map_err(netcdf_to_io_error)?;
    file.add_attribute(
        "area_definition",
        "land_area=normalized_area*land_fraction river_area=estimated_river_area coastal_area=normalized_area*coastal_fraction",
    )
    .map_err(netcdf_to_io_error)?;

    write_colm_i32_var(
        &mut file,
        "cell_index",
        &rows.iter().map(|row| row.cell_index).collect::<Vec<_>>(),
    )?;
    write_colm_f64_var(
        &mut file,
        "center_lon",
        &rows.iter().map(|row| row.center_lon).collect::<Vec<_>>(),
        Some("degrees_east"),
    )?;
    write_colm_f64_var(
        &mut file,
        "center_lat",
        &rows.iter().map(|row| row.center_lat).collect::<Vec<_>>(),
        Some("degrees_north"),
    )?;
    write_colm_f64_var(
        &mut file,
        "land_forcing_area_m2",
        &rows
            .iter()
            .map(|row| row.normalized_cell_area_m2 * colm_land_fraction(row))
            .collect::<Vec<_>>(),
        Some("m2"),
    )?;
    write_colm_f64_var(
        &mut file,
        "river_forcing_area_m2",
        &rows
            .iter()
            .map(|row| finite_or_zero(row.estimated_river_area_m2))
            .collect::<Vec<_>>(),
        Some("m2"),
    )?;
    write_colm_f64_var(
        &mut file,
        "coastal_forcing_area_m2",
        &rows
            .iter()
            .map(|row| row.normalized_cell_area_m2 * row.coastal_fraction.clamp(0.0, 1.0))
            .collect::<Vec<_>>(),
        Some("m2"),
    )?;

    Ok(ColmForcingTemplateNetcdfWriteReport {
        output,
        rows: rows.len(),
    })
}

/// Write the CoLM package delivery manifest tying together Rust-written
/// coupling, restart-template, and forcing-template handoff products.
pub fn write_colm_package_delivery_manifest(
    output_manifest: impl AsRef<Path>,
    case_name: &str,
    rows: usize,
    coupling_netcdf: impl AsRef<Path>,
    restart_template_netcdf: Option<&Path>,
    forcing_template_netcdf: Option<&Path>,
) -> io::Result<PathBuf> {
    let output_manifest = output_manifest.as_ref().to_path_buf();
    if let Some(parent) = output_manifest.parent() {
        fs::create_dir_all(parent)?;
    }
    let mut text = String::from("{\"kind\":\"earthmesh_colm_package_manifest\"");
    text.push_str(",\"case_name\":\"");
    text.push_str(&json_escape_string(case_name));
    text.push('"');
    text.push_str(",\"rows\":");
    text.push_str(&rows.to_string());
    text.push_str(",\"products\":{");
    text.push_str("\"coupling_netcdf\":\"");
    text.push_str(&json_escape_string(
        &coupling_netcdf.as_ref().display().to_string(),
    ));
    text.push('"');
    if let Some(path) = restart_template_netcdf {
        text.push_str(",\"restart_template_netcdf\":\"");
        text.push_str(&json_escape_string(&path.display().to_string()));
        text.push('"');
    }
    if let Some(path) = forcing_template_netcdf {
        text.push_str(",\"forcing_template_netcdf\":\"");
        text.push_str(&json_escape_string(&path.display().to_string()));
        text.push('"');
    }
    text.push_str("}}\n");
    fs::write(&output_manifest, text)?;
    Ok(output_manifest)
}

fn read_colm_coupling_csv_rows(input_csv: impl AsRef<Path>) -> io::Result<Vec<ColmCouplingCsvRow>> {
    let text = fs::read_to_string(input_csv)?;
    let mut lines = text.lines();
    let header = lines
        .next()
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "CoLM coupling CSV is empty"))?;
    let columns = split_simple_csv_line(header);
    let mut rows = Vec::new();
    for (line_index, line) in lines.enumerate() {
        if line.trim().is_empty() {
            continue;
        }
        let values = split_simple_csv_line(line);
        rows.push(ColmCouplingCsvRow {
            cell_id: csv_field(&columns, &values, "cell_id").to_string(),
            cell_index: parse_csv_i32(&columns, &values, "cell_index", line_index + 2)?,
            center_lon: parse_csv_f64(&columns, &values, "center_lon", line_index + 2)?,
            center_lat: parse_csv_f64(&columns, &values, "center_lat", line_index + 2)?,
            surface_class: csv_field(&columns, &values, "surface_class").to_string(),
            has_river: parse_csv_bool(csv_field(&columns, &values, "has_river")),
            river_class: csv_field(&columns, &values, "river_class").to_string(),
            river_fraction: parse_csv_f64(&columns, &values, "river_fraction", line_index + 2)?,
            estimated_river_area_m2: parse_csv_f64(
                &columns,
                &values,
                "estimated_river_area_m2",
                line_index + 2,
            )?,
            has_coast: parse_csv_bool(csv_field(&columns, &values, "has_coast")),
            coast_class: csv_field(&columns, &values, "coast_class").to_string(),
            coastal_fraction: parse_csv_f64(&columns, &values, "coastal_fraction", line_index + 2)?,
            normalized_cell_area_m2: parse_csv_f64(
                &columns,
                &values,
                "normalized_cell_area_m2",
                line_index + 2,
            )?,
            source_area_cell: parse_csv_f64(&columns, &values, "source_areaCell", line_index + 2)?,
        });
    }
    Ok(rows)
}

fn split_simple_csv_line(line: &str) -> Vec<String> {
    line.split(',')
        .map(|part| part.trim().to_string())
        .collect()
}

fn csv_field<'a>(columns: &[String], values: &'a [String], name: &str) -> &'a str {
    columns
        .iter()
        .position(|column| column == name)
        .and_then(|index| values.get(index))
        .map(String::as_str)
        .unwrap_or("")
}

fn parse_csv_i32(
    columns: &[String],
    values: &[String],
    name: &str,
    line_number: usize,
) -> io::Result<i32> {
    csv_field(columns, values, name)
        .parse::<i32>()
        .map_err(|_| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                format!("{name} on CSV line {line_number} must be an integer"),
            )
        })
}

fn parse_csv_f64(
    columns: &[String],
    values: &[String],
    name: &str,
    line_number: usize,
) -> io::Result<f64> {
    let value = csv_field(columns, values, name);
    if value.is_empty() {
        return Ok(f64::NAN);
    }
    value.parse::<f64>().map_err(|_| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            format!("{name} on CSV line {line_number} must be numeric"),
        )
    })
}

fn parse_csv_bool(value: &str) -> bool {
    value.eq_ignore_ascii_case("true") || value == "1"
}

fn surface_class_code(value: &str) -> i8 {
    match value {
        "LAND" => 1,
        "OCEAN" => 2,
        "COAST" => 3,
        _ => 0,
    }
}

fn colm_land_fraction(row: &ColmCouplingCsvRow) -> f64 {
    match row.surface_class.trim().to_ascii_uppercase().as_str() {
        "LAND" => 1.0,
        "OCEAN" => 0.0,
        "COAST" => (1.0 - row.coastal_fraction).clamp(0.0, 1.0),
        _ => 0.0,
    }
}

fn finite_or_zero(value: f64) -> f64 {
    if value.is_finite() {
        value
    } else {
        0.0
    }
}

fn river_class_code(value: &str) -> i8 {
    match value {
        "R1" => 1,
        "R2" => 2,
        "R3" => 3,
        _ => 0,
    }
}

fn coast_class_code(value: &str) -> i8 {
    match value {
        "COAST" => 1,
        "COAST_LAND" => 2,
        "COAST_OCEAN" => 3,
        _ => 0,
    }
}

fn write_colm_i32_var(file: &mut netcdf::FileMut, name: &str, values: &[i32]) -> io::Result<()> {
    let mut var = file
        .add_variable::<i32>(name, &["cell"])
        .map_err(netcdf_to_io_error)?;
    var.put_values(values, ..).map_err(netcdf_to_io_error)
}

fn write_colm_i8_var(file: &mut netcdf::FileMut, name: &str, values: &[i8]) -> io::Result<()> {
    let mut var = file
        .add_variable::<i8>(name, &["cell"])
        .map_err(netcdf_to_io_error)?;
    var.put_values(values, ..).map_err(netcdf_to_io_error)
}

fn write_colm_f64_var(
    file: &mut netcdf::FileMut,
    name: &str,
    values: &[f64],
    units: Option<&str>,
) -> io::Result<()> {
    let mut var = file
        .add_variable::<f64>(name, &["cell"])
        .map_err(netcdf_to_io_error)?;
    if let Some(units) = units {
        var.put_attribute("units", units)
            .map_err(netcdf_to_io_error)?;
    }
    var.put_values(values, ..).map_err(netcdf_to_io_error)
}

/// Rust adapter for `mkgrd.F90:gridfile_write`: derive the unstructured
/// gridfile payload from grid state and write the legacy output path.
pub fn write_gridfile_from_state(
    file_dir: impl AsRef<Path>,
    nxp: usize,
    step: usize,
    mode_grid: &str,
    grid: &GridMemory,
    tabs: &IjTabs,
) -> io::Result<UnstructuredMeshWriteReport> {
    let mesh = gridfile_mesh_from_state(grid, tabs)?;
    let output = gridfile_output_path(file_dir, nxp, step, mode_grid);
    write_unstructured_mesh_netcdf(output, &mesh)
}

/// Rust adapter for `mkgrd.F90:gridfile_write` when upstream kernels keep
/// direct Fortran one-based arrays.
pub fn write_gridfile_from_fortran_indexed_state(
    file_dir: impl AsRef<Path>,
    nxp: usize,
    step: usize,
    mode_grid: &str,
    grid: &GridMemory,
    tabs: &IjTabs,
) -> io::Result<UnstructuredMeshWriteReport> {
    let mesh = gridfile_mesh_from_fortran_indexed_state(grid, tabs)?;
    let output = gridfile_output_path(file_dir, nxp, step, mode_grid);
    write_unstructured_mesh_netcdf(output, &mesh)
}

/// Copy an existing EarthMesh-format mode file into the standard initial gridfile path.
pub fn copy_existing_earthmesh_mode_file(
    mode_file: impl AsRef<Path>,
    file_dir: impl AsRef<Path>,
    nxp: usize,
    mode_grid: &str,
) -> io::Result<UnstructuredMeshWriteReport> {
    let mode_file = mode_file.as_ref();
    let source = netcdf::open(mode_file).map_err(netcdf_to_io_error)?;
    let sjx_points = source
        .dimension("sjx_points")
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "mode_file missing sjx_points"))?
        .len();
    let lbx_points = source
        .dimension("lbx_points")
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "mode_file missing lbx_points"))?
        .len();
    let dimc = source
        .dimension("dimc")
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "mode_file missing dimc"))?
        .len();
    drop(source);

    let output = gridfile_output_path(file_dir, nxp, 1, mode_grid);
    if let Some(parent) = output.parent() {
        fs::create_dir_all(parent)?;
    }
    fs::copy(mode_file, &output)?;
    Ok(UnstructuredMeshWriteReport {
        output,
        sjx_points,
        lbx_points,
        dimc,
    })
}

/// Convert an existing MPAS mesh NetCDF into the EarthMesh unstructured gridfile schema.
///
/// This ports `MOD_file_preprocess.F90:MPAS_Mesh_Read`: MPAS vertices become
/// EarthMesh M points, MPAS cells become W points, connectivity arrays are
/// shifted by one to preserve the legacy placeholder record, and longitudes are
/// converted from radians to degrees in the `[-180, 180]` range.
pub fn convert_mpas_mode_file_to_earthmesh(
    mode_file: impl AsRef<Path>,
    file_dir: impl AsRef<Path>,
    nxp: usize,
    mode_grid: &str,
) -> io::Result<UnstructuredMeshWriteReport> {
    let mode_file = mode_file.as_ref();
    let file = netcdf::open(mode_file).map_err(netcdf_to_io_error)?;
    let n_vertices = required_dimension_len(&file, "nVertices")?;
    let n_cells = required_dimension_len(&file, "nCells")?;
    let max_edges = required_dimension_len(&file, "maxEdges")?;

    let lon_vertex = required_values_f64(&file, "lonVertex")?;
    let lat_vertex = required_values_f64(&file, "latVertex")?;
    let lon_cell = required_values_f64(&file, "lonCell")?;
    let lat_cell = required_values_f64(&file, "latCell")?;
    let cells_on_vertex = required_values_i32_2d(&file, "cellsOnVertex")?;
    let vertices_on_cell = required_values_i32_2d(&file, "verticesOnCell")?;
    let n_edges_on_cell = required_values_i32(&file, "nEdgesOnCell")?;

    require_len("lonVertex", lon_vertex.len(), n_vertices)?;
    require_len("latVertex", lat_vertex.len(), n_vertices)?;
    require_len("lonCell", lon_cell.len(), n_cells)?;
    require_len("latCell", lat_cell.len(), n_cells)?;
    require_len("cellsOnVertex", cells_on_vertex.len(), n_vertices * 3)?;
    require_len(
        "verticesOnCell",
        vertices_on_cell.len(),
        n_cells * max_edges,
    )?;
    require_len("nEdgesOnCell", n_edges_on_cell.len(), n_cells)?;

    let mut m_points = Vec::with_capacity(n_vertices + 1);
    m_points.push(LonLatPoint { lon: 0.0, lat: 0.0 });
    for idx in 0..n_vertices {
        m_points.push(LonLatPoint {
            lon: normalize_degrees(rad_to_deg(lon_vertex[idx])),
            lat: rad_to_deg(lat_vertex[idx]),
        });
    }

    let mut w_points = Vec::with_capacity(n_cells + 1);
    w_points.push(LonLatPoint { lon: 0.0, lat: 0.0 });
    for idx in 0..n_cells {
        w_points.push(LonLatPoint {
            lon: normalize_degrees(rad_to_deg(lon_cell[idx])),
            lat: rad_to_deg(lat_cell[idx]),
        });
    }

    let mut m_to_w = Vec::with_capacity(n_vertices + 1);
    m_to_w.push([1, 1, 1]);
    for vertex in 0..n_vertices {
        let base = vertex * 3;
        m_to_w.push([
            cells_on_vertex[base] + 1,
            cells_on_vertex[base + 1] + 1,
            cells_on_vertex[base + 2] + 1,
        ]);
    }

    let mut w_to_m = Vec::with_capacity(n_cells + 1);
    w_to_m.push(vec![1]);
    for cell in 0..n_cells {
        let base = cell * max_edges;
        w_to_m.push(
            vertices_on_cell[base..base + max_edges]
                .iter()
                .map(|value| value + 1)
                .collect(),
        );
    }

    let mut n_w_to_m = Vec::with_capacity(n_cells + 1);
    n_w_to_m.push(1);
    n_w_to_m.extend(n_edges_on_cell);

    let mesh = UnstructuredMesh {
        m_points,
        w_points,
        m_to_w,
        w_to_m,
        n_w_to_m,
    };
    let output = gridfile_output_path(file_dir, nxp, 1, mode_grid);
    write_unstructured_mesh_netcdf(output, &mesh)
}

/// Convert an existing FVCOM mesh NetCDF into the EarthMesh unstructured gridfile schema.
///
/// This ports `MOD_file_preprocess.F90:FVCOM_Mesh_Read`: FVCOM elements become
/// EarthMesh M points, FVCOM nodes become W points, one placeholder record is
/// retained, connectivity arrays are shifted by one, and longitudes are wrapped
/// into the `[-180, 180]` range before writing the standard gridfile schema.
pub fn convert_fvcom_mode_file_to_earthmesh(
    mode_file: impl AsRef<Path>,
    file_dir: impl AsRef<Path>,
    nxp: usize,
    mode_grid: &str,
) -> io::Result<UnstructuredMeshWriteReport> {
    let mode_file = mode_file.as_ref();
    let file = netcdf::open(mode_file).map_err(netcdf_to_io_error)?;
    let maxelem = required_dimension_len(&file, "maxelem")?;
    let n_nodes = required_dimension_len(&file, "node")?;
    let n_elements = required_dimension_len(&file, "nele")?;
    if maxelem < 7 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "FVCOM maxelem must be at least 7 for EarthMesh dimc",
        ));
    }

    let lonc = required_values_f64(&file, "lonc")?;
    let latc = required_values_f64(&file, "latc")?;
    let lon = required_values_f64(&file, "lon")?;
    let lat = required_values_f64(&file, "lat")?;
    let nv = required_values_i32_matrix(&file, "nv", "nele", "three", n_elements, 3)?;
    let nbve = required_values_i32_matrix(&file, "nbve", "node", "maxelem", n_nodes, maxelem)?;
    let ntve = required_values_i32(&file, "ntve")?;

    require_len("lonc", lonc.len(), n_elements)?;
    require_len("latc", latc.len(), n_elements)?;
    require_len("lon", lon.len(), n_nodes)?;
    require_len("lat", lat.len(), n_nodes)?;
    require_len("ntve", ntve.len(), n_nodes)?;

    let mut m_points = Vec::with_capacity(n_elements + 1);
    m_points.push(LonLatPoint { lon: 0.0, lat: 0.0 });
    for idx in 0..n_elements {
        m_points.push(LonLatPoint {
            lon: normalize_degrees(lonc[idx]),
            lat: latc[idx],
        });
    }

    let mut w_points = Vec::with_capacity(n_nodes + 1);
    w_points.push(LonLatPoint { lon: 0.0, lat: 0.0 });
    for idx in 0..n_nodes {
        w_points.push(LonLatPoint {
            lon: normalize_degrees(lon[idx]),
            lat: lat[idx],
        });
    }

    let mut m_to_w = Vec::with_capacity(n_elements + 1);
    m_to_w.push([1, 1, 1]);
    for element in 0..n_elements {
        let base = element * 3;
        m_to_w.push([nv[base] + 1, nv[base + 1] + 1, nv[base + 2] + 1]);
    }

    let mut w_to_m = Vec::with_capacity(n_nodes + 1);
    w_to_m.push(vec![1; 7]);
    for node in 0..n_nodes {
        let base = node * maxelem;
        w_to_m.push(nbve[base..base + 7].iter().map(|value| value + 1).collect());
    }

    let mut n_w_to_m = Vec::with_capacity(n_nodes + 1);
    n_w_to_m.push(0);
    n_w_to_m.extend(ntve);

    let mesh = UnstructuredMesh {
        m_points,
        w_points,
        m_to_w,
        w_to_m,
        n_w_to_m,
    };
    let output = gridfile_output_path(file_dir, nxp, 1, mode_grid);
    write_unstructured_mesh_netcdf(output, &mesh)
}

/// Read the IAP-Ocean NetCDF payload used by `MOD_file_preprocess.F90:IAP_Mesh_Read`.
pub fn read_iap_mesh_netcdf(inputfile: impl AsRef<Path>) -> io::Result<IapMeshReadPayload> {
    let file = netcdf::open(inputfile.as_ref()).map_err(netcdf_to_io_error)?;
    let source_triangles = required_dimension_len(&file, "sjx_points")?;
    let source_vertices = required_dimension_len(&file, "lbx_points")?;

    let glonw = required_values_f64(&file, "GLONW")?;
    let glatw = required_values_f64(&file, "GLATW")?;
    let source_neighbors = required_values_i32_matrix(
        &file,
        "itab_m%im",
        "sjx_points",
        "dimb",
        source_triangles,
        3,
    )?;
    let source_vertices_on_triangle = required_values_i32_matrix(
        &file,
        "itab_m%iw",
        "sjx_points",
        "dimb",
        source_triangles,
        3,
    )?;

    require_len("GLONW", glonw.len(), source_vertices)?;
    require_len("GLATW", glatw.len(), source_vertices)?;

    let mut w_points = Vec::with_capacity(source_vertices + 1);
    w_points.push(LonLatPoint { lon: 0.0, lat: 0.0 });
    for idx in 0..source_vertices {
        w_points.push(LonLatPoint {
            lon: normalize_degrees(rad_to_deg(glonw[idx])),
            lat: rad_to_deg(glatw[idx]),
        });
    }

    let mut triangle_neighbors = Vec::with_capacity(source_triangles + 1);
    let mut triangle_vertices = Vec::with_capacity(source_triangles + 1);
    triangle_neighbors.push([1, 1, 1]);
    triangle_vertices.push([1, 1, 1]);
    for idx in 0..source_triangles {
        let base = idx * 3;
        triangle_neighbors.push([
            source_neighbors[base] + 1,
            source_neighbors[base + 1] + 1,
            source_neighbors[base + 2] + 1,
        ]);
        triangle_vertices.push([
            source_vertices_on_triangle[base] + 1,
            source_vertices_on_triangle[base + 1] + 1,
            source_vertices_on_triangle[base + 2] + 1,
        ]);
    }

    Ok(IapMeshReadPayload {
        w_points,
        triangle_neighbors,
        triangle_vertices,
    })
}

/// Convert an existing IAP-Ocean-style mesh NetCDF into the EarthMesh gridfile schema.
///
/// This ports the `mkgrd.F90` branch that calls
/// `MOD_grid_preprocess.F90:IAP_Mesh_make`: the source stores W-point
/// coordinates in radians plus M-to-W triangle connectivity.  The Rust path
/// rebuilds M-point spherical circumcenters, derives W-to-M adjacency, preserves
/// the legacy placeholder record, and writes `Unstructured_Mesh_Save` output.
pub fn convert_iap_ocean_mode_file_to_earthmesh(
    mode_file: impl AsRef<Path>,
    file_dir: impl AsRef<Path>,
    nxp: usize,
    mode_grid: &str,
) -> io::Result<UnstructuredMeshWriteReport> {
    let mode_file = mode_file.as_ref();
    let file = netcdf::open(mode_file).map_err(netcdf_to_io_error)?;
    let source_triangles = required_dimension_len(&file, "sjx_points")?;
    let source_vertices = required_dimension_len(&file, "lbx_points")?;
    let fortran_triangles = source_triangles + 1;
    let fortran_vertices = source_vertices + 1;

    let glonw = required_values_f64(&file, "GLONW")?;
    let glatw = required_values_f64(&file, "GLATW")?;
    let _triangles_on_triangle = required_values_i32_matrix(
        &file,
        "itab_m%im",
        "sjx_points",
        "dimb",
        source_triangles,
        3,
    )?;
    let source_m_to_w = required_values_i32_matrix(
        &file,
        "itab_m%iw",
        "sjx_points",
        "dimb",
        source_triangles,
        3,
    )?;

    require_len("GLONW", glonw.len(), source_vertices)?;
    require_len("GLATW", glatw.len(), source_vertices)?;

    let mut w_points_fortran = vec![LonLatDegrees::new(0.0, 0.0); fortran_vertices + 1];
    for source_idx in 0..source_vertices {
        let fortran_idx = source_idx + 2;
        w_points_fortran[fortran_idx] = LonLatDegrees::new(
            normalize_degrees(rad_to_deg(glonw[source_idx])),
            rad_to_deg(glatw[source_idx]),
        );
    }

    let mut m_to_w_fortran = vec![[1_usize, 1, 1]; fortran_triangles + 1];
    for source_idx in 0..source_triangles {
        let fortran_idx = source_idx + 2;
        let base = source_idx * 3;
        m_to_w_fortran[fortran_idx] = [
            usize_from_i32_connectivity(source_m_to_w[base], "itab_m%iw")? + 1,
            usize_from_i32_connectivity(source_m_to_w[base + 1], "itab_m%iw")? + 1,
            usize_from_i32_connectivity(source_m_to_w[base + 2], "itab_m%iw")? + 1,
        ];
    }

    let centroids = centroid_spherical_mesh_fortran_indexed(&w_points_fortran, &m_to_w_fortran)
        .ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "IAP-Ocean triangle connectivity references missing W points",
            )
        })?;
    let mut centroid_xyz = lonlat_points_to_unit_xyz(&centroids);
    let mut vertex_xyz = lonlat_points_to_unit_xyz(&w_points_fortran);
    scale_cartesian_points_by_earth_radius(&mut centroid_xyz);
    scale_cartesian_points_by_earth_radius(&mut vertex_xyz);
    let circumcenters =
        circumcenter_spherical_mesh_fortran_indexed(&centroid_xyz, &vertex_xyz, &m_to_w_fortran)
            .ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "IAP-Ocean spherical circumcenter calculation failed",
                )
            })?;

    let mut m_points_fortran = vec![LonLatDegrees::new(0.0, 0.0); fortran_triangles + 1];
    for fortran_idx in 2..=fortran_triangles {
        m_points_fortran[fortran_idx] = xyz_to_lonlat_degrees(circumcenters[fortran_idx]);
    }

    let mut m_points = Vec::with_capacity(fortran_triangles);
    for fortran_idx in 1..=fortran_triangles {
        let lonlat = m_points_fortran[fortran_idx];
        m_points.push(LonLatPoint {
            lon: lonlat.lon_degrees,
            lat: lonlat.lat_degrees,
        });
    }

    let mut w_points = Vec::with_capacity(fortran_vertices);
    for point in w_points_fortran.iter().take(fortran_vertices + 1).skip(1) {
        w_points.push(LonLatPoint {
            lon: point.lon_degrees,
            lat: point.lat_degrees,
        });
    }

    let m_to_w = (1..=fortran_triangles)
        .map(|idx| {
            [
                m_to_w_fortran[idx][0] as i32,
                m_to_w_fortran[idx][1] as i32,
                m_to_w_fortran[idx][2] as i32,
            ]
        })
        .collect::<Vec<_>>();
    let (w_to_m, n_w_to_m) =
        derive_iap_w_to_m_fortran_indexed(fortran_vertices, &m_to_w_fortran, &m_points_fortran)?;

    let mesh = UnstructuredMesh {
        m_points,
        w_points,
        m_to_w,
        w_to_m,
        n_w_to_m,
    };
    let output = gridfile_output_path(file_dir, nxp, 1, mode_grid);
    write_unstructured_mesh_netcdf(output, &mesh)
}

fn required_dimension_len(file: &netcdf::File, name: &str) -> io::Result<usize> {
    file.dimension(name)
        .map(|dimension| dimension.len())
        .ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                format!("missing {name} dimension"),
            )
        })
}

fn first_existing_dimension_len(file: &netcdf::File, names: &[&str]) -> io::Result<usize> {
    for name in names {
        if let Some(dimension) = file.dimension(name) {
            return Ok(dimension.len());
        }
    }
    Err(io::Error::new(
        io::ErrorKind::InvalidData,
        format!("missing dimension; expected one of {}", names.join(", ")),
    ))
}

fn required_values_f64(file: &netcdf::File, name: &str) -> io::Result<Vec<f64>> {
    file.variable(name)
        .ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                format!("missing {name} variable"),
            )
        })?
        .get_values::<f64, _>(..)
        .map_err(netcdf_to_io_error)
}

fn required_values_f64_any(file: &netcdf::File, name: &str) -> io::Result<Vec<f64>> {
    let variable = file.variable(name).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            format!("missing {name} variable"),
        )
    })?;
    if let Ok(values) = variable.get_values::<f64, _>(..) {
        return Ok(values);
    }
    if let Ok(values) = variable.get_values::<f32, _>(..) {
        return Ok(values.into_iter().map(f64::from).collect());
    }
    Err(io::Error::new(
        io::ErrorKind::InvalidData,
        format!("{name} variable must be readable as f64 or f32"),
    ))
}

fn required_values_f64_any_matrix(
    file: &netcdf::File,
    name: &str,
    outer_len: usize,
    inner_len: usize,
) -> io::Result<Vec<f64>> {
    let variable = file.variable(name).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            format!("missing {name} variable"),
        )
    })?;
    let dimensions = variable.dimensions();
    if dimensions.len() != 2 || dimensions[0].len() != outer_len || dimensions[1].len() != inner_len
    {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!("{name} dimensions must match longitude x latitude"),
        ));
    }
    if let Ok(values) = variable.get_values::<f64, _>((.., ..)) {
        require_len(name, values.len(), outer_len * inner_len)?;
        return Ok(values);
    }
    if let Ok(values) = variable.get_values::<f32, _>((.., ..)) {
        require_len(name, values.len(), outer_len * inner_len)?;
        return Ok(values.into_iter().map(f64::from).collect());
    }
    Err(io::Error::new(
        io::ErrorKind::InvalidData,
        format!("{name} variable must be readable as f64 or f32"),
    ))
}

